// the site timeline (from the Mukhtasar), in order: [title, the book's words, page, place in the timeline]
export const SI=[["مولده صلى الله عليه وسلم بمكة عام الفيل", "ولا خلاف أنه صلى الله عليه وسلم ولد بمكة عام الفيل. وكانت وقعة الفيل تقدمة قدمها الله لنبيه وبيته، وإلا فأهل الفيل نصارى أهل كتاب، دينهم خير من دين أهل مكة. لأنهم عباد أوثان. فنصرهم الله نصرا لا صنع للبشر فيه، تقدمة للنبي الذي أخرجته قريش من مكة، وتعظيما للبلد الحرام.", 51, 0], ["قصة الفيل: بناء أبرهة كنيسة بصنعاء", "وكان سبب قصة أصحاب الفيل - على ما ذكر محمد بن إسحاق - أن أبرهة بن الصباح كان عاملا للنجاشي ملك الحبشة على اليمن، فرأى الناس يتجهزون أيام الموسم إلى مكة - شرفها الله - فبنى كنيسة بصنعاء. وكتب إلى النجاشي \" إني بنيت لك كنيسة لم يبن مثلها، ولست منتهيا حتى أصرف إليها حج العرب \" فسمع به رجل من بني كنانة، فدخلها ليلا. فلطخ قبلتها بالعذرة. فقال أبرهة: من الذي اجترأ على هذا؟ قيل: رجل من أهل ذلك البيت، سمع بالذي قلت. فحلف أبرهة ليسيرن إلى الكعبة حتى يهدمها. وكتب إلى النجاشي يخبره بذلك، فسأله أن يبعث إليه بفيله. وكان له فيل يقال له: محمود، لم ير مثله عظما وجسما وقوة، فبعث به إليه. فخرج أبرهة سائرا إلى مكة. فسمعت العرب بذلك فأعظموه، ورأوا جهاده حقا عليهم.", 51, 1], ["مسير أبرهة إلى مكة لهدم الكعبة", "وكان سبب قصة أصحاب الفيل - على ما ذكر محمد بن إسحاق - أن أبرهة بن الصباح كان عاملا للنجاشي ملك الحبشة على اليمن، فرأى الناس يتجهزون أيام الموسم إلى مكة - شرفها الله - فبنى كنيسة بصنعاء. وكتب إلى النجاشي \" إني بنيت لك كنيسة لم يبن مثلها، ولست منتهيا حتى أصرف إليها حج العرب \" فسمع به رجل من بني كنانة، فدخلها ليلا. فلطخ قبلتها بالعذرة. فقال أبرهة: من الذي اجترأ على هذا؟ قيل: رجل من أهل ذلك البيت، سمع بالذي قلت. فحلف أبرهة ليسيرن إلى الكعبة حتى يهدمها. وكتب إلى النجاشي يخبره بذلك، فسأله أن يبعث إليه بفيله. وكان له فيل يقال له: محمود، لم ير مثله عظما وجسما وقوة، فبعث به إليه. فخرج أبرهة سائرا إلى مكة. فسمعت العرب بذلك فأعظموه، ورأوا جهاده حقا عليهم.", 51, 2], ["قتال ذي نفر أبرهة وأسره", "فخرج ملك من ملوك اليمن، يقال له: ذو نفر. فقاتله. فهزمه أبرهة وأخذه أسيرا، فقال: أيها الملك استبقني خيرا لك، فاستبقاه وأوثقه.", 52, 3], ["قتال نفيل بن حبيب الخثعمي أبرهة وأسره", "وكان أبرهة رجلا حليما. فسار حتى إذا دنا من بلاد خثعم خرج إليه نفيل بن حبيب الخثعمي، ومن اجتمع إليه من قبائل العرب. فقاتلوهم فهزمهم أبرهة. فأخذ نفيلا، فقال له: أيها الملك إنني دليلك بأرض العرب، وهاتان يداي على قومي بالسمع والطاعة. فاستبقني خيرا لك. فاستبقاه. وخرج معه يدله على الطريق.", 52, 4], ["ثقيف تبعث أبا رغال دليلا وموته بالمغمس", "فلما مر بالطائف خرج إليه مسعود بن معتب في رجال من ثقيف. فقال له: أيها الملك، نحن عبيدك. ونحن نبعث معك من يدلك. فبعثوا معه بأبي رغال مولى لهم. فخرج حتى إذا كان بالمغمس مات أبو رغال، وهو الذي يرجم قبره. وبعث أبرهة رجلا من الحبشة - يقال له: الأسود بن مفصود - على مقدمة خيله وأمر بالغارة على نعم الناس. فجمع الأسود إليه أموال الحرم، وأصاب لعبد المطلب مائتي بعير.", 52, 5], ["غارة الأسود بن مفصود على أموال الحرم", "فلما مر بالطائف خرج إليه مسعود بن معتب في رجال من ثقيف. فقال له: أيها الملك، نحن عبيدك. ونحن نبعث معك من يدلك. فبعثوا معه بأبي رغال مولى لهم. فخرج حتى إذا كان بالمغمس مات أبو رغال، وهو الذي يرجم قبره. وبعث أبرهة رجلا من الحبشة - يقال له: الأسود بن مفصود - على مقدمة خيله وأمر بالغارة على نعم الناس. فجمع الأسود إليه أموال الحرم، وأصاب لعبد المطلب مائتي بعير.", 52, 6], ["لقاء عبد المطلب أبرهة", "وكان عبد المطلب رجلا جسيما وسيما. فلما رآه أبرهة أعظمه وأكرمه. وكره أن يجلس معه على سريره. وأن يجلس تحته. فهبط إلى البساط فدعاه فأجلسه معه. فطلب منه أن يرد عليه مائتي البعير التي أصابها من ماله.", 53, 7], ["رد الإبل على عبد المطلب وتحرز قريش في الشعاب", "ثم خرج وأخبر قريشا الخبر، وأمرهم أن يتفرقوا في الشعاب، ويتحرزوا في رءوس الجبال، خوفا عليهم من معرة الجيش.", 54, 8], ["بروك الفيل وإرسال الطير على جيش أبرهة", "ثم توجه في بعض تلك الوجوه مع قومه. وأصبح أبرهة بالمغمس قد تهيأ للدخول. وعبأ جيشه. وهيأ فيه. فأقبل نفيل إلى الفيل. فأخذ بأذنه. فقال: ابرك محمود. فإنك في بلد الله الحرام. فبرك الفيل، فبعثوه فأبى. فوجهوه إلى اليمن، فقام يهرول. ووجهوه إلى الشام ففعل مثل ذلك. ووجهوه إلى المشرق ففعل ذلك. فصرفوه إلى الحرم فبرك. وخرج نفيل يشتد حتى صعد الجبل، فأرسل الله طيرا من قبل البحر مع كل طائر ثلاثة أحجار. حجرين في رجليه وحجرا في منقاره. فلما غشيت القوم أرسلتها عليهم. فلم تصب تلك الحجارة أحدا إلا هلك. وليس كل القوم أصابت. فخرج البقية هاربين يسألون عن نفيل ليدلهم على الطريق إلى اليمن. فماج بعضهم في بعض. يتساقطون بكل طريق، ويهلكون على كل منهل. وبعث الله على أبرهة داء في جسده. فجعلت تساقط أنامله حتى انتهى إلى صنعاء وهو مثل الفرخ. وما مات حتى انصدع صدره عن قلبه ثم هلك.", 54, 9], ["هلاك أبرهة", "ثم توجه في بعض تلك الوجوه مع قومه. وأصبح أبرهة بالمغمس قد تهيأ للدخول. وعبأ جيشه. وهيأ فيه. فأقبل نفيل إلى الفيل. فأخذ بأذنه. فقال: ابرك محمود. فإنك في بلد الله الحرام. فبرك الفيل، فبعثوه فأبى. فوجهوه إلى اليمن، فقام يهرول. ووجهوه إلى الشام ففعل مثل ذلك. ووجهوه إلى المشرق ففعل ذلك. فصرفوه إلى الحرم فبرك. وخرج نفيل يشتد حتى صعد الجبل، فأرسل الله طيرا من قبل البحر مع كل طائر ثلاثة أحجار. حجرين في رجليه وحجرا في منقاره. فلما غشيت القوم أرسلتها عليهم. فلم تصب تلك الحجارة أحدا إلا هلك. وليس كل القوم أصابت. فخرج البقية هاربين يسألون عن نفيل ليدلهم على الطريق إلى اليمن. فماج بعضهم في بعض. يتساقطون بكل طريق، ويهلكون على كل منهل. وبعث الله على أبرهة داء في جسده. فجعلت تساقط أنامله حتى انتهى إلى صنعاء وهو مثل الفرخ. وما مات حتى انصدع صدره عن قلبه ثم هلك.", 54, 10], ["وفاة عبد الله والد رسول الله ﷺ", "قد اختلف في وفاة أبيه: هل توفي بعد ولادته أو قبلها؛ الأكثر: على أنه توفي وهو حمل. ولا خلاف أن أمه ماتت بين مكة والمدينة بالأبواء، منصرفها من المدينة من زيارة أخواله. ولم يستكمل إذ ذاك ست سنين.", 55, 11], ["وفاة أمه بالأبواء", "قد اختلف في وفاة أبيه: هل توفي بعد ولادته أو قبلها؛ الأكثر: على أنه توفي وهو حمل. ولا خلاف أن أمه ماتت بين مكة والمدينة بالأبواء، منصرفها من المدينة من زيارة أخواله. ولم يستكمل إذ ذاك ست سنين.", 55, 12], ["كفالة جده عبد المطلب له", "فكفله جده عبد المطلب. ورق عليه رقة لم يرقها على أولاده. فكان لا يفارقه. وما كان أحد من ولده يجلس على فراشه - إجلالا له - إلا رسول الله صلى الله عليه وسلم.", 55, 13], ["قول القافة من بني مدلج فيه", "وقدم مكة قوم من بني مدلج من القافة. فلما نظروا إليه قالوا لجده: احتفظ به. فلم نجد قدما أشبه بالقدم الذي في المقام من قدمه. فقال لأبي طالب: اسمع ما يقول هؤلاء، واحتفظ به.", 55, 14], ["وفاة جده عبد المطلب ووصيته به إلى أبي طالب", "وتوفي جده في السنة الثامنة من مولده. وأوصى به إلى أبي طالب. وقيل إنه قال له:", 55, 15], ["استشهاد عبد الله بن الزبير بن عبد المطلب بأجنادين", "ومنهم: الزبير بن عبد المطلب شقيق عبد الله. وكان رئيس بني هاشم وبني المطلب في حرب الفجار، شريفا شاعرا. ولم يدرك الإسلام. وأسلم من أولاده: عبد الله، واستشهد بأجنادين، وضباعة، ومجل، وصفية، وعاتكة.", 56, 16], ["موت أبي لهب عقيب بدر", "ومنهم: أبو لهب مات عقيب بدر. وله من الولد: عتيبة الذي دعا عليه النبي صلى الله عليه وسلم فقتله السبع. وله عتبة، ومعتب. أسلما يوم الفتح. ومن بناته: أروى. تزوجها كرز بن ربيعة بن حبيب بن عبد شمس، فولدت له عامرا وأروى. فتزوج أروى عفان بن أبي العاص بن أمية. فولدت له عثمان، ثم خلف عليها عقبة بن أبي معيط، فولدت له الوليد بن عقبة، وعاشت إلى خلافة ابنها عثمان.", 56, 17], ["دعاء النبي ﷺ على عتيبة بن أبي لهب وقتل السبع له", "ومنهم: أبو لهب مات عقيب بدر. وله من الولد: عتيبة الذي دعا عليه النبي صلى الله عليه وسلم فقتله السبع. وله عتبة، ومعتب. أسلما يوم الفتح. ومن بناته: أروى. تزوجها كرز بن ربيعة بن حبيب بن عبد شمس، فولدت له عامرا وأروى. فتزوج أروى عفان بن أبي العاص بن أمية. فولدت له عثمان، ثم خلف عليها عقبة بن أبي معيط، فولدت له الوليد بن عقبة، وعاشت إلى خلافة ابنها عثمان.", 56, 18], ["إسلام عتبة ومعتب ابني أبي لهب يوم الفتح", "ومنهم: أبو لهب مات عقيب بدر. وله من الولد: عتيبة الذي دعا عليه النبي صلى الله عليه وسلم فقتله السبع. وله عتبة، ومعتب. أسلما يوم الفتح. ومن بناته: أروى. تزوجها كرز بن ربيعة بن حبيب بن عبد شمس، فولدت له عامرا وأروى. فتزوج أروى عفان بن أبي العاص بن أمية. فولدت له عثمان، ثم خلف عليها عقبة بن أبي معيط، فولدت له الوليد بن عقبة، وعاشت إلى خلافة ابنها عثمان.", 56, 19], ["منام عاتكة بنت عبد المطلب قبل بدر", "ومنهن: عاتكة أم عبد الله بن أبي أمية. وهي صاحبة المنام قبل يوم بدر. واختلف في إسلامها.", 57, 20], ["موت هاشم بغزة وولادة عبد المطلب", "وأم عبد المطلب: هي سلمى بنت زيد من بني النجار، تزوجها أبوه هاشم بن عبد مناف. فخرج إلى الشام - وهي عند أهلها، وقد حملت بعبد المطلب - فمات بغزة. فرجع أبو رهم بن عبد العزى وأصحابه إلى المدينة بتركته. وولدت امرأته سلمى: عبد المطلب. وسمته شيبة الحمد. فأقام في أخواله مكرما. فبينما هو يناضل الصبيان، فيقول: أنا ابن هاشم، سمعه رجل من قريش، فقال لعمه المطلب: إني مررت بدور بني قيلة. فرأيت غلاما يعتزي إلى أخيك. وما ينبغي ترك مثله في الغربة. فرحل إلى المدينة في طلبه. فلما رآه فاضت عيناه، وضمه إليه. وأنشد شعرا:", 57, 21], ["قدوم المطلب بشيبة (عبد المطلب) إلى مكة", "فأردفه على راحلته، فقال: يا عم، ذلك إلى الوالدة. فجاء إلى أمه. فسألها أن ترسل به معه، فامتنعت. فقال لها: إنما يمضي إلى ملك أبيه، وإلى حرم الله. فأذنت له. فقدم به مكة، فقال الناس: هذا عبد المطلب. فقال: ويحكم إنما هو ابن أخي هاشم.", 57, 22], ["تسليم المطلب ملك هاشم إلى عبد المطلب", "فأقام عنده حتى ترعرع. فسلم إليه ملك هاشم: من أمر البيت، والرفادة، والسقاية، وأمر الحجيج، وغير ذلك.", 58, 23], ["عقد المطلب الحلف بين قريش والنجاشي", "وكان المطلب شريفا مطاعا جوادا، وكانت قريش تسميه الفياض لسخائه. وهو الذي عقد الحلف بين قريش وبين النجاشي. وله من الولد: الحارث، ومخرمة، وعباد، وأنيس، وأبو عمر، وأبو رهم، وغيرهم.", 58, 24], ["غصب نوفل أركاح شيبة بعد موت المطلب", "ولما مات وثب نوفل بن عبد مناف على أركاح (1) شيبة. فغصبه إياها، فسأل رجالا من قريش النصرة على عمه. فقالوا: لا ندخل بينك وبين عمك. فكتب إلى أخواله من بني النجار أبياتا، منها:", 58, 25], ["نصرة أبي سعد بن عدي لعبد المطلب ورد أركاحه", "فاستنفروا وامنعوا ضيم ابن أختكم ... لا تخذلوه فما أنتم بخذالي فلما وقف خاله أبو سعد بن عدي بن النجار على كتابه بكى. وسار من المدينة في ثمانين راكبا، حتى قدم مكة. فنزل بالأبطح فتلقاه عبد المطلب وقال: المنزل يا خال. فقال: لا والله حتى ألقى نوفلا. فقال: تركته بالحجر جالسا في مشايخ قومه. فأقبل أبو سعد حتى وقف عليهم. فقام نوفل قائما، فقال: يا أبا سعد، أنعم صباحا. فقال: لا أنعم الله لك صباحا، وسل سيفه. وقال: ورب هذا البيت، لئن لم ترد على ابن أختي أركاحه لأمكنن منك هذا السيف. فقال: رددتها عليه. فأشهد عليه مشايخ قريش. ثم نزل على شيبة، فأقام عنده ثلاثا. ثم اعتمر ورجع إلى المدينة. فقال عبد المطلب:", 58, 26], ["تحالف نوفل وبني عبد شمس، وبني هاشم وخزاعة", "فلما جرى ذلك حالف نوفل بني عبد شمس بن عبد مناف على بني هاشم، وحالفت بنو هاشم: خزاعة على بني عبد شمس ونوفل. فكان ذلك سببا لفتح مكة. كما سيأتي.", 59, 27], ["تحالف خزاعة في دار الندوة", "فلما رأت خزاعة نصر بني النجار لعبد المطلب، قالوا: نحن ولدناه كما ولدتموه، فنحن أحق بنصره. وذلك أن أم عبد مناف منهم. فدخلوا دار الندوة وتحالفوا وكتبوا بينهم كتابا.", 59, 28], ["غلبة خزاعة جرهما ونفيها من مكة", "وسبب ذلك: أن عبد المطلب أمر في المنام بحفر زمزم. ووصف له موضعها. وكانت جرهم قد غلبت آل إسماعيل على مكة، وملكوها زمانا طويلا. ثم أفسدوا في حرم الله. فوقع بينهم وبين خزاعة حرب، وخزاعة من قبائل اليمن، من أهل سبأ. ولم يدخل بينهم بنو إسماعيل. فغلبتهم خزاعة. ونفت جرهما من مكة. وكانت جرهم قد دفنت الحجر الأسود، والمقام وبئر زمزم. وظهر بعد ذلك قصي بن كلاب على مكة. ورجع إليه ميراث قريش. فأنزل بعضهم داخل مكة - وهم قريش الأباطح - وبعضهم خارجها - وهم قريش الظواهر - فبقيت زمزم مدفونة إلى عصر عبد المطلب. فرأى في المنام موضعها. فقام يحفر. فوجد فيها سيوفا مدفونة وحليا، وغزالا من ذهب مشنفا بالدر. فعلقه عبد المطلب على الكعبة. وليس مع عبد المطلب إلا ولده الحارث. فنازعته قريش، وقالوا له: أشركنا، فقال: ما أنا بفاعل. هذا أمر خصصت به. فاجعلوا بيني وبينكم من شئتم أحاكمكم إليه.", 60, 29], ["ظهور قصي بن كلاب على مكة", "وسبب ذلك: أن عبد المطلب أمر في المنام بحفر زمزم. ووصف له موضعها. وكانت جرهم قد غلبت آل إسماعيل على مكة، وملكوها زمانا طويلا. ثم أفسدوا في حرم الله. فوقع بينهم وبين خزاعة حرب، وخزاعة من قبائل اليمن، من أهل سبأ. ولم يدخل بينهم بنو إسماعيل. فغلبتهم خزاعة. ونفت جرهما من مكة. وكانت جرهم قد دفنت الحجر الأسود، والمقام وبئر زمزم. وظهر بعد ذلك قصي بن كلاب على مكة. ورجع إليه ميراث قريش. فأنزل بعضهم داخل مكة - وهم قريش الأباطح - وبعضهم خارجها - وهم قريش الظواهر - فبقيت زمزم مدفونة إلى عصر عبد المطلب. فرأى في المنام موضعها. فقام يحفر. فوجد فيها سيوفا مدفونة وحليا، وغزالا من ذهب مشنفا بالدر. فعلقه عبد المطلب على الكعبة. وليس مع عبد المطلب إلا ولده الحارث. فنازعته قريش، وقالوا له: أشركنا، فقال: ما أنا بفاعل. هذا أمر خصصت به. فاجعلوا بيني وبينكم من شئتم أحاكمكم إليه.", 60, 30], ["حفر عبد المطلب زمزم", "وسبب ذلك: أن عبد المطلب أمر في المنام بحفر زمزم. ووصف له موضعها. وكانت جرهم قد غلبت آل إسماعيل على مكة، وملكوها زمانا طويلا. ثم أفسدوا في حرم الله. فوقع بينهم وبين خزاعة حرب، وخزاعة من قبائل اليمن، من أهل سبأ. ولم يدخل بينهم بنو إسماعيل. فغلبتهم خزاعة. ونفت جرهما من مكة. وكانت جرهم قد دفنت الحجر الأسود، والمقام وبئر زمزم. وظهر بعد ذلك قصي بن كلاب على مكة. ورجع إليه ميراث قريش. فأنزل بعضهم داخل مكة - وهم قريش الأباطح - وبعضهم خارجها - وهم قريش الظواهر - فبقيت زمزم مدفونة إلى عصر عبد المطلب. فرأى في المنام موضعها. فقام يحفر. فوجد فيها سيوفا مدفونة وحليا، وغزالا من ذهب مشنفا بالدر. فعلقه عبد المطلب على الكعبة. وليس مع عبد المطلب إلا ولده الحارث. فنازعته قريش، وقالوا له: أشركنا، فقال: ما أنا بفاعل. هذا أمر خصصت به. فاجعلوا بيني وبينكم من شئتم أحاكمكم إليه.", 60, 31], ["نذر عبد المطلب وفداء عبد الله بمائة من الإبل", "فنذر حينئذ عبد المطلب: لئن آتاه الله عشرة أولاد، وبلغوا أن يمنعوه لينحرن أحدهم عند الكعبة. فلما تموا عشرة. وعرف أنهم يمنعونه أخبرهم بنذره فأطاعوه. وكتب كل منهم اسمه في قدح. وأعطوها القداح قيم هبل - وكان الذي يجيل القداح - فخرج القدح على عبد الله. وأخذ عبد المطلب المدية ليذبحه. فقامت إليه قريش من ناديها فمنعوه. فقال: كيف أصنع بنذري؟ فأشاروا عليه أن ينحر مكانه عشرا من الإبل. فأقرع بين عبد الله وبينها. فوقعت القرعة عليه. فاغتم عبد المطلب، ثم لم يزل يزيد عشرا عشرا، ولا تقع القرعة إلا عليه، إلى أن بلغ مائة، فوقعت القرعة على الإبل. فنحرت عنه. فجرت سنة.", 60, 32], ["جريان الدية مائة من الإبل", "ثم ترك عبد المطلب الإبل لا يرد عنها إنسانا ولا سبعا. فجرت الدية في قريش والعرب مائة من الإبل. . وأقرها رسول الله صلى الله عليه وسلم. وقالت صفية بنت عبد المطلب:", 61, 33], ["كفالة أبي طالب لرسول الله ﷺ", "قال الواقدي: قام أبو طالب - من سنة ثمان من مولد رسول الله صلى الله عليه وسلم إلى السنة العاشرة من النبوة أي ثلاثا وأربعين - يحوطه ويقوم بأمره، ويذب عنه. ويلطف به. وقال أبو محمد بن قدامة: كان يقر بنبوة النبي صلى الله عليه وسلم. وله في ذلك أشعار، منها:", 61, 34], ["وفاة أبي طالب على ملة عبد المطلب", "ولكنه أبى أن يدين بذلك خشية العار. ولما حضرته الوفاة: «دخل عليه رسول الله صلى الله عليه وسلم - وعنده أبو جهل، وعبد الله بن أبي أمية - فقال: \"يا عم قل: لا إله إلا الله، كلمة أحاج لك بها عند الله\" فقالا له: أترغب عن ملة عبد المطلب؟ فلم يزل صلى الله عليه وسلم يرددها عليه، وهما يرددان عليه حتى كان آخر كلمة قالها: \"هو على ملة عبد المطلب \" فقال رسول الله صلى الله عليه وسلم: لأستغفرن لك ما لم أنه عنك فأنزل الله تعالى: {ما كان للنبي والذين آمنوا أن يستغفروا للمشركين ولو كانوا أولي قربى من بعد ما تبين لهم أنهم أصحاب الجحيم} [التوبة: 113] (1) ونزل قوله تعالى: {إنك لا تهدي من أحببت ولكن الله يهدي من يشاء} [القصص: 56] » (2) الآية (3) .", 62, 35], ["خروج طالب بن أبي طالب يوم بدر وفقده", "فأما طالب: فأخرجه المشركون يوم بدر كرها. فلما انهزم الكفار طلب، فلم يوجد في القتلى، ولا في الأسرى، ولا رجع إلى مكة، وليس له عقب.", 63, 36], ["أسر عقيل يوم بدر وفداء العباس له", "وأما عقيل: فأسر ذلك اليوم. ولم يكن له مال. ففداه عمه العباس.", 63, 37], ["هجرة عقيل إلى المدينة وشهوده مؤتة", "ثم رجع إلى مكة. فأقام بها إلى السنة الثامنة. ثم هاجر إلى المدينة. فشهد مؤتة مع أخيه جعفر. وهو الذي قال فيه النبي صلى الله عليه وسلم: «وهل ترك لنا عقيل من منزل؟» (1) .", 63, 38], ["خروجه مع أبي طالب إلى الشام ولقاء بحيرى", "واستمرت كفالة أبي طالب لرسول الله صلى الله عليه وسلم - كما ذكرنا - فلما بلغ اثنتي عشرة سنة - وقيل: تسعا خرج به أبو طالب إلى الشام في تجارة، فرآه بحيرى الراهب، وأمر عمه أن لا يقدم به إلى الشام؛ خوفا عليه من اليهود. فبعثه عمه مع بعض غلمانه إلى المدينة.", 63, 39], ["خروجه إلى الشام في تجارة لخديجة", "فلما بلغ رسول الله صلى الله عليه وسلم خمسا وعشرين سنة: خرج إلى الشام في تجارة لخديجة رضي الله عنها، ومعه ميسرة غلامها. فوصل بصرى.", 64, 40], ["زواجه خديجة بنت خويلد", "ثم رجع فتزوج عقب رجوعه خديجة بنت خويلد. وهي أول امرأة تزوجها، وأول امرأة ماتت من نسائه. ولم ينكح عليها غيرها. وأمره جبريل: \" أن يقرأ عليها السلام من ربها ويبشرها ببيت في الجنة من قصب \".", 64, 41], ["تحنثه في غار حراء", "ثم حبب إليه الخلاء، والتعبد لربه، فكان يخلو بغار حراء يتعبد فيه (1) وبغضت إليه الأوثان ودين قومه. فلم يكن شيء أبغض إليه من ذلك. وأنبته الله نباتا حسنا، حتى كان أفضل قومه مروءة، وأحسنهم خلقا، وأعزهم جوارا، وأعظمهم حلما، وأصدقهم حديثا. وأحفظهم لأمانة. حتى سماه قومه \" الأمين \" لما جمع الله فيه من الأحوال الصالحة، والخصال الكريمة المرضية.", 64, 42], ["بناء قريش الكعبة", "ولما بلغ رسول الله صلى الله عليه وسلم خمسا وثلاثين سنة: قامت قريش في بناء الكعبة حين تضعضعت.", 65, 43], ["سرقة كنز الكعبة", "قال ابن إسحاق: ولما بلغ رسول الله صلى الله عليه وسلم خمسا وثلاثين سنة، جمعت قريش لبنيان الكعبة. وكانوا يهمون بذلك ليسقفوها، ويهابون هدمها، وإنما كانت رضما فوق القامة. فأرادوا رفعها وتسقيفها. وذلك أن قوما سرقوا كنز الكعبة. وكان في بئر في جوف الكعبة. وكان البحر قد رمى سفينة إلى جدة لرجل من تجار الروم، فتحطمت. فأخذوا خشبها فأعدوه لسقفها.", 65, 44], ["تحطم سفينة الرومي بجدة وأخذ خشبها لسقف الكعبة", "قال ابن إسحاق: ولما بلغ رسول الله صلى الله عليه وسلم خمسا وثلاثين سنة، جمعت قريش لبنيان الكعبة. وكانوا يهمون بذلك ليسقفوها، ويهابون هدمها، وإنما كانت رضما فوق القامة. فأرادوا رفعها وتسقيفها. وذلك أن قوما سرقوا كنز الكعبة. وكان في بئر في جوف الكعبة. وكان البحر قد رمى سفينة إلى جدة لرجل من تجار الروم، فتحطمت. فأخذوا خشبها فأعدوه لسقفها.", 65, 45], ["اختطاف الطائر حية الكعبة", "وكان بمكة رجل قبطي نجار. فهيأ لهم بعض ما كان يصلحها. وكانت حية تخرج من بئر الكعبة التي كان يطرح فيه ما يهدى لها كل يوم، فتتشرق على جدار الكعبة، وكانت مما يهابون. وذلك أنه كان لا يدنو منها أحد إلا احزألت وكشت وفتحت فاها. فبينما هي ذات يوم تتشرق على جدار الكعبة، بعث الله إليها طائرا فاختطفها. فذهب بها. فقالت قريش: إنا لنرجو أن يكون الله قد رضي ما أردنا، عندنا عامل رفيق، وعندنا خشب. وقد كفانا الله الحية.", 66, 46], ["وثوب الحجر من يد أبي وهب المخزومي", "فلما أجمعوا أمرهم في هدمها وبنائها: قام أبو وهب بن عمرو بن عائذ المخزومي فتناول من الكعبة حجرا. فوثب من يده حتى رجع إلى موضعه، فقال: يا معشر قريش، لا تدخلوا في بنيانها من كسبكم إلا طيبا، لا يدخل فيها مهر بغي، ولا بيع ربا، ولا مظلمة أحد من الناس.", 66, 47], ["بدء الوليد بن المغيرة هدم الكعبة", "ثم إن الناس هابوا هدمها، فقال الوليد بن المغيرة: أنا أبدؤكم في هدمها، فأخذ المعول. ثم قام عليها. وهو يقول: اللهم لا ترع - أو: لم نزغ - اللهم إنا لا نريد إلا الخير. ثم هدم من ناحية الركنين. فتربص الناس تلك الليلة. وقالوا: إن أصيب، لم نهدم منها شيئا. ورددناها كما كانت، وإلا فقد رضي الله ما صنعنا. فأصبح الوليد من ليلته غاديا على عمله. فهدم وهدم الناس معه.", 66, 48], ["انتهاء الهدم إلى أساس إبراهيم", "حتى إذا انتهى الهدم بهم إلى الأساس - أساس إبراهيم عليه السلام - أفضوا إلى حجارة خضر كالأسنة، أخذ بعضها بعضا. فأدخل بعضهم عتلة بين حجرين منها ليقلع بها أحدهما. فلما تحرك الحجر: انتفضت مكة بأسرها. فانتهوا عند ذلك الأساس.", 67, 49], ["اختصام قريش في الحجر الأسود ولعقة الدم", "ثم إن القبائل من قريش جمعت الحجارة لبنائها، كل قبيلة تجمع على حدة ثم بنوها، حتى بلغ البنيان موضع الحجر الأسود. فاختصموا فيه، كل قبيلة تريد أن ترفعه إلى موضعه، حتى تحاوروا وتحالفوا، وأعدوا للقتال، فقربت بنو عبد الدار جفنة، مملوءة دما. تعاهدوا - هم وبنو عدي بن كعب - على الموت، وأدخلوا أيديهم في ذلك الدم. فسموا \" لعقة الدم\" فمكثت قريش على ذلك أربع ليال، أو خمسا.", 67, 50], ["تحكيم رسول الله ﷺ ووضعه الحجر الأسود", "فزعم بعض أهل الرواية: «أن أبا أمية بن المغيرة بن عبد الله بن عمر بن مخزوم المخزومي - وكان يومئذ أسن قريش كلهم - قال: اجعلوا بينكم أول من يدخل من باب المسجد. ففعلوا، فكان أول من دخل: رسول الله صلى الله عليه وسلم. فلما رأوه، قالوا: هذا الأمين، رضينا به، هذا محمد \" فلما انتهى إليهم أخبروه الخبر. فقال صلى الله عليه وسلم: هلم إلي ثوبا \" فأتي به. فأخذ الركن فوضعه فيه بيده. ثم قال: \"لتأخذ كل قبيلة بناحية من الثوب، ثم ارفعوا جميعا \" ففعلوا، حتى إذا بلغوا به موضعه: وضعه هو بيده صلى الله عليه وسلم. ثم بنى عليه.»", 67, 51], ["نقله الحجارة وستر عورته", "وكان رسول الله صلى الله عليه وسلم ينقل معهم الحجارة. وكانوا يرفعون أزرهم على عواتقهم، ففعل ذلك رسول الله صلى الله عليه وسلم فلبط به - أي طاح على وجهه - ونودي \"استر عورتك\" فما رئيت له عورة بعد ذلك.", 68, 52], ["تسقيف الكعبة وإخراج الحجر ورفع بابها", "فلما بلغوا خمسة عشر ذراعا سقفوه على ستة أعمدة.", 68, 53], ["كسوة الحجاج الكعبة الديباج", "وكان البيت يكسى القباطي. تم كسي البرود، وأول من كساه الديباج: الحجاج بن يوسف.", 68, 54], ["البعثة على رأس أربعين سنة", "فلما بلغ صلى الله عليه وسلم أربعين سنة: بعثه الله بشيرا ونذيرا. وداعيا إلى الله بإذنه وسراجا منيرا.", 68, 55], ["اختلاف الناس بعد آدم وبعث نوح", "قال قتادة: ذكر لنا: أنه كان بين آدم ونوح عشرة قرون. كلهم على الهدى، وعلى شريعة من الحق. ثم اختلفوا بعد ذلك. فبعث الله نوحا عليه السلام. وكان أول رسول إلى أهل الأرض. قال ابن عباس: في قوله تعالى: {كان الناس أمة واحدة} [البقرة: 213] (1) قال: على الإسلام كلهم. وكان أول ما كادهم به الشيطان: هو تعظيم الصالحين، وذكر الله ذلك في كتابه في قوله: {وقالوا لا تذرن آلهتكم ولا تذرن ودا ولا سواعا ولا يغوث ويعوق ونسرا} [نوح: 23] (2) قال ابن عباس: كان هؤلاء قوما صالحين. فلما ماتوا في شهر: جزع عليهم أقاربهم، فصوروا صورهم.", 68, 56], ["تصوير قوم نوح صالحيهم ثم عبادتهم", "وفي غير حديثه: \" قال أصحابهم: لو صورناهم كان أشوق لنا إلى العبادة\" قال: فكان الرجل يأتي أخاه وابن عمه فيعظمه، حتى ذهب ذلك القرن. ثم جاء قرن آخر، فعظموهم أشد من الأول. ثم جاء القرن الثالث، فقالوا: ما عظم أولونا هؤلاء إلا وهم يرجون شفاعتهم عند الله، فعبدوهم.", 69, 57], ["إهباط الطوفان الأصنام إلى أرض جدة", "فلما بعث الله إليهم نوحا - وغرق من غرق - أهبط الماء هذه الأصنام من أرض إلى أرض، حتى قذفها إلى أرض جدة. فلما نضب الماء بقيت على الشط، فسفت الريح عليها التراب، حتى وارتها.", 69, 58], ["عمرو بن لحي يورد الأصنام تهامة", "وكان عمرو بن لحي سيد خزاعة كاهنا وله رئي من الجن فأتاه. فقال: \" عجل السير والظعن من تهامة، بالسعد والسلامة، ائت جدة، تجد أصناما معدة، فأوردها تهامة ولا تهب، وادع العرب إلى عبادتها تجب \" فأتى جدة فاستثارها، ثم حملها حتى أوردها تهامة.", 69, 59], ["دعوة عمرو بن لحي العرب إلى عبادة الأصنام وتوزيعها", "وحضر الحج، فدعا العرب إلى عبادتها. فأجابه عوف بن عذرة، فدفع إليه ودا فحمله. فكان بوادي القرى بدومة الجندل. وسمى ابنه: عبد ود، فهو أول من سمى به. فلم يزل بنوه يسدنونه، حتى جاء الإسلام. فبعث رسول الله صلى الله عليه وسلم خالد بن الوليد لهدمه. فحالت بينه وبينه بنو عذرة وبنو عامر، فقاتلهم فقتلهم. ثم هدمه وجعله جذاذا.", 70, 60], ["هدم خالد بن الوليد ودا", "وحضر الحج، فدعا العرب إلى عبادتها. فأجابه عوف بن عذرة، فدفع إليه ودا فحمله. فكان بوادي القرى بدومة الجندل. وسمى ابنه: عبد ود، فهو أول من سمى به. فلم يزل بنوه يسدنونه، حتى جاء الإسلام. فبعث رسول الله صلى الله عليه وسلم خالد بن الوليد لهدمه. فحالت بينه وبينه بنو عذرة وبنو عامر، فقاتلهم فقتلهم. ثم هدمه وجعله جذاذا.", 70, 61], ["هدم علي مناة عام الفتح", "ومن أقدم أصنامهم: مناة. وكان منصوبا على ساحل البحر من ناحية المشلل بقديد، بين مكة والمدينة. وكانت العرب تعظمه قاطبة، ولم يكن أحد أشد تعظيما له من الأوس والخزرج، وبسبب ذلك أنزل الله تعالى: {إن الصفا والمروة من شعائر الله فمن حج البيت أو اعتمر فلا جناح عليه أن يطوف بهما} [البقرة: 158] (1) الآية فبعث رسول الله صلى الله عليه وسلم عليا رضي الله عنه فهدمها عام الفتح.", 71, 62], ["اتخاذ اللات في الطائف", "صنم اللات ثم اتخذوا اللات في الطائف، قيل: إن أصل ذلك رجل كان يلت السويق للحاج، فمات. فعكفوا على قبره. وكانت صخرة مربعة، وكان سدنتها ثقيف، وكانوا قد بنوا عليها بيتا. فكان جميع العرب يعظمونها، وكانت العرب تسمي زيد اللات، وتيم اللات. وهي في موضع منارة مسجد الطائف.", 71, 63], ["هدم المغيرة بن شعبة اللات", "فلما أسلمت ثقيف، بعث رسول الله صلى الله عليه وسلم المغيرة بن شعبة فهدمها، وحرقها بالنار.", 72, 64], ["عضد خالد بن الوليد العزى", "صنم العزى ثم اتخذوا العزى. وهي أحدث من اللات. وكانت بوادي نخلة. فوق ذات عرق. وبثوا عليها بيتا. وكانوا يسمعون منها الصوت. وكانت قريش تعظمها. فلما فتح رسول الله صلى الله عليه وسلم مكة، بعث خالد بن الوليد فأتاها فعضدها، وكانت ثلاث سمرات. فلما عضد الثالثة: فإذا بحبشية نافشة شعرها، واضعة يدها على عاتقها، تضرب بأنيابها. وخلفها سادنها، فقال خالد:", 72, 65], ["قول أبي سفيان يوم أحد: اعل هبل", "وكانت لقريش أصنام في جوف الكعبة وحولها. وأعظمها: هبل، وكان من عقيق أحمر على صورة الإنسان. وكانوا إذا اختصموا، أو أرادوا سفرا: أتوه فاستقسموا بالقداح عنده. وهو الذي قال فيه أبو سفيان يوم أحد: \" اعل هبل \" فقال رسول الله صلى الله عليه وسلم «قولوا: الله أعلى وأجل» .", 72, 66], ["مسخ إساف ونائلة حجرين", "وكان لهم إساف ونائلة، قيل: أصلهما أن إسافا رجل من جرهم، ونائلة امرأة منهم، فدخلا البيت، ففجر بها فيه. فمسخهما الله فيه حجرين، فأخرجهما فوضعوهما ليتعظ بهما الناس، فلما طال الأمد وعبدت الأصنام: عبدا.", 73, 67], ["هدم جرير بن عبد الله ذا الخلصة", "وكان لخثعم وبجيلة صنم يقال له: ذو الخلصة، بين مكة والمدينة. فقال رسول الله صلى الله عليه وسلم لجرير بن عبد الله البجلي: ألا تريحني من ذي الخلصة؟ فسار إليه بأحمس. فقاتلته همدان، فظفر بهم وهدمه.", 73, 68], ["تكسير الأصنام حول البيت يوم الفتح", "ولما فتح رسول الله صلى الله عليه وسلم مكة: وجد حول البيت ثلاثمائة وستين صنما. فجعل يطعن في وجوهها وعيونها، ويقول: {جاء الحق وزهق الباطل إن الباطل كان زهوقا} [الإسراء: 81] وهي تتساقط على رءوسها، ثم أمر بها فأخرجت من المسجد وحرقت.", 74, 69], ["بدء الوحي ونزول اقرأ في غار حراء", "في الصحيح عن عائشة رضي الله عنها قالت: «أول ما بدئ برسول الله صلى الله عليه وسلم من الوحي: الرؤيا الصادقة. فكان لا يرى رؤيا إلا جاءت مثل فلق، الصبح ثم حبب إليه الخلاء. فكان يخلو بغار حراء، فيتحنث فيه - وهو التعبد - الليالي ذوات العدد. قبل أن ينزع إلى أهله. ويتزود لذلك. ثم يرجع إلى خديجة فيتزود لمثلها، حتى فاجأه الحق، وهو في غار حراء، فجاءه الملك. فقال: اقرأ، فقلت: ما أنا بقارئ. قال: فأخذني فغطني، حتى بلغ مني الجهد. ثم أرسلني. فقال: اقرأ، فقلت: ما أنا بقارئ. فأخذني فغطني الثانية، حتى بلغ مني الجهد، ثم أرسلني. فقال: اقرأ. فقلت: ما أنا بقارئ. فأخذني الثالثة فغطني الثالثة. ثم أرسلني، فقال لي في الثالثة: {اقرأ باسم ربك الذي خلق - خلق الإنسان من علق - اقرأ وربك الأكرم} [العلق: 1 - 3] (1) فرجع بها رسول الله صلى الله عليه وسلم يرجف فؤاده، حتى دخل على خديجة بنت خويلد. فقال: زملوني، زملوني، فزملوه حتى ذهب عنه الروع. فقال لخديجة - وأخبرها الخبر - لقد خشيت على نفسي. فقالت خديجة: كلا والله، ما يخزيك الله أبدا، إنك لتصل الرحم، وتحمل الكل، وتقري الضيف، وتكسب المعدوم، وتعين على نوائب الحق. فانطلقت به خديجة حتى أتت به ورقة بن نوفل بن أسد بن عبد العزى - ابن عم خديجة - وكان قد تنصر في الجاهلية. وكان يكتب الكتاب العبراني. فيكتب من الإنجيل بالعبرانية ما شاء الله أن يكتب، وكان شيخا كبيرا قد عمي. فقالت له خديجة: يا ابن عم، اسمع من ابن أخيك. فقال له ورقة: يا ابن أخي، ماذا ترى؟ فأخبره رسول الله صلى الله عليه وسلم خبر ما رأى. فقال له ورقة: هذا الناموس الذي أنزل الله على موسى، يا ليتني فيها جذعا، ليتني أكون حيا إذ يخرجك قومك؟ قال: أو مخرجي هم؟ قال: نعم، لم يأت رجل قط بمثل ما جئت به إلا عودي. وإن يدركني يومك أنصرك نصرا مؤزرا.", 74, 70], ["ذهاب خديجة به إلى ورقة بن نوفل", "في الصحيح عن عائشة رضي الله عنها قالت: «أول ما بدئ برسول الله صلى الله عليه وسلم من الوحي: الرؤيا الصادقة. فكان لا يرى رؤيا إلا جاءت مثل فلق، الصبح ثم حبب إليه الخلاء. فكان يخلو بغار حراء، فيتحنث فيه - وهو التعبد - الليالي ذوات العدد. قبل أن ينزع إلى أهله. ويتزود لذلك. ثم يرجع إلى خديجة فيتزود لمثلها، حتى فاجأه الحق، وهو في غار حراء، فجاءه الملك. فقال: اقرأ، فقلت: ما أنا بقارئ. قال: فأخذني فغطني، حتى بلغ مني الجهد. ثم أرسلني. فقال: اقرأ، فقلت: ما أنا بقارئ. فأخذني فغطني الثانية، حتى بلغ مني الجهد، ثم أرسلني. فقال: اقرأ. فقلت: ما أنا بقارئ. فأخذني الثالثة فغطني الثالثة. ثم أرسلني، فقال لي في الثالثة: {اقرأ باسم ربك الذي خلق - خلق الإنسان من علق - اقرأ وربك الأكرم} [العلق: 1 - 3] (1) فرجع بها رسول الله صلى الله عليه وسلم يرجف فؤاده، حتى دخل على خديجة بنت خويلد. فقال: زملوني، زملوني، فزملوه حتى ذهب عنه الروع. فقال لخديجة - وأخبرها الخبر - لقد خشيت على نفسي. فقالت خديجة: كلا والله، ما يخزيك الله أبدا، إنك لتصل الرحم، وتحمل الكل، وتقري الضيف، وتكسب المعدوم، وتعين على نوائب الحق. فانطلقت به خديجة حتى أتت به ورقة بن نوفل بن أسد بن عبد العزى - ابن عم خديجة - وكان قد تنصر في الجاهلية. وكان يكتب الكتاب العبراني. فيكتب من الإنجيل بالعبرانية ما شاء الله أن يكتب، وكان شيخا كبيرا قد عمي. فقالت له خديجة: يا ابن عم، اسمع من ابن أخيك. فقال له ورقة: يا ابن أخي، ماذا ترى؟ فأخبره رسول الله صلى الله عليه وسلم خبر ما رأى. فقال له ورقة: هذا الناموس الذي أنزل الله على موسى، يا ليتني فيها جذعا، ليتني أكون حيا إذ يخرجك قومك؟ قال: أو مخرجي هم؟ قال: نعم، لم يأت رجل قط بمثل ما جئت به إلا عودي. وإن يدركني يومك أنصرك نصرا مؤزرا.", 74, 71], ["وفاة ورقة وفترة الوحي", "فلم يلبث ورقة أن توفي، وفتر الوحي. حتى حزن رسول الله صلى الله عليه وسلم حزنا شديدا. حتى كان يذهب إلى رءوس شواهق الجبال، يريد أن يلقي بنفسه منها، كلما أوفى بذروة جبل تبدى له جبريل عليه السلام، فقال: يا محمد، إنك رسول الله حقا \" فيسكن لذلك جأشه، وتقر نفسه، فيرجع، فإذا طال عليه فترة الوحي غدا لمثل ذلك، فإذا أوفى بذروة الجبل تبدى له جبريل، فيقول له ذلك.", 76, 72], ["نزول يا أيها المدثر وتتابع الوحي", "فبينما هو يوما يمشي إذ سمع صوتا من السماء. قال: فرفعت بصري فإذا الملك الذي جاءني بحراء جالس على كرسي بين السماء والأرض، فرعبت منه، فرجعت إلى أهلي، فقلت: دثروني. دثروني. فأنزل الله {يا أيها المدثر - قم فأنذر} [المدثر: 1 - 2] (1) فحمي الوحي وتتابع.»", 76, 73], ["إسلام أبي بكر ومن استجاب له", "ولما دعا إلى الله: استجاب له عباد من كل قبيلة. فكان حائز السبق: صديق الأمة أبا بكر رضي الله عنه. فوازره في دين الله. ودعا معه إلى الله. فاستجاب لأبي بكر عثمان وطلحة وسعد رضي الله عنهم.", 78, 74], ["إسلام خديجة وعلي بن أبي طالب", "وبادر إلى استجابته أيضا صديقة النساء خديجة رضي الله عنها. وبادر إلى الإسلام علي بن أبي طالب رضي الله عنه. وكان ابن ثمان سنين، وقيل: أكثر. إذ كان في كفالة رسول الله صلى الله عليه وسلم، أخذه من عمه.", 78, 75], ["إسلام زيد بن حارثة", "وبادر زيد بن حارثة رضي الله عنه، حب رسول الله صلى الله عليه وسلم، وكان غلاما لخديجة، فوهبته لرسول الله صلى الله عليه وسلم لما تزوجها. «وقدم أبوه حارثة وعمه في فدائه، فقالا للنبي صلى الله عليه وسلم: يا ابن سيد قومه، أنتم أهل حرم الله وجيرانه، تفكون العاني، وتطعمون الأسير، جئناك في ابننا عبدك. فأحسن لنا في فدائه. فقال صلى الله عليه وسلم: فهل غير ذلك؟ فقالوا: وما هو؟ قال: أدعوه فأخيره، فإن اختاركم فهو لكم. وإن اختارني: فوالله ما أنا بالذي أختار على من اختارني\" قالوا: قد زدتنا على النصف، وأحسنت. فدعاه. فقال: هل تعرف هؤلاء؟ قال: نعم أبي وعمي. قال: فأنا من قد علمت. وقد رأيت صحبتي لك. فاخترني، أو اخترهما. فقال: ما أنا بالذي أختار عليك أحدا. أنت مني مكان أبي وعمي. فقالا: ويحك يا زيد أتختار العبودية على الحرية. وعلى أبيك وعمك، وأهل بيتك؟ قال: نعم، قد رأيت من هذا الرجل شيئا، ما أنا بالذي أختار عليه أحدا أبدا. فلما رأى رسول الله صلى الله عليه وسلم ذلك خرج إلى الحجر. فقال: أشهدكم أن زيدا ابني، أرثه ويرثني فلما رأى ذلك أبوه وعمه طابت نفوسهما. فانصرفا. ودعي: زيد بن محمد، حتى جاء الله بالإسلام فنزلت: {ادعوهم لآبائهم هو أقسط عند الله} [الأحزاب: 5] (1) » قال الزهري: ما علمنا أحدا أسلم قبل زيد.", 78, 76], ["قدوم حارثة وأخيه في فداء زيد", "وبادر زيد بن حارثة رضي الله عنه، حب رسول الله صلى الله عليه وسلم، وكان غلاما لخديجة، فوهبته لرسول الله صلى الله عليه وسلم لما تزوجها. «وقدم أبوه حارثة وعمه في فدائه، فقالا للنبي صلى الله عليه وسلم: يا ابن سيد قومه، أنتم أهل حرم الله وجيرانه، تفكون العاني، وتطعمون الأسير، جئناك في ابننا عبدك. فأحسن لنا في فدائه. فقال صلى الله عليه وسلم: فهل غير ذلك؟ فقالوا: وما هو؟ قال: أدعوه فأخيره، فإن اختاركم فهو لكم. وإن اختارني: فوالله ما أنا بالذي أختار على من اختارني\" قالوا: قد زدتنا على النصف، وأحسنت. فدعاه. فقال: هل تعرف هؤلاء؟ قال: نعم أبي وعمي. قال: فأنا من قد علمت. وقد رأيت صحبتي لك. فاخترني، أو اخترهما. فقال: ما أنا بالذي أختار عليك أحدا. أنت مني مكان أبي وعمي. فقالا: ويحك يا زيد أتختار العبودية على الحرية. وعلى أبيك وعمك، وأهل بيتك؟ قال: نعم، قد رأيت من هذا الرجل شيئا، ما أنا بالذي أختار عليه أحدا أبدا. فلما رأى رسول الله صلى الله عليه وسلم ذلك خرج إلى الحجر. فقال: أشهدكم أن زيدا ابني، أرثه ويرثني فلما رأى ذلك أبوه وعمه طابت نفوسهما. فانصرفا. ودعي: زيد بن محمد، حتى جاء الله بالإسلام فنزلت: {ادعوهم لآبائهم هو أقسط عند الله} [الأحزاب: 5] (1) » قال الزهري: ما علمنا أحدا أسلم قبل زيد.", 78, 77], ["تبني رسول الله ﷺ زيدا ثم نزول ادعوهم لآبائهم", "وبادر زيد بن حارثة رضي الله عنه، حب رسول الله صلى الله عليه وسلم، وكان غلاما لخديجة، فوهبته لرسول الله صلى الله عليه وسلم لما تزوجها. «وقدم أبوه حارثة وعمه في فدائه، فقالا للنبي صلى الله عليه وسلم: يا ابن سيد قومه، أنتم أهل حرم الله وجيرانه، تفكون العاني، وتطعمون الأسير، جئناك في ابننا عبدك. فأحسن لنا في فدائه. فقال صلى الله عليه وسلم: فهل غير ذلك؟ فقالوا: وما هو؟ قال: أدعوه فأخيره، فإن اختاركم فهو لكم. وإن اختارني: فوالله ما أنا بالذي أختار على من اختارني\" قالوا: قد زدتنا على النصف، وأحسنت. فدعاه. فقال: هل تعرف هؤلاء؟ قال: نعم أبي وعمي. قال: فأنا من قد علمت. وقد رأيت صحبتي لك. فاخترني، أو اخترهما. فقال: ما أنا بالذي أختار عليك أحدا. أنت مني مكان أبي وعمي. فقالا: ويحك يا زيد أتختار العبودية على الحرية. وعلى أبيك وعمك، وأهل بيتك؟ قال: نعم، قد رأيت من هذا الرجل شيئا، ما أنا بالذي أختار عليه أحدا أبدا. فلما رأى رسول الله صلى الله عليه وسلم ذلك خرج إلى الحجر. فقال: أشهدكم أن زيدا ابني، أرثه ويرثني فلما رأى ذلك أبوه وعمه طابت نفوسهما. فانصرفا. ودعي: زيد بن محمد، حتى جاء الله بالإسلام فنزلت: {ادعوهم لآبائهم هو أقسط عند الله} [الأحزاب: 5] (1) » قال الزهري: ما علمنا أحدا أسلم قبل زيد.", 78, 78], ["إسلام ورقة بن نوفل", "وأسلم ورقة بن نوفل. وفي جامع الترمذي: \" أن النبي صلى الله عليه وسلم «رآه في المنام في هيئة حسنة» .", 79, 79], ["عيبه دين قريش وابتداء عداوتهم", "ودخل الناس في دين الله واحدا بعد واحد. وقريش لا تنكر ذلك، حتى بادأهم بعيب دينهم وسب آلهتهم (1) وأنها لا تضر ولا تنفع. فحينئذ شمروا له ولأصحابه عن ساق العداوة. فحمى الله رسوله بعمه أبي طالب. لأنه كان شريفا معظما. وكان من حكمة أحكم الحاكمين: بقاؤه على دين قومه لما في ذلك من المصالح التي تبدو لمن تأملها.", 79, 80], ["تعذيب آل ياسر", "وأما أصحابه: فمن كان له عشيرة تحميه امتنع بعشيرته، وسائرهم تصدوا له بالأذى والعذاب. منهم: عمار بن ياسر، وأمه سمية، وأهل بيته. عذبوا في الله. وكان رسول الله صلى الله عليه وسلم إذا مر بهم - وهم يعذبون - يقول: «صبرا يا آل ياسر، فإن موعدكم الجنة» .", 80, 81], ["مقتل سمية أول شهيدة", "ومر أبو جهل بسمية - أم عمار رضي الله عنهما - وهي تعذب، وزوجها وابنها. فطعنها بحربة في فرجها فقتلها.", 80, 82], ["عتق أبي بكر بلالا وغيره من المعذبين", "وكان الصديق إذا مر بأحد من العبيد يعذب اشتراه وأعتقه. منهم بلال. فإنه عذب في الله أشد العذاب. ومنهم عامر بن فهيرة، وجارية لبني عدي، كان عمر يعذبها على الإسلام. فقال أبو قحافة - عثمان بن عامر - لابنه أبي بكر: يا بني، أراك تعتق رقابا ضعافا. فلو أعتقت قوما جلدا يمنعونك؟ فقال: إني أريد ما أريد. وكان بلال كلما اشتد به العذاب يقول: أحد، أحد.", 80, 83], ["تعذيب قريش من آمن من عشائرهم", "ابتداء الدعوة وقال الزهري: لما ظهر الإسلام، أتى جماعة من كفار قريش إلى من آمن من عشائرهم، فعذبوهم وسجنوهم، وأرادوا أن يفتنوهم عن دينهم. قال الترمذي: حدثني محمد بن صالح عن عاصم بن عمرو بن قتادة ويزيد بن رومان وغيرهم. قالوا: «قام رسول الله صلى الله عليه وسلم بمكة ثلاث سنين مستخفيا. تم أعلن في الرابعة. فدعا الناس عشر سنين، يوافي المواسم كل عام، يتبع الناس في منازلهم. وفي المواسم بعكاظ، ومجنة، وذي المجاز: يدعوهم أن يمنعوه حتى يبلغ رسالات ربه. ولهم الجنة، فلا يجد أحدا ينصره ويحميه. حتى ليسأل عن القبائل ومنازلها قبيلة قبيلة، فيقول: \"أيها الناس، قولوا: لا إله إلا الله، تفلحوا وتملكوا بها العرب، وتدين لكم بها العجم. فإذا متم كنتم ملوكا في الجنة\" وأبو لهب وراءه يقول: لا تطيعوه. فإنه صابئ كذاب، فيردون على رسول الله صلى الله عليه وسلم أقبح الرد. ويؤذونه، ويقولون: عشيرتك أعلم بك حيث لم يتبعوك. وهو يقول: اللهم لو شئت لم يكونوا هكذا ولما نزل عليه قوله تعالى: {وأنذر عشيرتك الأقربين} [الشعراء: 214] صعد الصفا فنادى: واصباحاه. فلما اجتمعوا إليه قال: لو أخبرتكم أن خيلا تريد أن تخرج عليكم من سفح هذا الجبل أكنتم مصدقي؟ قالوا: نعم، ما جربنا عليك كذبا. قال: فإني نذير لكم بين يدي عذاب شديد، فقال أبو لهب: تبا لك، ما جمعتنا إلا لهذا؟ فأنزل الله قوله تعالى: {تبت يدا أبي لهب وتب - ما أغنى عنه ماله وما كسب} [المسد: 1 - 2] » (1) .", 80, 84], ["الدعوة سرا ثلاث سنين ثم إعلانها في الرابعة", "ابتداء الدعوة وقال الزهري: لما ظهر الإسلام، أتى جماعة من كفار قريش إلى من آمن من عشائرهم، فعذبوهم وسجنوهم، وأرادوا أن يفتنوهم عن دينهم. قال الترمذي: حدثني محمد بن صالح عن عاصم بن عمرو بن قتادة ويزيد بن رومان وغيرهم. قالوا: «قام رسول الله صلى الله عليه وسلم بمكة ثلاث سنين مستخفيا. تم أعلن في الرابعة. فدعا الناس عشر سنين، يوافي المواسم كل عام، يتبع الناس في منازلهم. وفي المواسم بعكاظ، ومجنة، وذي المجاز: يدعوهم أن يمنعوه حتى يبلغ رسالات ربه. ولهم الجنة، فلا يجد أحدا ينصره ويحميه. حتى ليسأل عن القبائل ومنازلها قبيلة قبيلة، فيقول: \"أيها الناس، قولوا: لا إله إلا الله، تفلحوا وتملكوا بها العرب، وتدين لكم بها العجم. فإذا متم كنتم ملوكا في الجنة\" وأبو لهب وراءه يقول: لا تطيعوه. فإنه صابئ كذاب، فيردون على رسول الله صلى الله عليه وسلم أقبح الرد. ويؤذونه، ويقولون: عشيرتك أعلم بك حيث لم يتبعوك. وهو يقول: اللهم لو شئت لم يكونوا هكذا ولما نزل عليه قوله تعالى: {وأنذر عشيرتك الأقربين} [الشعراء: 214] صعد الصفا فنادى: واصباحاه. فلما اجتمعوا إليه قال: لو أخبرتكم أن خيلا تريد أن تخرج عليكم من سفح هذا الجبل أكنتم مصدقي؟ قالوا: نعم، ما جربنا عليك كذبا. قال: فإني نذير لكم بين يدي عذاب شديد، فقال أبو لهب: تبا لك، ما جمعتنا إلا لهذا؟ فأنزل الله قوله تعالى: {تبت يدا أبي لهب وتب - ما أغنى عنه ماله وما كسب} [المسد: 1 - 2] » (1) .", 80, 85], ["عرضه نفسه على القبائل في المواسم", "ابتداء الدعوة وقال الزهري: لما ظهر الإسلام، أتى جماعة من كفار قريش إلى من آمن من عشائرهم، فعذبوهم وسجنوهم، وأرادوا أن يفتنوهم عن دينهم. قال الترمذي: حدثني محمد بن صالح عن عاصم بن عمرو بن قتادة ويزيد بن رومان وغيرهم. قالوا: «قام رسول الله صلى الله عليه وسلم بمكة ثلاث سنين مستخفيا. تم أعلن في الرابعة. فدعا الناس عشر سنين، يوافي المواسم كل عام، يتبع الناس في منازلهم. وفي المواسم بعكاظ، ومجنة، وذي المجاز: يدعوهم أن يمنعوه حتى يبلغ رسالات ربه. ولهم الجنة، فلا يجد أحدا ينصره ويحميه. حتى ليسأل عن القبائل ومنازلها قبيلة قبيلة، فيقول: \"أيها الناس، قولوا: لا إله إلا الله، تفلحوا وتملكوا بها العرب، وتدين لكم بها العجم. فإذا متم كنتم ملوكا في الجنة\" وأبو لهب وراءه يقول: لا تطيعوه. فإنه صابئ كذاب، فيردون على رسول الله صلى الله عليه وسلم أقبح الرد. ويؤذونه، ويقولون: عشيرتك أعلم بك حيث لم يتبعوك. وهو يقول: اللهم لو شئت لم يكونوا هكذا ولما نزل عليه قوله تعالى: {وأنذر عشيرتك الأقربين} [الشعراء: 214] صعد الصفا فنادى: واصباحاه. فلما اجتمعوا إليه قال: لو أخبرتكم أن خيلا تريد أن تخرج عليكم من سفح هذا الجبل أكنتم مصدقي؟ قالوا: نعم، ما جربنا عليك كذبا. قال: فإني نذير لكم بين يدي عذاب شديد، فقال أبو لهب: تبا لك، ما جمعتنا إلا لهذا؟ فأنزل الله قوله تعالى: {تبت يدا أبي لهب وتب - ما أغنى عنه ماله وما كسب} [المسد: 1 - 2] » (1) .", 80, 86], ["صعوده الصفا ونزول تبت يدا أبي لهب", "ابتداء الدعوة وقال الزهري: لما ظهر الإسلام، أتى جماعة من كفار قريش إلى من آمن من عشائرهم، فعذبوهم وسجنوهم، وأرادوا أن يفتنوهم عن دينهم. قال الترمذي: حدثني محمد بن صالح عن عاصم بن عمرو بن قتادة ويزيد بن رومان وغيرهم. قالوا: «قام رسول الله صلى الله عليه وسلم بمكة ثلاث سنين مستخفيا. تم أعلن في الرابعة. فدعا الناس عشر سنين، يوافي المواسم كل عام، يتبع الناس في منازلهم. وفي المواسم بعكاظ، ومجنة، وذي المجاز: يدعوهم أن يمنعوه حتى يبلغ رسالات ربه. ولهم الجنة، فلا يجد أحدا ينصره ويحميه. حتى ليسأل عن القبائل ومنازلها قبيلة قبيلة، فيقول: \"أيها الناس، قولوا: لا إله إلا الله، تفلحوا وتملكوا بها العرب، وتدين لكم بها العجم. فإذا متم كنتم ملوكا في الجنة\" وأبو لهب وراءه يقول: لا تطيعوه. فإنه صابئ كذاب، فيردون على رسول الله صلى الله عليه وسلم أقبح الرد. ويؤذونه، ويقولون: عشيرتك أعلم بك حيث لم يتبعوك. وهو يقول: اللهم لو شئت لم يكونوا هكذا ولما نزل عليه قوله تعالى: {وأنذر عشيرتك الأقربين} [الشعراء: 214] صعد الصفا فنادى: واصباحاه. فلما اجتمعوا إليه قال: لو أخبرتكم أن خيلا تريد أن تخرج عليكم من سفح هذا الجبل أكنتم مصدقي؟ قالوا: نعم، ما جربنا عليك كذبا. قال: فإني نذير لكم بين يدي عذاب شديد، فقال أبو لهب: تبا لك، ما جمعتنا إلا لهذا؟ فأنزل الله قوله تعالى: {تبت يدا أبي لهب وتب - ما أغنى عنه ماله وما كسب} [المسد: 1 - 2] » (1) .", 80, 87], ["نزول فاصدع بما تؤمر", "قال ابن القيم رحمه الله: دعا رسول الله صلى الله عليه وسلم إلى الله مستخفيا ثلاث سنين، ثم نزل عليه: {فاصدع بما تؤمر وأعرض عن المشركين} [الحجر: 94] (2) .", 81, 88], ["أول دم أهريق في الإسلام", "وفي السنة الرابعة: ضرب سعد بن أبي وقاص رجلا من المشركين فشجه. وذلك: أن أصحاب رسول الله صلى الله عليه وسلم كانوا يجتمعون في الشعاب، فيصلون فيها. فرآهم رجل من الكفار، ومعه جماعة من قريش، فسبوهم. وضرب سعد بن أبي وقاص رجلا منهم، فسال دمه. فكان أول دم أهريق في الإسلام.", 82, 89], ["استهزاء المشركين بالمستضعفين", "استهزاء المشركين وكان النبي صلى الله عليه وسلم إذا جلس وحوله المستضعفون من أصحابه - مثل عمار بن ياسر، وخباب بن الأرت، وصهيب الرومي، وبلال، وأشباههم - فإذا مرت بهم قريش استهزءوا بهم، وقالوا: أهؤلاء - جلساؤه - قد من الله عليهم من بيننا؟ فأنزل الله: {أليس الله بأعلم بالشاكرين} [الأنعام: 53] (3) وفيهم نزل:", 82, 90], ["نهي أبي جهل النبي ﷺ عن الصلاة", "{والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنة ولأجر الآخرة أكبر لو كانوا يعلمون} [النحل: 41] (1) وقال أبو جهل: والله لئن رأيت محمدا يصلي لأطأن على رقبته. فبلغه أن رسول الله يصلي، فأتاه. فقال: ألم أنهك عن الصلاة؟ فانتهره رسول الله صلى الله عليه وسلم. فقال: أتنتهرني، وأنا أعز أهل البطحاء؟ فنزل قوله تعالى: {أرأيت الذي ينهى - عبدا إذا صلى} [العلق: 9 - 10] (2) وفي بعض الروايات، أنه قال: ألم أنهك؟ فوالله ما في مكة أعز من نادي.", 82, 91], ["الهجرة الأولى إلى الحبشة", "الهجرة الأولى إلى الحبشة وفي السنة الخامسة: «أمر النبي صلى الله عليه وسلم أصحابه بالهجرة إلى الحبشة لما اشتد عليهم العذاب والأذى. وقال: إن فيها رجلا لا يظلم الناس عنده» .", 83, 92], ["رجوع مهاجرة الحبشة إلى مكة", "وممن خرج: الزبير وعبد الرحمن بن عوف وابن مسعود وأبو سلمة وامرأته رضي الله عنهم. خرجوا متسللين سرا، فوفق الله لهم ساعة وصولهم إلى الساحل سفينتين للتجار. فحملوهم إلى الحبشة، وخرجت قريش في آثارهم حتى جاءوا البحر. فلم يدركوا منهم أحدا. وكان خروجهم في رجب. فأقاموا بالحبشة شعبان ورمضان. ثم رجعوا إلى مكة في شوال، لما بلغهم: أن قريشا صافوا رسول الله صلى الله عليه وسلم وكفوا عنه.", 83, 93], ["قراءته سورة النجم وسجود المشركين", "وكان سبب ذلك: أن رسول الله صلى الله عليه وسلم قرأ سورة النجم. فلما بلغ: {أفرأيتم اللات والعزى - ومناة الثالثة الأخرى} [النجم: 19 - 20] (1) ألقى الشيطان على لسانه: \"تلك الغرانيق العلى، وإن شفاعتهن لترتجى\" فقال المشركون: ما ذكر آلهتنا بخير قبل اليوم، وقد علمنا أن الله يخلق ويرزق ويحيي ويميت ولكن آلهتنا تشفع عنده. فلما بلغ السجدة سجد، وسجد معه المسلمون والمشركون كلهم. إلا شيخا من قريش. رفع إلى جبهته كفا من حصى فسجد عليه. وقال: يكفيني هذا (2) .", 84, 94], ["اشتداد قريش على من أسلم", "ولما استمر النبي صلى الله عليه وسلم على سب آلهتهم، عادوا إلى شر مما كانوا عليه، وازدادوا شدة على من أسلم.", 84, 95], ["الهجرة الثانية إلى الحبشة", "فلما قرب مهاجرة الحبشة من مكة، وبلغهم أمرهم، توقفوا عن الدخول. ثم دخل كل رجل في جوار رجل من قريش. ثم اشتد عليهم البلاء والعذاب من قريش وسطت بهم عشائرهم، وصعب عليهم ما بلغهم عن النجاشي من حسن جواره. فأذن لهم رسول الله صلى الله عليه وسلم في الخروج إلى الحبشة مرة ثانية. فخرجوا.", 85, 96], ["رجوع بعض مهاجرة الحبشة لما سمعوا بالهجرة", "فلما سمعوا بمهاجر رسول الله صلى الله عليه وسلم إلى المدينة، رجع منهم ثلاثة وثلاثون رجلا، ومن النساء ثمان. ومات منهم رجلان بمكة. وحبس سبعة. وشهد بدرا منهم أربعة وعشرون رجلا.", 85, 97], ["كتاب رسول الله ﷺ إلى النجاشي", "فلما كان شهر ربيع سنة سبع من الهجرة. كتب رسول الله صلى الله عليه وسلم كتابا إلى النجاشي يدعوه إلى الإسلام. وكتب إليه: أن يزوجه أم حبيبة بنت أبي سفيان. وكانت مهاجرة مع زوجها عبد الله بن جحش. فتنصر هناك ومات نصرانيا.", 85, 98], ["تنصر عبد الله بن جحش زوج أم حبيبة وموته نصرانيا", "فلما كان شهر ربيع سنة سبع من الهجرة. كتب رسول الله صلى الله عليه وسلم كتابا إلى النجاشي يدعوه إلى الإسلام. وكتب إليه: أن يزوجه أم حبيبة بنت أبي سفيان. وكانت مهاجرة مع زوجها عبد الله بن جحش. فتنصر هناك ومات نصرانيا.", 85, 99], ["إسلام النجاشي وتزويجه أم حبيبة", "وكتب إليه أيضا: أن يبعث إليه من بقي من أصحابه. فلما قرأ الكتاب أسلم. وقال: لو قدرت أن آتيه لأتيته. وزوجه أم حبيبة، وأصدقها عنه أربعمائة دينار. وحمل بقية أصحابه في سفينتين. فقدموا على رسول الله صلى الله عليه وسلم بخيبر، وقد فتحها.", 85, 100], ["قدوم أصحاب الحبشة على رسول الله ﷺ بخيبر", "وكتب إليه أيضا: أن يبعث إليه من بقي من أصحابه. فلما قرأ الكتاب أسلم. وقال: لو قدرت أن آتيه لأتيته. وزوجه أم حبيبة، وأصدقها عنه أربعمائة دينار. وحمل بقية أصحابه في سفينتين. فقدموا على رسول الله صلى الله عليه وسلم بخيبر، وقد فتحها.", 85, 101], ["بعث قريش إلى النجاشي تطلب إرجاع المسلمين", "ولما كان بعد بدر: اجتمعت قريش في دار الندوة. وقالوا: إن لنا في الذين عند النجاشي ثأرا. فاجمعوا مالا، وأهدوه إلى النجاشي، لعله يدفع إليكم من عنده ولننتدب لذلك رجلين من أهل رأيكم. فبعثوا عمرو بن العاص وعمارة بن الوليد (1) مع الهدية. فركبا البحر. فلما دخلا على النجاشي سجدا له، وسلما عليه. وقالا: قومنا لك ناصحون، وإنهم بعثونا إليك لنحذرك هؤلاء الذين قدموا عليك لأنهم قوم اتبعوا رجلا كذابا. خرج فينا يزعم أنه رسول الله، ولم يتبعه إلا السفهاء فضيقنا عليهم، وألجأناهم إلى شعب بأرضنا، لا يخرج منهم أحد ولا يدخل عليهم أحد. فقتلهم الجوع والعطش. فلما اشتد عليهم الأمر، بعث إليك ابن عمه ليفسد عليك دينك وملكك. فاحذرهم. وادفعهم إلينا لنكفيكهم، وآية ذلك: أنهم إذا دخلوا عليك لا يسجدون لك، ولا يحيونك بالتحية التي تحيى بها، رغبة عن دينك.", 86, 102], ["دخول جعفر والمسلمين على النجاشي ومحاورته", "فدعاهم النجاشي. فلما حضروا صاح جعفر بن أبي طالب بالباب \"يستأذن عليك حزب الله\" فقال النجاشي: مروا هذا الصائح فليعد كلامه. ففعل. قال: نعم. فليدخلوا بإذن الله وذمته. فدخلوا ولم يسجدوا له. فقال: ما منعكم أن تسجدوا لي؟ قالوا: إنما نسجد لله الذي خلقك وملكك، وإنما كانت تلك التحية لنا ونحن نعبد الأوثان. فبعث الله فينا نبيا صادقا. وأمرنا بالتحية التي رضيها الله. وهي \" السلام \" تحية أهل الجنة.", 86, 103], ["قراءة جعفر القرآن على النجاشي ونزول آية المائدة", "فقال: اقرأ مما يقرأ عليكم. فقرأ سورتي العنكبوت والروم. ففاضت عينا النجاشي من الدمع. فقال: زدنا من هذا الحديث الطيب. فقرأ عليهم سورة الكهف.", 88, 104], ["تأمين النجاشي للمسلمين بأرضه", "فأقبل النجاشي على جعفر. ثم قال: اذهبوا فأنتم سيوم بأرضي - والسيوم الآمنون - من سبكم غرم. فلا هوادة (2) اليوم على حزب إبراهيم.", 89, 105], ["موت النجاشي وصلاة النبي ﷺ عليه", "«ولما مات النجاشي، خرج رسول الله صلى الله عليه وسلم فصلى عليه كما يصلي على الجنائز. فقال المنافقون: يصلي على علج مات بأرض الحبشة. فأنزل الله تعالى: {وإن من أهل الكتاب لمن يؤمن بالله وما أنزل إليكم وما أنزل إليهم خاشعين لله} [آل عمران: 199] الآية» (3) .", 89, 106], ["استتاره ﷺ في دار الأرقم", "وفي سنة خمس من النبوة استتر رسول الله صلى الله عليه وسلم في دار الأرقم بن أبي الأرقم.", 89, 107], ["إسلام حمزة بن عبد المطلب", "وفي السنة السادسة، أسلم حمزة بن عبد المطلب وعمر.", 89, 108], ["إسلام عمر رضي الله عنه", "وروي عن ابن عباس رضي الله عنهما: أنه قال لعمر رضي الله عنه: «لم سميت الفاروق؟ فقال: أسلم حمزة قبلي بثلاثة أيام. ثم شرح الله صدري للإسلام. وأول شيء سمعته من القرآن ووقر في صدري: {الله لا إله إلا هو له الأسماء الحسنى} [طه: 8] (1) فما في الأرض نسمة أحب إلي من نسمة رسول الله صلى الله عليه وسلم. فسألت عنه؟ فقيل لي: هو في دار الأرقم. فأتيت الدار - وحمزة في أصحابه جلوسا في الدار، ورسول الله صلى الله عليه وسلم في البيت - فضربت الباب، فاستجمع القوم. فقال لهم حمزة: ما لكم؟ فقالوا: عمر، فخرج رسول الله صلى الله عليه وسلم. فأخذ بمجامع ثيابي. ثم نترني نترة لم أتمالك أن وقعت على ركبتي. فقال: ما أنت بمنته يا عمر؟ فقلت: أشهد أن لا إله إلا الله وأنك رسول الله، فكبر أهل الدار تكبيرة سمعها أهل المسجد. فقلت: يا رسول الله، ألسنا على الحق، إن متنا أو حيينا؟ قال: بلى. فقلت: ففيم الاختفاء؟ والذي بعثك بالحق لتخرجن، فخرجنا في صفين. حمزة في صف، وأنا في صف - له كديد ككديد الطحن - حتى دخلنا المسجد. فلما نظرت إلينا قريش أصابتهم كآبة لم يصبهم مثلها قط. فسماني رسول الله صلى الله عليه وسلم: الفاروق» .", 90, 109], ["خروج المسلمين في صفين إلى المسجد وتسمية عمر الفاروق", "وروي عن ابن عباس رضي الله عنهما: أنه قال لعمر رضي الله عنه: «لم سميت الفاروق؟ فقال: أسلم حمزة قبلي بثلاثة أيام. ثم شرح الله صدري للإسلام. وأول شيء سمعته من القرآن ووقر في صدري: {الله لا إله إلا هو له الأسماء الحسنى} [طه: 8] (1) فما في الأرض نسمة أحب إلي من نسمة رسول الله صلى الله عليه وسلم. فسألت عنه؟ فقيل لي: هو في دار الأرقم. فأتيت الدار - وحمزة في أصحابه جلوسا في الدار، ورسول الله صلى الله عليه وسلم في البيت - فضربت الباب، فاستجمع القوم. فقال لهم حمزة: ما لكم؟ فقالوا: عمر، فخرج رسول الله صلى الله عليه وسلم. فأخذ بمجامع ثيابي. ثم نترني نترة لم أتمالك أن وقعت على ركبتي. فقال: ما أنت بمنته يا عمر؟ فقلت: أشهد أن لا إله إلا الله وأنك رسول الله، فكبر أهل الدار تكبيرة سمعها أهل المسجد. فقلت: يا رسول الله، ألسنا على الحق، إن متنا أو حيينا؟ قال: بلى. فقلت: ففيم الاختفاء؟ والذي بعثك بالحق لتخرجن، فخرجنا في صفين. حمزة في صف، وأنا في صف - له كديد ككديد الطحن - حتى دخلنا المسجد. فلما نظرت إلينا قريش أصابتهم كآبة لم يصبهم مثلها قط. فسماني رسول الله صلى الله عليه وسلم: الفاروق» .", 90, 110], ["مشي قريش إلى أبي طالب بعمارة بن الوليد", "حماية أبي طالب لرسول الله صلى الله عليه وسلم ولما رأت قريش أن رسول الله صلى الله عليه وسلم يتزايد أمره ويقوى، ورأوا ما صنع أبو طالب به. مشوا إليه بعمارة بن الوليد. فقالوا: يا أبا طالب، هذا أنهد فتى في قريش وأجمله. فخذه وادفع إلينا هذا الذي خالف دينك ودين آبائك فنقتله، فإنما هو رجل برجل. فقال: بئسما تسومونني، تعطوني ابنكم أربيه لكم وأعطيكم ابني تقتلونه؟ فقال المطعم بن عدي بن نوفل: يا أبا طالب، قد أنصفك قومك، وجهدوا على التخلص منك بكل طريق. قال: والله ما أنصفتموني، ولكنك أجمعت على خذلاني، فاصنع ما بدا لك.", 91, 111], ["كلام أبي طالب لابن أخيه وجوابه ﷺ", "فبعث أبو طالب إلى رسول الله صلى الله عليه وسلم، فقال له: يابن أخي، إن قومك جاءوني، وقالوا كذا وكذا، فأبق علي وعلى نفسك، ولا تحملني ما لا أطيق أنا ولا أنت. فاكفف عن قومك ما يكرهون من قولك. فقال صلى الله عليه وسلم: «والله لو وضعوا الشمس في يميني والقمر في يساري ما تركت هذا الأمر حتى يظهره الله، أو أهلك في طلبه\" فقال: امض على أمرك، فوالله لا أسلمك أبدا» .", 92, 112], ["إجابة بني هاشم وبني المطلب أبا طالب إلى نصرته", "ودعا أبو طالب أقاربه إلى نصرته فأجابه بنو هاشم وبنو المطلب، غير أبي لهب، وقال أبو طالب:", 92, 113], ["كتابة قريش الصحيفة على بني هاشم", "ولما اجتمعوا - مؤمنهم وكافرهم - على منع رسول الله صلى الله عليه وسلم: اجتمعت قريش. فأجمعوا أمرهم على ألا يجالسوهم، ولا يبايعوهم ولا يدخلوا بيوتهم. حتى يسلموا رسول الله صلى الله عليه وسلم للقتل. وكتبوا بذلك صحيفة فيها عهود ومواثيق \" ألا يقبلوا من بني هاشم صلحا أبدا، ولا تأخذهم بهم رأفة حتى يسلموه للقتل \" فأمرهم أبو طالب أن يدخلوا شعبه فلبثوا فيه ثلاث سنين. واشتد عليهم البلاء وقطعوا عنهم الأسواق. فلا يتركون طعاما يدخل مكة، ولا بيعا إلا بادروا فاشتروه. ومنعوه أن يصل شيء منه إلى بني هاشم. حتى كان يسمع أصوات نسائهم يتضاغون من وراء الشعب من الجوع. واشتدوا على من أسلم ممن لم يدخل الشعب، فأوثقهم. وعظمت الفتنة وزلزلوا زلزالا شديدا، وكان أبو طالب إذا أخذ الناس مضاجعهم. أمر رسول الله صلى الله عليه وسلم أن يضطجع على فراشه حتى يرى ذلك من أراد اغتياله.", 92, 114], ["حصار بني هاشم في شعب أبي طالب", "ولما اجتمعوا - مؤمنهم وكافرهم - على منع رسول الله صلى الله عليه وسلم: اجتمعت قريش. فأجمعوا أمرهم على ألا يجالسوهم، ولا يبايعوهم ولا يدخلوا بيوتهم. حتى يسلموا رسول الله صلى الله عليه وسلم للقتل. وكتبوا بذلك صحيفة فيها عهود ومواثيق \" ألا يقبلوا من بني هاشم صلحا أبدا، ولا تأخذهم بهم رأفة حتى يسلموه للقتل \" فأمرهم أبو طالب أن يدخلوا شعبه فلبثوا فيه ثلاث سنين. واشتد عليهم البلاء وقطعوا عنهم الأسواق. فلا يتركون طعاما يدخل مكة، ولا بيعا إلا بادروا فاشتروه. ومنعوه أن يصل شيء منه إلى بني هاشم. حتى كان يسمع أصوات نسائهم يتضاغون من وراء الشعب من الجوع. واشتدوا على من أسلم ممن لم يدخل الشعب، فأوثقهم. وعظمت الفتنة وزلزلوا زلزالا شديدا، وكان أبو طالب إذا أخذ الناس مضاجعهم. أمر رسول الله صلى الله عليه وسلم أن يضطجع على فراشه حتى يرى ذلك من أراد اغتياله.", 92, 115], ["تعاقد النفر على نقض الصحيفة", "ثم بعد ذلك مشى هشام بن عمرو من بني عامر بن لؤي. وكان يصل بني هاشم في الشعب خفية بالليل بالطعام - مشى إلى زهير بن أبي أمية المخزومي - وكانت أمه عاتكة بنت عبد المطلب - وقال يا زهير أرضيت أن تأكل الطعام وتشرب الشراب وأخوالك بحيث تعلم؟ فقال ويحك، فما أصنع وأنا رجل واحد؟ أما والله لو كان معي رجل آخر لقمت في نقضها. قال أنا. قال أبغنا ثالثا. قال أبو البختري بن هشام. قال أبغنا رابعا. قال زمعة بن الأسود. قال أبغنا خامسا. قال المطعم بن عدي. قال فاجتمعوا عند الحجون، وتعاقدوا على القيام بنقض الصحيفة. فقال زهير أنا أبدأ بها.", 96, 116], ["أكل الأرضة الصحيفة وإخبار أبي طالب قريشا", "وبعث الله على صحيفتهم الأرضة فلم تترك اسما لله إلا لحسته وبقي ما فيها من شرك وظلم وقطيعة وأطلع الله رسوله على الذي صنع بصحيفتهم. فذكر ذلك لعمه. فقال لا، والثواقب ما كذبتني. فانطلق يمشي بعصابة من بني عبد المطلب، حتى أتى المسجد وهو حافل في قريش. فلما رأوهم ظنوا أنهم خرجوا من شدة الحصار وأتوا ليعطوهم رسول الله -صلى الله عليه وسلم - فتكلم أبو طالب. فقال قد حدث أمر. لعله أن يكون بيننا وبينكم صلحا. فأتوا بصحيفتكم - وإنما قال ذلك خشية أن ينظروا فيها قبل أن يأتوا بها، فلا يأتون بها - فأتوا بها معجبين. لا يشكون أن رسول الله -صلى الله عليه وسلم - مدفوع إليهم قالوا: قد آن لكم أن تفيئوا وترجعوا خطرا لهلكة قومكم.", 97, 117], ["فتح الصحيفة فوجدوها كما أخبر", "فقال أبو طالب: لأعطينكم أمرا فيه نصف، إن ابني أخبرني - ولم يكذبني - أن الله عز وجل بريء من هذه الصحيفة التي في أيديكم وأنه محا كل اسم له فيها، وترك فيها غدركم وقطيعتكم. فإن كان ما قال حقا، فوالله لا نسلمه إليكم حتى نموت عن آخرنا. وإن كان الذي يقول باطلا، دفعناه إليكم فقتلتموه. أو استحييتموه. قالوا: قد رضينا. ففتحوا الصحيفة فوجدوها كما أخبر. فقالوا: هذا سحر من صاحبكم فارتكسوا وعادوا إلى شر ما هم عليه. فتكلم عند ذلك النفر الذين تعاقدوا - كما تقدم - وقال أبو طالب شعرا يمدح النفر الذين تعاقدوا على نقض الصحيفة. ويمدح النجاشي، منه:", 97, 118], ["إسلام هشام بن عمرو", "وأسلم هشام بن عمرو يوم الفتح. وخرج بنو هاشم من شعبهم وخالطوا الناس. وكان خروجهم في سنة عشر من النبوة. ومات أبو طالب بعدها بستة أشهر.", 98, 119], ["خروج بني هاشم من الشعب", "وأسلم هشام بن عمرو يوم الفتح. وخرج بنو هاشم من شعبهم وخالطوا الناس. وكان خروجهم في سنة عشر من النبوة. ومات أبو طالب بعدها بستة أشهر.", 98, 120], ["موت أبي طالب", "وأسلم هشام بن عمرو يوم الفتح. وخرج بنو هاشم من شعبهم وخالطوا الناس. وكان خروجهم في سنة عشر من النبوة. ومات أبو طالب بعدها بستة أشهر.", 98, 121], ["موت خديجة أم المؤمنين", "وماتت خديجة أم المؤمنين -رضي الله عنها- بعد موت أبي طالب بأيام. فاشتد البلاء على رسول الله -صلى الله عليه وسلم - من قومه بعد موت خديجة وعمه وتجرءوا عليه وكاشفوه بالأذى. وأرادوا قتله. فمنعهم الذي من ذلك.", 98, 122], ["اجتماع أشراف قريش في الحجر وغمزهم له ﷺ", "قال عبد الله بن عمرو بن العاص رضي الله عنهما \" حضرتهم. وقد اجتمع أشرافهم في الحجر. فذكروا رسول الله -صلى الله عليه وسلم -. فقالوا: ما رأينا مثل صبرنا عليه سفه أحلامنا. وشتم آباءنا. وفرق جماعتنا، فبينما هم في ذلك. إذ أقبل. فاستلم الركن. فلما مر بهم غمزوه \".", 98, 123], ["وثوب قريش عليه ﷺ ودفاع أبي بكر عنه", "فلما كان من الغد اجتمعوا فقالوا: ذكرتم ما بلغ منكم حتى إذا أتاكم بما تكرهون تركتموه. فبينما هم كذلك. إذ طلع عليهم فقالوا: قوموا إليه وثبة رجل واحد. فلقد رأيت عقبة بن أبي معيط آخذا بمجامع ردائه وقام أبو بكر دونه وهو يبكي، يقول أتقتلون رجلا أن يقول ربي الله؟ .", 99, 124], ["إلقاء سلا الجزور على ظهره وهو يصلي", "ومرة كان يصلي عند البيت، ورهط من أشرافهم يرونه فأتى أحدهم بسلا جزور. فرماه على ظهره. وكانوا يعلمون صدقه وأمانته. وأن ما جاء به هو الحق. لكنهم كما قال الله تعالى {فإنهم لا يكذبونك ولكن الظالمين بآيات الله يجحدون} [الأنعام: 33] (1) .", 99, 125], ["استماع أبي جهل والأخنس قراءته ليلا", "وذكر الزهري: أن أبا جهل. وجماعة معه وفيهم الأخنس بن شريق، استمعوا قراءة رسول الله -صلى الله عليه وسلم - في الليل فقال الأخنس لأبي جهل يا أبا الحكم ما رأيك فيما سمعت من محمد؟ فقال تنازعنا نحن وبنو عبد مناف الشرف أطعموا فأطعمنا. وحملوا فحملنا. وأعطوا فأعطينا. حتى إذا تجاثينا على الركب وكنا كفرسي رهان. قالوا: منا نبي يأتيه الوحي من السماء! فمتى ندرك هذا؟ والله لا نسمع له أبدا. ولا نصدقه أبدا \".", 99, 126], ["بعث قريش النضر بن الحارث وعقبة إلى أحبار المدينة", "قال ابن إسحاق عن ابن عباس: بعثت قريش النضر بن الحارث وعقبة بن أبي معيط، إلى أحبار اليهود بالمدينة فقالوا لهما: سلاهم عن محمد وصفا لهم صفته. فإنهم أهل الكتاب. وعنده ما ليس عندنا من علم الأنبياء.", 100, 127], ["نزول سورة الكهف وآية الروح جوابا لسؤالهم", "فجاءوا رسول الله صلى الله عليه وسلم فسألوه عما أخبرهم أحبار يهود. فجاءه جبريل بسورة الكهف فيها خبر ما سألوه عنه. من الفتية والرجل الطواف. وجاءه بقوله {ويسألونك عن الروح} [الإسراء: 85]- الآية (1) .", 100, 128], ["سماع الوليد بن المغيرة القرآن", "وعن ابن عباس قال «إن الوليد بن المغيرة جاء إلى النبي -صلى الله عليه وسلم - فقال اقرأ علي. فقرأ عليه {إن الله يأمر بالعدل والإحسان وإيتاء ذي القربى} [النحل: 90]- الآية (1) فقال أعد. فأعاد. فقال والله إن له لحلاوة. وإن عليه لطلاوة. وإن أعلاه لمثمر. وإن أسفله لمغدق. وإنه ليعلو ولا يعلى عليه. وإنه ليحطم ما تحته. وما يقول هذا بشر» .", 102, 129], ["اتفاق قريش في الموسم على قول: ساحر", "وفي رواية أن الوليد بن المغيرة قال لهم - وقد حضر الموسم - \" ستقدم عليكم وفود العرب من كل جانب وقد سمعوا بأمر صاحبكم. فأجمعوا فيه رأيا، ولا تختلفوا، فيكذب بعضكم بعضا. فقالوا: فأنت فقل. فقال بل قولوا وأنا أسمع. قالوا: نقول كاهن. قال ما هو بزمرة الكهان ولا سجعهم. قالوا نقول مجنون قال ما هو بمجنون. لقد رأينا الجنون وعرفناه. فما هو بخنقه ولا وسوسته ولا تخالجه. قالوا: نقول شاعر. قال ما هو بشاعر. لقد عرفنا الشعر رجزه وهزجه وقريضه. ومقبوضه ومبسوطه قالوا: نقول ساحر قال ما هو بساحر. لقد رأينا السحرة وسحرهم فما هو بعقدهم ولا نفثهم قالوا: فما نقول يا أبا عبد شمس؟ قال ما نقول من شيء من هذا إلا عرف أنه باطل وإن أقرب القول أن تقولوا: ساحر يفرق بين المرء وأخيه وبين المرء وزوجه وبين المرء وعشيرته فتفرقوا عنه بذلك. فجعلوا يجلسون للناس لا يمر بهم أحد إلا حذروه رسول الله -صلى الله عليه وسلم -.", 103, 130], ["نزول آيات المدثر في الوليد بن المغيرة", "فأنزل الله في الوليد بن المغيرة {ذرني ومن خلقت وحيدا} [المدثر: 11]- إلى قوله - {سأصليه سقر} [المدثر: 26] (1) . ونزل في النفر الذين كانوا معه يصنفون القول في رسول الله صلى الله عليه وسلم وفيما جاء به من عند الله {الذين جعلوا القرآن عضين} [الحجر: 91] (2) أي أصنافا. وكانوا يسألون رسول الله -صلى الله عليه وسلم - الآيات فمنها ما يأتيهم الله به لحكمة أرادها الله سبحانه.", 103, 131], ["نزول آية عضين في النفر الذين معه", "فأنزل الله في الوليد بن المغيرة {ذرني ومن خلقت وحيدا} [المدثر: 11]- إلى قوله - {سأصليه سقر} [المدثر: 26] (1) . ونزل في النفر الذين كانوا معه يصنفون القول في رسول الله صلى الله عليه وسلم وفيما جاء به من عند الله {الذين جعلوا القرآن عضين} [الحجر: 91] (2) أي أصنافا. وكانوا يسألون رسول الله -صلى الله عليه وسلم - الآيات فمنها ما يأتيهم الله به لحكمة أرادها الله سبحانه.", 103, 132], ["انشقاق القمر", "فمن ذلك أنهم سألوه أن يريهم آية فأراهم انشقاق القمر. وأنزل قوله {اقتربت الساعة وانشق القمر} [القمر: 1]- الآيات - إلى قوله {وكل أمر مستقر} [القمر: 3] (3) فقالوا: سحركم انظروا إلى السفار فإن كانوا رأوا مثل ما رأيتم فقد صدق. فقدموا من كل وجه. فقالوا: رأينا.", 104, 133], ["سؤال أهل مكة أن يجعل لهم الصفا ذهبا", "بين سبحانه وتعالى: أنه إنما منعه أن يرسل بها إلا أن كذب بها الأولون فإذ كذب هؤلاء كذلك استحقوا عذاب الاستئصال. وروى أهل التفسير وأهل الحديث عن ابن عباس. قال «سأله أهل مكة أن يجعل لهم الصفا ذهبا وأن ينحي عنهم الجبال حتى يزرعوا. فقيل له إن شئت نستأني بهم وإن شئت أن نؤتيهم الذي سألوا، فإن كفروا هلكوا، كما هلك من قبلهم. فقال بل أستأني بهم فأنزل الله {وما منعنا أن نرسل بالآيات إلا أن كذب بها الأولون} [الإسراء: 59] » - الآية.", 105, 134], ["افتراس الأسد من دعا عليه النبي ﷺ", "وكان من حكمته تعالى ورحمته - لما أرسل محمدا -صلى الله عليه وسلم - خاتم المرسلين - ألا يهلك قومه بعذاب الاستئصال بل عذب بعضهم بأنواع العذاب كالمستهزئين الذين قال الله فيهم {إنا كفيناك المستهزئين} [الحجر: 95]- الآيات (4) . والذي دعا عليه النبي -صلى الله عليه وسلم - أن يسلط عليه كلبا من كلابه فافترسه الأسد كما قال تعالى {قل هل تربصون بنا إلا إحدى الحسنيين ونحن نتربص بكم أن يصيبكم الله بعذاب من عنده} [التوبة: 52]- الآية (5) . فأخبر سبحانه أنه يعذب الكفار تارة بأيدي المؤمنين بالجهاد والحدود وتارة بغير ذلك.", 108, 135], ["خروجه ﷺ إلى الطائف", "ولما اشتد البلاء من قريش على رسول الله -صلى الله عليه وسلم - بعد موت عمه خرج إلى الطائف، رجاء أن يؤووه وينصروه على قومه ويمنعوه منهم حتى يبلغ رسالة ربه. ودعاهم إلى الله عز وجل فلم ير من يؤوي ولم ير ناصرا، وآذوه أشد الأذى. ونالوا منه ما لم ينل قومه. وكان معه زيد بن حارثة مولاه. فأقام بينهم عشرة أيام. لا يدع أحدا من أشرافهم إلا كلمه فقالوا: اخرج من بلدنا. وأغروا به سفهاءهم. فوقفوا له سماطين. وجعلوا يرمونه بالحجارة وبكلمات من السفه هي أشد وقعا من الحجارة. حتى دميت قدماه وزيد بن حارثة يقيه بنفسه حتى أصابه شجاج في رأسه فانصرف إلى مكة محزونا.", 111, 136], ["إقامته بالطائف ورميه بالحجارة", "ولما اشتد البلاء من قريش على رسول الله -صلى الله عليه وسلم - بعد موت عمه خرج إلى الطائف، رجاء أن يؤووه وينصروه على قومه ويمنعوه منهم حتى يبلغ رسالة ربه. ودعاهم إلى الله عز وجل فلم ير من يؤوي ولم ير ناصرا، وآذوه أشد الأذى. ونالوا منه ما لم ينل قومه. وكان معه زيد بن حارثة مولاه. فأقام بينهم عشرة أيام. لا يدع أحدا من أشرافهم إلا كلمه فقالوا: اخرج من بلدنا. وأغروا به سفهاءهم. فوقفوا له سماطين. وجعلوا يرمونه بالحجارة وبكلمات من السفه هي أشد وقعا من الحجارة. حتى دميت قدماه وزيد بن حارثة يقيه بنفسه حتى أصابه شجاج في رأسه فانصرف إلى مكة محزونا.", 111, 137], ["دعاؤه ﷺ في مرجعه من الطائف", "وفي مرجعه دعا بالدعاء المشهور «اللهم إني أشكو إليك ضعف قوتي وقلة حيلتي، وهواني على الناس أنت رب المستضعفين وأنت ربي، إلى من تكلني؟ إلى بعيد يتجهمني، أو إلى عدو ملكته أمري؟ إن لم يكن بك غضب علي فلا أبالي، غير أن عافيتك هي أوسع لي. أعوذ بنور وجهك الذي أشرقت له الظلمات وصلح عليه أمر الدنيا والآخرة أن يحل علي غضبك، أو ينزل بي سخطك. لك العتبى حتى ترضى. ولا حول ولا قوة إلا بك» (1) .", 112, 138], ["إرسال ملك الجبال إليه", "فأرسل ربه تبارك وتعالى إليه ملك الجبال يستأمره أن يطبق الأخشبين على أهل مكة - وهما جبلاها اللذان هي بينهما فقال «بل أستأني بهم لعل الله أن يخرج من أصلابهم من يعبده لا يشرك به شيئا» .", 112, 139], ["استماع نفر من الجن قراءته بنخلة", "فلما نزل بنخلة في مرجعه قام يصلي من الليل ما شاء الله فصرف الله إليه نفرا من الجن. فاستمعوا قراءته ولم يشعر بهم رسول الله -صلى الله عليه وسلم - حتى نزل عليه {وإذ صرفنا إليك نفرا من الجن} [الأحقاف: 29]- إلى قوله - {أولئك في ضلال مبين} [الأحقاف: 32] (1) . وأقام بنخلة أياما. فقال زيد بن حارثة -رضي الله عنه- كيف تدخل عليهم وقد أخرجوك؟ - يعني قريشا - فقال «يا زيد إن الله جاعل لما ترى فرجا ومخرجا. وإن الله ناصر دينه ومظهر نبيه» .", 112, 140], ["دخوله مكة في جوار المطعم بن عدي", "ثم انتهى إلى مكة. فأرسل رجلا من خزاعة إلى المطعم بن عدي أدخل في جوارك؟ فقال نعم. فدعا المطعم بنيه وقومه فقال البسوا السلاح وكونوا عند أركان البيت. فإني قد أجرت محمدا. فلا يهجه أحد فانتهى رسول الله -صلى الله عليه وسلم - إلى الركن فاستلمه. وصلى ركعتين. وانصرف إلى بيته والمطعم بن عدي وولده محدقون به في السلاح حتى دخل بيته.", 113, 141], ["الإسراء والمعراج", "ثم أسري برسول الله -صلى الله عليه وسلم - إلى بيت القدس راكبا على البراق صحبة جبريل عليه السلام. فنزل هناك. وصلى بالأنبياء إماما. وربط البراق بحلقة باب المسجد. ثم عرج به إلى السماء الدنيا. فرأى فيها آدم. ورأى أرواح السعداء عن يمينه والأشقياء عن شماله. ثم إلى الثانية. فرأى فيها عيسى ويحيى. ثم إلى الثالثة. فرأى فيها يوسف. ثم إلى الرابعة. فرأى فيها إدريس. ثم إلى الخامسة. فرأى فيها هارون. ثم إلى السادسة. فرأى فيها موسى. فلما جاوزه بكى. فقيل له ما يبكيك؟ قال أبكي أن غلاما بعث بعدي يدخل الجنة من أمته أكثر مما يدخلها من أمتي. ثم عرج به إلى السماء السابعة. فلقي فيها إبراهيم. ثم إلى سدرة المنتهى. ثم رفع إلى البيت المعمور. فرأى هناك جبريل في صورته له ستمائة جناح. وهو قوله تعالى {ولقد رآه نزلة أخرى - عند سدرة المنتهى} [النجم: 13 - 14] (1) . وكلمه ربه وأعطاه ما أعطاه. وأعطاه الصلاة. فكانت قرة عين رسول الله -صلى الله عليه وسلم -", 113, 142], ["إعطاؤه الصلاة", "ثم أسري برسول الله -صلى الله عليه وسلم - إلى بيت القدس راكبا على البراق صحبة جبريل عليه السلام. فنزل هناك. وصلى بالأنبياء إماما. وربط البراق بحلقة باب المسجد. ثم عرج به إلى السماء الدنيا. فرأى فيها آدم. ورأى أرواح السعداء عن يمينه والأشقياء عن شماله. ثم إلى الثانية. فرأى فيها عيسى ويحيى. ثم إلى الثالثة. فرأى فيها يوسف. ثم إلى الرابعة. فرأى فيها إدريس. ثم إلى الخامسة. فرأى فيها هارون. ثم إلى السادسة. فرأى فيها موسى. فلما جاوزه بكى. فقيل له ما يبكيك؟ قال أبكي أن غلاما بعث بعدي يدخل الجنة من أمته أكثر مما يدخلها من أمتي. ثم عرج به إلى السماء السابعة. فلقي فيها إبراهيم. ثم إلى سدرة المنتهى. ثم رفع إلى البيت المعمور. فرأى هناك جبريل في صورته له ستمائة جناح. وهو قوله تعالى {ولقد رآه نزلة أخرى - عند سدرة المنتهى} [النجم: 13 - 14] (1) . وكلمه ربه وأعطاه ما أعطاه. وأعطاه الصلاة. فكانت قرة عين رسول الله -صلى الله عليه وسلم -", 113, 143], ["إخباره قومه بالإسراء وتكذيبهم", "فلما أصبح رسول الله -صلى الله عليه وسلم - في قومه وأخبرهم اشتد تكذيبهم له وسألوه أن يصف لهم بيت المقدس. فجلاه الله له حتى عاينه. وجعل يخبرهم به. ولا يستطيعون أن يردوا عليه شيئا. وأخبرهم عن عيرهم التي رآها في مسراه ومرجعه وعن وقت قدومها، وعن البعير الذي يقدمها. فكان كما قال. فلم يزدهم ذلك إلا ثبورا. وأبى الظالمون إلا كفورا.", 114, 144], ["عرضه ﷺ نفسه على الحاج في الموسم", "قد ذكرنا: أنه -صلى الله عليه وسلم - كان يوافي الموسم كل عام يتبع الحاج في منازلهم وفي عكاظ وغيرها. يدعوهم إلى الله. فلم يجبه أحد منهم. ولم يأوه. فكان ممن صنع الله لرسوله أن الأوس والخزرج كانوا يسمعون من حلفائهم يهود المدينة: أن نبيا يبعث في هذا الزمان فنتبعه ونقتلكم معه قتل عاد.", 115, 145], ["بيعة العقبة الأولى: إسلام ستة نفر من الخزرج", "فلقي رسول الله -صلى الله عليه وسلم - عند العقبة: ستة نفر من الأنصار كلهم من الخزرج. منهم أسعد بن زرارة وجابر بن عبد الله بن رئاب السلمي. فدعاهم إلى الإسلام فأسلموا. ثم رجعوا إلى المدينة، فدعوا إلى الإسلام. فنشأ الإسلام فيها، حتى لم تبق دار إلا ودخلها. فلما كان العام المقبل جاء منهم اثنا عشر رجلا - الستة الأول. خلا جابرا - ومعهم عبادة بن الصامت، وأبو الهيثم بن التيهان، وغيرهم. الجميع اثنا عشر رجلا.", 115, 146], ["قدوم اثني عشر رجلا من الأنصار في العام المقبل", "فلقي رسول الله -صلى الله عليه وسلم - عند العقبة: ستة نفر من الأنصار كلهم من الخزرج. منهم أسعد بن زرارة وجابر بن عبد الله بن رئاب السلمي. فدعاهم إلى الإسلام فأسلموا. ثم رجعوا إلى المدينة، فدعوا إلى الإسلام. فنشأ الإسلام فيها، حتى لم تبق دار إلا ودخلها. فلما كان العام المقبل جاء منهم اثنا عشر رجلا - الستة الأول. خلا جابرا - ومعهم عبادة بن الصامت، وأبو الهيثم بن التيهان، وغيرهم. الجميع اثنا عشر رجلا.", 115, 147], ["الحرب بين الأوس والخزرج", "فوقعت بينهم العداوة بسبب قتيل فلبثت بينهم الحرب مائة وعشرين سنة إلى أن أطفأها الله بالإسلام. وألف بينهم برسول الله -صلى الله عليه وسلم - وذلك قوله {واذكروا نعمت الله عليكم إذ كنتم أعداء فألف بين قلوبكم فأصبحتم بنعمته إخوانا} [آل عمران: 103]- الآية (1) .", 116, 148], ["بعث مصعب بن عمير إلى المدينة", "فلما انصرفوا بعث معهم رسول الله -صلى الله عليه وسلم - مصعب بن عمير، وأمره أن يقرئهم القرآن ويعلمهم الإسلام. فنزل على أبي أمامة - أسعد بن زرارة - فخرج بمصعب - في إحدى خريجاته - فدخل به حائطا من حيطان بني ظفر. فجلسا فيه واجتمع إليهما رجال ممن أسلم.", 116, 149], ["إسلام أسيد بن حضير", "ثم قال ما أحسن هذا وما أجمله! كيف تصنعون إذا أردتم أن تدخلوا في هذا الدين؟ . قالا له تغتسل وتطهر ثوبك. ثم تشهد شهادة الحق. ثم تصلي ركعتين. فقام واغتسل. وطهر ثوبه. وتشهد وصلى ركعتين. ثم قال إن ورائي رجلا إن تبعكما لم يتخلف عنه أحد من قومه. وسأرشده إليكما الآن - سعد بن معاذ - ثم أخذ حربته وانصرف إلى سعد في قومه وهم جلوس في ناديهم.", 117, 150], ["إسلام سعد بن معاذ", "فعرض عليه الإسلام وقرأ عليه القرآن. قال فعرفنا والله في وجهه الإسلام قبل أن يتكلم في إشراقه وتهلله. ثم قال كيف تصنعون إذا أسلمتم؟ قالا: تغتسل وتطهر ثوبك ثم تشهد شهادة الحق. ثم تصلي ركعتين ففعل ذلك. ثم أخذ حربته. فأقبل إلى نادي قومه. فلما رأوه قالوا: نحلف بالله لقد رجع بغير الوجه الذي ذهب به فقال يا بني عبد الأشهل كيف أمري فيكم؟ قالوا: سيدنا. وابن سيدنا، وأفضلنا رأيا، وأيمننا نقيبة. قال فإن كلام رجالكم ونسائكم علي حرام حتى تؤمنوا بالله ورسوله. فما أمسى فيهم رجل ولا امرأة إلا أسلموا، إلا الأصيرم. فإنه تأخر إسلامه إلى يوم أحد.", 118, 151], ["إسلام بني عبد الأشهل", "فعرض عليه الإسلام وقرأ عليه القرآن. قال فعرفنا والله في وجهه الإسلام قبل أن يتكلم في إشراقه وتهلله. ثم قال كيف تصنعون إذا أسلمتم؟ قالا: تغتسل وتطهر ثوبك ثم تشهد شهادة الحق. ثم تصلي ركعتين ففعل ذلك. ثم أخذ حربته. فأقبل إلى نادي قومه. فلما رأوه قالوا: نحلف بالله لقد رجع بغير الوجه الذي ذهب به فقال يا بني عبد الأشهل كيف أمري فيكم؟ قالوا: سيدنا. وابن سيدنا، وأفضلنا رأيا، وأيمننا نقيبة. قال فإن كلام رجالكم ونسائكم علي حرام حتى تؤمنوا بالله ورسوله. فما أمسى فيهم رجل ولا امرأة إلا أسلموا، إلا الأصيرم. فإنه تأخر إسلامه إلى يوم أحد.", 118, 152], ["إسلام الأصيرم وقتله يوم أحد", "فعرض عليه الإسلام وقرأ عليه القرآن. قال فعرفنا والله في وجهه الإسلام قبل أن يتكلم في إشراقه وتهلله. ثم قال كيف تصنعون إذا أسلمتم؟ قالا: تغتسل وتطهر ثوبك ثم تشهد شهادة الحق. ثم تصلي ركعتين ففعل ذلك. ثم أخذ حربته. فأقبل إلى نادي قومه. فلما رأوه قالوا: نحلف بالله لقد رجع بغير الوجه الذي ذهب به فقال يا بني عبد الأشهل كيف أمري فيكم؟ قالوا: سيدنا. وابن سيدنا، وأفضلنا رأيا، وأيمننا نقيبة. قال فإن كلام رجالكم ونسائكم علي حرام حتى تؤمنوا بالله ورسوله. فما أمسى فيهم رجل ولا امرأة إلا أسلموا، إلا الأصيرم. فإنه تأخر إسلامه إلى يوم أحد.\nفأسلم وقاتل وقتل ولم يسجد لله سجدة.", 119, 153], ["انتشار الإسلام في دور الأنصار", "فقال النبي -صلى الله عليه وسلم - «عمل قليلا وأجر كثيرا» . فأقام مصعب في منزل أسعد يدعو الناس إلى الإسلام حتى لم يبق دار من دور الأنصار إلا وفيها رجال ونساء مسلمون إلا ما كان من دار بني أمية بن زيد وخطمة ووائل وواقف.", 119, 154], ["تأخر إسلام بعض دور الأنصار حتى عام الخندق", "وذلك أنهم كان فيهم قيس بن الأسلت الشاعر. وكانوا يسمعون منه فوقف بهم عن الإسلام حتى كان عام الخندق، بعد أن هاجر رسول الله -صلى الله عليه وسلم -.", 119, 155], ["خروج من أسلم من الأنصار حجاجا", "فلما كان من العام المقبل. وجاء موسم الحج. قال من أسلم من الأنصار: حتى متى نترك رسول الله -صلى الله عليه وسلم - يطرد في جبال مكة ويخاف؟ ! فخرجوا مع مشركي قومهم حجاجا.", 119, 156], ["بيعة العقبة الثانية", "فلما وصلوا واعدوه العقبة، من أواسط أيام التشريق للبيعة بعد ما انقضى حجهم. فقال له العباس ما أدري ما هؤلاء القوم الذين جاءوك؟ إني ذو معرفة بأهل يثرب. فلما كان الليل تسللوا من رحالهم مختفين ومعهم عبد الله بن عمرو بن حرام - أبو جابر - وهو مشرك وكانوا يكاتمونه الأمر. فلما كانت الليلة التي واعدوا فيها رسول الله -صلى الله عليه وسلم - قالوا: يا أبا جابر، إنك شريف من أشرافنا. وإنا نرغب بك أن تكون حطبا للنار غدا، قال وما ذلك؟ فأخبروه الخبر فأسلم وشهد العقبة وكان نقيبا.", 119, 157], ["إسلام عبد الله بن عمرو بن حرام أبي جابر", "فلما وصلوا واعدوه العقبة، من أواسط أيام التشريق للبيعة بعد ما انقضى حجهم. فقال له العباس ما أدري ما هؤلاء القوم الذين جاءوك؟ إني ذو معرفة بأهل يثرب. فلما كان الليل تسللوا من رحالهم مختفين ومعهم عبد الله بن عمرو بن حرام - أبو جابر - وهو مشرك وكانوا يكاتمونه الأمر. فلما كانت الليلة التي واعدوا فيها رسول الله -صلى الله عليه وسلم - قالوا: يا أبا جابر، إنك شريف من أشرافنا. وإنا نرغب بك أن تكون حطبا للنار غدا، قال وما ذلك؟ فأخبروه الخبر فأسلم وشهد العقبة وكان نقيبا.", 119, 158], ["اجتماع الأنصار به ﷺ ليلا وكلام العباس", "فلما مضى ثلث الليل خرجوا للميعاد حتى اجتمع عنده من رجل ورجلين ومعه عمه العباس - وهو يومئذ على دين قومه - ولكنه أحب أن يحضر أمر ابن أخيه ويتوثق له.", 120, 159], ["مبايعة الأنصار وأولهم البراء بن معرور", "فكان أول من بايعه البراء بن معرور. فقال والذي بعثك بالحق لنمنعنك مما نمنع منه أزرنا. فبايعنا يا رسول الله. فنحن أهل الحرب والحلقة ورثناها صاغرا عن كابر. فاعترضه أبو الهيثم بن التيهان، وقال إن بيننا وبين الناس حبالا ونحن قاطعوها، فهل عسيت - إن أظهرك الله -: أن ترجع إلى قومك وتدعنا؟ فتبسم رسول الله -صلى الله عليه وسلم - ثم قال «لا والله بل الدم الدم والهدم الهدم أنتم مني وأنا منكم. أحارب من حاربتم. وأسالم من سالمتم» .", 121, 160], ["اختيار اثني عشر نقيبا", "ثم قال رسول الله -صلى الله عليه وسلم - «أخرجوا إلي منكم اثني عشر نقيبا كفلاء على قومهم ككفالة الحواريين لعيسى ابن مريم وأنا كفيل على قومي» وفي رواية \" أن «موسى اتخذ من قومه اثني عشر نقيبا» (1) .", 121, 161], ["صراخ الشيطان بعد بيعة العقبة", "فلما بايعوه صرخ الشيطان بأنفذ صوت سمع قط يا أهل الأخاشب هل لكم في محمد والصبأة معه؟ قد اجتمعوا على حربكم. فقال رسول الله -صلى الله عليه وسلم - «هذا أزب العقبة أما والله يا عدو الله لأفرغن لك ثم قال رسول الله -صلى الله عليه وسلم - ارفضوا إلى رحالكم.", 122, 162], ["غدو جلة قريش على الأنصار", "فلما أصبحوا غدت عليهم جلة قريش. فقالوا: إنه بلغنا أنكم جئتم صاحبنا البارحة تستخرجونه من بين أظهرنا، وتبايعونه على حربنا. وإن الله ما من حي من العرب أبغض إلينا من أن تنشب الحرب بيننا وبينهم منكم. فانبعث رجال - ممن لم يعلم - يحلفون لهم بالله ما كان من هذا شيء والذين يشهدون ينظر بعضهم إلى بعض. وجعل عبد الله بن أبي ابن سلول يقول هذا باطل. ما كان هذا. وما كان قومي ليفتاتوا علي بمثل هذا. لو كنت بيثرب ما صنع قومي هذا. حتى يؤامروني.", 122, 163], ["أسر قريش سعد بن عبادة", "فلما انفصلت الأنصار عن مكة: صح الخبر عند قريش. فخرجوا في طلبهم فأدركوا سعد بن عبادة، والمنذر بن عمرو. فأعجزهم المنذر ومضى. وأما سعد فقالوا له أنت على دين محمد؟ قال نعم فربطوا يديه إلى عنقه بنسعة رحله. وجعلوا يسحبونه بشعره ويضربونه - وكان ذا جمة - حتى أدخلوه مكة، فجاء المطعم بن عدي والحارث بن حرب بن أمية. فخلصاه من أيديهم.", 123, 164], ["هاتف على أبي قبيس بالسعدين", "وسمعت قريش قائلا يقول بالليل على أبي قبيس:", 124, 165], ["الإذن للمسلمين بالهجرة إلى المدينة", "وأذن رسول الله -صلى الله عليه وسلم - للمسلمين في الهجرة إلى المدينة. فبادروا إليها. وأول من خرج أبو سلمة بن عبد الأسد وزوجته أم سلمة. ولكنها حبست عنه سنة وحيل بينها وبين ولدها. ثم خرجت بعد هي وولدها إلى المدينة.", 125, 166], ["تآمر قريش بدار الندوة", "فلما رأى المشركون أصحاب رسول الله -صلى الله عليه وسلم - قد تجهزوا وخرجوا بأهليهم إلى المدينة: عرفوا أن الدار دار منعة وأن القوم أهل حلقة وبأس فخافوا خروج رسول الله -صلى الله عليه وسلم - فيشتد أمره عليهم. فاجتمعوا في دار الندوة. وحضرهم إبليس في صورة شيخ من أهل نجد.", 125, 167], ["إذن الله لرسوله في الخروج وصحبة أبي بكر", "«وجاء رسول الله -صلى الله عليه وسلم - إلى أبي بكر نصف النهار - في ساعة لم يكن يأتيه فيها - متقنعا، فقال: \" أخرج من عندك \" فقال: إنما هم أهلك يا رسول الله. فقال رسول الله -صلى الله عليه وسلم -: \" إن الله قد أذن لي في الخروج \" فقال أبو بكر: الصحبة يا رسول الله. قال: \" نعم \" فقال أبو بكر: فخذ - بأبي أنت وأمي - إحدى راحلتي هاتين فقال: بالثمن» .", 126, 168], ["مبيت علي على الفراش وخروج النبي ﷺ عليهم", "وأمر عليا أن يبيت تلك الليلة على فراشه.", 126, 169], ["خروج رسول الله ﷺ وأبي بكر إلى غار ثور", "ومضى رسول الله -صلى الله عليه وسلم - إلى بيت أبي بكر. فخرجا من خوخة في بيت أبي بكر ليلا. فجاء رجل فرأى القوم ببابه، فقال: ما تنتظرون؟ قالوا: محمدا. قال: خبتم وخسرتم قد والله مر بكم وذر على رءوسكم التراب. قالوا: والله ما أبصرناه وقاموا ينفضون التراب عن رءوسهم.", 127, 170], ["وصول قريش إلى باب الغار", "وجدت قريش في طلبهما، وأخذوا معهم القافة حتى انتهوا إلى باب الغار. فوقفوا عليه. فقال أبو بكر «يا رسول الله لو أن أحدهم نظر إلى ما تحت قدميه لأبصرنا. فقال: ما ظنك باثنين الله ثالثهما؟ لا تحزن إن الله معنا.»", 127, 171], ["تلقيب أسماء ذات النطاقين", "قالت عائشة: فجهزناهما أحث الجهاز. وصنعنا لهما سفرة في جراب. فقطعت أسماء بنت أبي بكر. قطعة من نطاقها، فأوكت به فم الجراب وقطعت الأخرى عصاما للقربة. فبذلك لقبت \" ذات النطاقين \".", 128, 172], ["الارتحال من الغار بعد ثلاث", "ومكثا في الغار ثلاثا. حتى خمدت نار الطلب. فجاءهما ابن أريقط بالراحلتين فارتحلا، وأردف أبو بكر عامر بن فهيرة.", 128, 173], ["قصة سراقة بن مالك", "ففطن بالأمر سراقة بن مالك، فأراد أن يكون الظفر له. وقد سبق له من الظفر ما لم يكن في حسابه. فقال: بل هما فلان وفلان خرجا في طلب حاجة لهما. ثم مكث قليلا. ثم قام فدخل خباءه وقال لجاريته: أخرجي بالفرس من وراء الخباء وموعدك وراء الأكمة. ثم أخذ رمحه وخفض عاليه يخط به الأرض حتى ركب فرسه. فلما قرب منهم وسمع قراءة النبي -صلى الله عليه وسلم - وأبو بكر يكثر الالتفات ورسول الله -صلى الله عليه وسلم - لا يلتفت - قال أبو بكر: يا رسول الله هذا سراقة بن مالك قد رهقنا. فدعا عليه رسول الله -صلى الله عليه وسلم - فساخت يدا فرسه في الأرض.", 128, 174], ["قصة أم معبد", "قصة أم معبد ثم مروا بخيمة أم معبد الخزاعية، وكانت امرأة برزة جلدة تحتبي بفناء الخيمة ثم تطعم وتسقي من مر بها، فسألاها: هل عندها شيء يشترونه؟ فقالت والله لو عندنا شيء ما أعوزكم القرى. والشاء عازب - وكانت سنة شهباء - فنظر رسول الله -صلى الله عليه وسلم - إلى شاة في كسر الخيمة فقال «ما هذه الشاة؟» قالت خلفها الجهد عن الغنم. فقال «هل بها من لبن؟» قالت: هي أجهد من ذلك. قال «أتأذنين لي أن أحلبها؟» قالت: نعم - بأبي أنت وأمي - إن رأيت بها حليبا فاحلبها.", 129, 175], ["صوت بمكة بخبر خيمة أم معبد", "وأصبح صوت عال بمكة يسمعونه ولا يرون القائل يقول:", 130, 176], ["أبو قحافة وأسماء ومال أبي بكر", "قالت ولما خرج أبو بكر احتمل معه ماله. فدخل علينا جدي أبو قحافة - وقد ذهب بصره - فقال: إني والله لأراه قد فجعكم بماله مع نفسه. قلت: كلا والله قد ترك لنا خيرا. وأخذت حجارة فوضعتها في كوة البيت. وقلت: ضع يدك على المال. فوضعها، وقال: لا بأس. إن كان قد ترك لكم هذا فقد أحسن، قالت: والله ما ترك لنا شيئا وإنما أردت أن أسكت الشيخ.", 132, 177], ["دخول رسول الله ﷺ المدينة", "ولما بلغ الأنصار مخرج رسول الله -صلى الله عليه وسلم - من مكة. كانوا يخرجون كل يوم إلى الحرة ينتظرونه. فإذا اشتد حر الشمس رجعوا إلى منازلهم. فلما كان يوم الاثنين ثاني عشر ربيع الأول على رأس ثلاث عشرة سنة من نبوته. خرجوا على عادتهم. فلما حميت الشمس رجعوا، فصعد رجل من اليهود على أطم من آطام المدينة. فرأى رسول الله -صلى الله عليه وسلم - وأصحابه مبيضين يزول بهم السراب. فصرخ بأعلى صوته يا بني قيلة هذا صاحبكم قد جاء هذا جدكم الذي تنتظرونه. فثار الأنصار إلى السلاح ليتلقوا رسول الله -صلى الله عليه وسلم -.", 132, 178], ["نزوله بقباء في بني عمرو بن عوف", "فلما أتى المدينة، عدل ذات اليمين حتى نزل بقباء في بني عمرو بن عوف، ونزل على كلثوم بن الهدم - أو على سعد بن خيثمة - فأقام في بني عمرو بن عوف أربع عشرة ليلة. وأسس مسجد قباء. وهو أول مسجد أسس بعد النبوة.", 132, 179], ["تأسيس مسجد قباء", "فلما أتى المدينة، عدل ذات اليمين حتى نزل بقباء في بني عمرو بن عوف، ونزل على كلثوم بن الهدم - أو على سعد بن خيثمة - فأقام في بني عمرو بن عوف أربع عشرة ليلة. وأسس مسجد قباء. وهو أول مسجد أسس بعد النبوة.", 132, 180], ["الجمعة في بني سالم بن عوف", "فلما كان يوم الجمعة ركب. فأدركته الجمعة في بني سالم بن عوف. فجمع بهم في المسجد الذي في بطن الوادي. ثم ركب. فأخذوا بخطام راحلته يقولون. هلم إلى القوة والمنعة والسلاح. فيقول «خلوا سبيلها. فإنها مأمورة» فلم تزل ناقته سائرة لا يمر بدار من دور الأنصار، إلا رغبوا إليه في النزول عليهم فيقول: «دعوها فإنها مأمورة» فسارت حتى وصلت إلى موضع مسجده اليوم فبركت ولم ينزل عنها، حتى نهضت وسارت قليلا. ثم رجعت وبركت في موضعها الأول. فنزل عنها.", 133, 181], ["بروك الناقة ونزوله على أبي أيوب", "وكان من توفيق الله لها. فإنه أحب أن ينزل على أخواله يكرمهم. فجعل الناس يكلمونه في النزول عليهم. وبادر أبو أيوب خالد بن زيد إلى رحله فأدخله بيته. فجعل رسول الله -صلى الله عليه وسلم - يقول: «المرء مع رحله» وجاء أسعد بن زرارة فأخذ بخطام ناقته. فكانت عنده. وأصبح كما قال قيس بن صرمة - وكان ابن عباس يختلف إليه ليحفظها عنه.", 133, 182], ["نزول «وقل رب أدخلني مدخل صدق»", "قال ابن عباس: كان النبي -صلى الله عليه وسلم - بمكة فأمر بالهجرة. وأنزل الله عليه، {وقل رب أدخلني مدخل صدق وأخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا} [الإسراء: 80] (1) والنبي -صلى الله عليه وسلم - يعلم ألا طاقة له بهذا الأمر إلا بسلطان. فسأل الله سلطانا نصيرا، فأعطاه. قال البراء.: أول من قدم علينا: مصعب بن عمير، وابن أم مكتوم، فجعلا يقرئان الناس القرآن. ثم جاء عمار بن ياسر، وبلال وسعد ثم جاء عمر بن الخطاب في عشرين راكبا. ثم جاء رسول الله -صلى الله عليه وسلم -. فما رأيت الناس فرحوا بشيء فرحهم به حتى جعل النساء والصبيان والإماء يقلن قدم رسول الله جاء رسول الله -صلى الله عليه وسلم -.", 134, 183], ["أول من قدم المدينة من المهاجرين", "قال ابن عباس: كان النبي -صلى الله عليه وسلم - بمكة فأمر بالهجرة. وأنزل الله عليه، {وقل رب أدخلني مدخل صدق وأخرجني مخرج صدق واجعل لي من لدنك سلطانا نصيرا} [الإسراء: 80] (1) والنبي -صلى الله عليه وسلم - يعلم ألا طاقة له بهذا الأمر إلا بسلطان. فسأل الله سلطانا نصيرا، فأعطاه. قال البراء.: أول من قدم علينا: مصعب بن عمير، وابن أم مكتوم، فجعلا يقرئان الناس القرآن. ثم جاء عمار بن ياسر، وبلال وسعد ثم جاء عمر بن الخطاب في عشرين راكبا. ثم جاء رسول الله -صلى الله عليه وسلم -. فما رأيت الناس فرحوا بشيء فرحهم به حتى جعل النساء والصبيان والإماء يقلن قدم رسول الله جاء رسول الله -صلى الله عليه وسلم -.", 134, 184], ["قدوم بنات رسول الله ﷺ وأهله من مكة", "وبعث رسول الله -صلى الله عليه وسلم - وهو في منزل أبي أيوب - زيد بن حارثة وأبا رافع. وأعطاهما بعيرين وخمسمائة درهم إلى مكة، فقدما عليه بفاطمة وأم كلثوم ابنتيه. وسودة بنت زمعة زوجه وأسامة بن زيد، وأم أيمن. وأما زينب فلم يمكنها زوجها أبو العاص بن الربيع من الخروج وخرج عبد الله بن أبي بكر بعيال أبي بكر. وفيهم عائشة.", 135, 185], ["بناء المسجد النبوي", "قال الزهري: بركت ناقة رسول الله -صلى الله عليه وسلم - عند موضع مسجده وكان مربدا لسهل وسهيل غلامين يتيمين من الأنصار، كانا في حجر أسعد بن زرارة. فساوم رسول الله -صلى الله عليه وسلم - الغلامين بالمربد ليتخذه مسجدا فقالا: بل نهبه لك يا رسول الله. فأبى رسول الله صلى الله عليه وسلم فاشتراه منهما بعشرة دنانير.", 136, 186], ["بناؤه بعائشة", "فلما فرغ من البناء بنى بعائشة في البيت الذي بناه لها شرقي المسجد. وكان بناؤه بها في شوال من السنة الأولى، وكان بعض الناس. يكره البناء في شوال. قيل إن أصله أن طاعونا وقع في الجاهلية وكانت عائشة تتحرى أن تدخل نساءها في شوال وتخالفهم. وجعل لسودة بيتا آخر.", 137, 187], ["المؤاخاة بين المهاجرين والأنصار", "ثم آخى بين المهاجرين والأنصار، وكانوا تسعين رجلا. نصفهم من المهاجرين، ونصفهم من الأنصار، آخى بينهم على المواساة وعلى أن يتوارثوا بعد الموت دون ذوي الأرحام. إلى وقعة بدر. فلما أنزل الله {وأولو الأرحام بعضهم أولى ببعض في كتاب الله} [الأنفال: 75] (1) رد التوارث إلى الأرحام.", 137, 188], ["رد التوارث إلى الأرحام", "ثم آخى بين المهاجرين والأنصار، وكانوا تسعين رجلا. نصفهم من المهاجرين، ونصفهم من الأنصار، آخى بينهم على المواساة وعلى أن يتوارثوا بعد الموت دون ذوي الأرحام. إلى وقعة بدر. فلما أنزل الله {وأولو الأرحام بعضهم أولى ببعض في كتاب الله} [الأنفال: 75] (1) رد التوارث إلى الأرحام.", 137, 189], ["وباء المدينة ومرض أبي بكر وبلال", "وفي الصحيح عن عائشة قالت \" قدم رسول الله -صلى الله عليه وسلم - المدينة وهي وبيئة. فمرض أبو بكر. وكان يقول إذا أخذته الحمى:", 137, 190], ["زيادة ركعتين في صلاة الحضر", "وفي السنة الأولى: زيد في صلاة الحضر ركعتان. فصارت أربع ركعات.", 138, 192], ["نزول أهل الصفة المسجد", "وفيها: نزل أهل الصفة المسجد. وكانت مكانا في المسجد ينزل فيه فقراء المهاجرين الذي لا أهل لهم ولا مال. وكان رسول الله -صلى الله عليه وسلم - يفرقهم في أصحابه إذا جاء الليل ويتعشى طائفة منهم معه حتى جاء الله بالغنى.", 138, 193], ["وفيات: أسعد بن زرارة والبراء وضمرة وكلثوم", "وتوفي فيها من الأعيان أسعد بن زرارة قبل أن يفرغ رسول الله -صلى الله عليه وسلم - من بناء المسجد. وتوفي البراء بن معرور في صفر قبل قدوم رسول الله -صلى الله عليه وسلم - المدينة. وهو أول من مات من النقباء. وفيها: توفي ضمرة بن جندب. وكان قد مرض بمكة. فقال لبنيه اخرجوا بي منها فخرجوا به يريد الهجرة. فلما بلغ أضاة بني عقار - أو التنعيم - مات. فأنزل الله تعالى {ومن يخرج من بيته مهاجرا إلى الله ورسوله ثم يدركه الموت فقد وقع أجره على الله} [النساء: 100]- الآية (1) .", 139, 194], ["موادعة يهود المدينة", "وكلثوم بن الهدم الذي نزل عليه رسول الله -صلى الله عليه وسلم -. وفيها: وادع رسول الله -صلى الله عليه وسلم - من بالمدينة من اليهود. وكتب بينه وبينهم كتابا.", 139, 195], ["إسلام عبد الله بن سلام", "وبادر عالم اليهود وحبرهم عبد الله بن سلام فأسلم. وأبى عامتهم إلا الكفر وكانوا ثلاث قبائل قينقاع والنضير وقريظة. فنقض الثلاث العهد. وحاربهم.", 139, 196], ["نقض اليهود العهد ومحاربتهم", "وبادر عالم اليهود وحبرهم عبد الله بن سلام فأسلم. وأبى عامتهم إلا الكفر وكانوا ثلاث قبائل قينقاع والنضير وقريظة. فنقض الثلاث العهد. وحاربهم.\nفمن على بني قينقاع وأجلى بني النضير. وقتل بني قريظة. ونزلت سورة الحشر في بني النضير وسورة الأحزاب في بني قريظة.", 139, 197], ["رؤيا الأذان", "حوادث السنة الثانية وفي السنة الثانية رأى عبد الله بن زيد بن عبد ربه الأذان فأمره رسول الله -صلى الله عليه وسلم - أن يلقيه على بلال.", 140, 199], ["فرض صوم رمضان", "وفيها: فرض صوم رمضان. ونسخ صوم عاشوراء. وبقي صومه مستحبا.", 140, 200], ["تزويج علي فاطمة", "وفيها: زوج رسول الله -صلى الله عليه وسلم - عليا فاطمة رضي الله عنهما.", 140, 201], ["تحويل القبلة إلى الكعبة", "وفيها: صرف الله عز وجل القبلة عن بيت المقدس إلى الكعبة.", 140, 202], ["الإذن في القتال ثم فرضه", "والله يأمر رسوله والمؤمنين بالكف والعفو والصفح حتى قويت الشوكة. فحينئذ أذن لهم في القتال ولم يفرضه عليهم فقال تعالى {أذن للذين يقاتلون بأنهم ظلموا وإن الله على نصرهم لقدير} [الحج: 39] (1) وهي أول آية نزلت في القتال.", 143, 203], ["أول لواء: لواء حمزة", "وأول لواء عقده رسول الله -صلى الله عليه وسلم - على قول موسى بن عقبة - لواء حمزة بن عبد المطلب في شهر رمضان في السنة الأولى، بعثه في ثلاثين رجلا من المهاجرين خاصة يعترض عيرا لقريش جاءت من الشام، فيها أبو جهل في ثلاثمائة رجل حتى بلغوا سيف البحر من ناحية العيص، فالتقوا واصطفوا للقتال فحجز بينهم مجدي بن عمرو الجهني. وكان موادعا للفريقين. فلم يقتتلوا.", 145, 204], ["سرية عبيدة بن الحارث", "ثم بعث عبيدة بن الحارث بن عبد المطلب بن عبد مناف في شوال من تلك السنة في سرية إلى بطن رابغ في ستين رجلا من المهاجرين خاصة. فلقي أبا سفيان عند رابغ. فكان بينهم الرمي. ولم يسلوا السيوف. وإنما كانت مناوشة.", 145, 205], ["سرية سعد بن أبي وقاص إلى الخرار", "ثم بعث سعد بن أبي وقاص في ذي القعدة من تلك السنة إلى الخرار من أرض الحجاز، يعترضون عيرا لقريش. وعهد إليه ألا يجاوز الخرار، وكانوا عشرين. فخرجوا على أقدامهم يسيرون بالليل ويكمنون بالنهار. حتى بلغوا الخرار، فوجدوا العير قد مرت بالأمس.", 145, 206], ["غزوة الأبواء", "فغزا فيها -صلى الله عليه وسلم - غزوة الأبواء. وكانت أول غزوة غزاها رسول الله -صلى الله عليه وسلم - بنفسه. خرج في المهاجرين خاصة يعترض عيرا لقريش فلم يلق كيدا. وفيها وادع بني ضمرة على ألا يغزوهم ولا يغزوه ولا يعينوا عليه أحدا.", 146, 207], ["موادعة بني ضمرة", "فغزا فيها -صلى الله عليه وسلم - غزوة الأبواء. وكانت أول غزوة غزاها رسول الله -صلى الله عليه وسلم - بنفسه. خرج في المهاجرين خاصة يعترض عيرا لقريش فلم يلق كيدا. وفيها وادع بني ضمرة على ألا يغزوهم ولا يغزوه ولا يعينوا عليه أحدا.", 146, 208], ["غزوة بواط", "ثم غزا بواطا في ربيع الأول. خرج يعترض عيرا لقريش فيها أمية بن خلف ومائة رجل من المشركين. فبلغ بواطا - جبلا من جبال جهينة - فرجع ولم يلق كيدا.", 146, 209], ["الخروج في طلب كرز بن جابر", "ثم خرج في طلب كرز بن جابر الفهري. وقد أغار على سرح المدينة، فاستاقه. فخرج رسول الله -صلى الله عليه وسلم - في أثره حتى بلغ سفوان من ناحية بدر وفاته كرز.", 146, 210], ["غزوة العشيرة", "ثم خرج في جمادى الآخرة في مائة وخمسين من المهاجرين يعترضون عيرا لقريش ذاهبة إلى الشام. وخرج في ثلاثين بعيرا يتعاقبونها. فبلغ ذا العشيرة من ناحية ينبع. فوجد العير فاتته بأيام. وهي التي خرجوا لها يوم بدر لما جاءت عائدة من الشام.", 146, 211], ["موادعة بني مدلج", "وفيها: وادع بني مدلج وحلفاءهم.", 147, 212], ["بعث عبد الله بن جحش إلى نخلة", "ثم بعث عبد الله بن جحش إلى نخلة في رجب في اثني عشر رجلا من المهاجرين كل اثنين على بعير. فوصلوا إلى نخلة، يرصدون عيرا لقريش. وكان رسول الله -صلى الله عليه وسلم - قد كتب له كتابا. وأمره ألا ينظر فيه حتى يسير يومين. فلما فتح الكتاب إذا فيه «إذا نظرت في كتابي هذا، فامض حتى تنزل بنخلة بين مكة والطائف، فترصد قريشا، وتعلم لنا أخبارها» .", 147, 213], ["قتل عمرو بن الحضرمي", "فمرت بهم عير قريش تحمل زبيبا وتجارة فيها عمرو بن الحضرمي، فقتلوه وأسروا عثمان ونوفلا ابني عبد الله بن المغيرة والحكم بن كيسان مولى بني المغيرة.", 147, 214], ["أول خمس وأول قتل وأول أسر ونزول آية الشهر الحرام", "فقال المسلمون نحن في آخر يوم من رجب. فإن قاتلناهم انتهكنا الشهر الحرام وإن تركناهم الليلة دخلوا الحرم. ثم أجمعوا على ملاقاتهم. فرمى أحدهم عمرو بن الحضرمي فقتله وأسروا عثمان والحكم. وأفلت نوفل. ثم قدموا بالعير والأسيرين حتى عزلوا من ذلك الخمس. فكان أول خمس في الإسلام وأول قتل في الإسلام وأول أسر. فأنكر رسول الله -صلى الله عليه وسلم - ما فعلوه.", 147, 215], ["وقعة بدر الكبرى", "فلما كان في رمضان بلغ رسول الله -صلى الله عليه وسلم - خبر العير المقبلة من الشام مع أبي سفيان فيها أموال قريش فندب رسول الله -صلى الله عليه وسلم - للخروج إليها فخرج مسرعا في ثلاثمائة وبضعة عشر رجلا. ولم يكن معهم من الخيل إلا فرسان فرس للزبير وفرس للمقداد بن الأسود. وكان معهم سبعون بعيرا يعتقب الرجلان والثلاثة على بعير. واستخلف على المدينة عبد الله بن أم مكتوم.", 149, 216], ["استصراخ أبي سفيان قريشا ونفيرهم", "وبلغ أبا سفيان مخرج رسول الله -صلى الله عليه وسلم -. فاستأجر ضمضم بن عمرو الغفاري. وبعثه حثيثا إلى مكة مستصرخا قريشا بالنفير إلى عيرهم. فنهضوا مسرعين. ولم يتخلف من أشرافهم سوى أبي لهب. فإنه عوض عنه رجلا بجعل. وحشدوا فيمن حولهم من قبائل العرب. ولم يتخلف عنهم من بطون قريش إلا بني عدي فلم يشهدها منهم أحد وخرجوا من ديارهم كما قال تعالى {بطرا ورئاء الناس ويصدون عن سبيل الله} [الأنفال: 47] (1) فجمعهم على غير ميعاد كما قال تعالى {ولو تواعدتم لاختلفتم في الميعاد} [الأنفال: 42] (2) .", 149, 217], ["استشارة الأصحاب قبل بدر", "ولما بلغ رسول الله صلى الله عليه وسلم خروج قريش استشار أصحابه. فتكلم المهاجرون فأحسنوا ثم استشارهم ثانيا. فتكلم المهاجرون. ثم ثالثا. فعلمت الأنصار أن رسول الله إنما يعنيهم، فقال سعد بن معاذ: كأنك تعرض بنا يا رسول الله، وكان إنما يعنيهم لأنهم بايعوه على أن يمنعوه في ديارهم، وكأنك تخشى أن تكون الأنصار ترى عليهم ألا ينصروك إلا في ديارهم. وإني أقول عن الأنصار وأجيب عنهم. فامض بنا حيث شئت وصل حبل من شئت واقطع حبل من شئت وخذ من أموالنا ما شئت. وأعطنا ما شئت. وما أخذت منها كان أحب إلينا مما تركت. فوالله لئن سرت بنا حتى تبلغ البرك من غمدان لنسيرن معك ووالله لئن استعرضت بنا هذا البحر لخضناه معك.", 150, 218], ["نجاة العير وإصرار أبي جهل", "وخفض أبو سفيان. فلحق بساحل البحر. وكتب إلى قريش أن ارجعوا فإنكم إنما خرجتم لتحرزوا عيركم. فأتاهم الخبر فهموا بالرجوع. فقال أبو جهل: والله لا نرجع حتى نقدم بدرا فنقيم بها نطعم من حضرنا ونسقي الخمر وتعزف علينا القيان. وتسمع بنا العرب. فلا تزال تهابنا أبدا وتخافنا.", 151, 219], ["رجوع الأخنس وبني زهرة وطالب بن أبي طالب", "فأشار الأخنس بن شريق عليهم بالرجوع فلم يفعلوا. فرجع هو وبنو زهرة. فلم يزل الأخنس في بني زهرة مطاعا بعدها.", 151, 220], ["النزول على أدنى مياه بدر ونزول المطر", "وسار رسول الله -صلى الله عليه وسلم - حتى نزل على ماء أدنى مياه بدر. فقال الحباب بن المنذر: إن رأيت أن نسير إلى قلب - قد عرفناها - كثيرة الماء عذبة فننزل عليها. ونغور ما سواها من المياه؟ وأنزل الله تلك الليلة مطرا واحدا صلب الرمل. وثبت الأقدام. وربط على قلوبهم.", 151, 221], ["إشارة النبي ﷺ إلى مصارع القوم", "ومشى رسول الله -صلى الله عليه وسلم - في موضع المعركة. وجعل يشير بيده ويقول: «هذا مصرع فلان وهذا مصرع فلان إن شاء الله.» فما تعدى أحد منهم موضع إشارته -صلى الله عليه وسلم -.", 152, 222], ["استنصار النبي ﷺ ربه وإمداد الملائكة", "فلما طلع المشركون قال رسول الله -صلى الله عليه وسلم - «اللهم هذه قريش جاءت بخيلائها وفخرها جاءت تحادك وتكذب رسولك. اللهم فنصرك الذي وعدتني. اللهم أحنهم الغداة» وقام ورفع يديه واستنصر ربه وبالغ في التضرع ورفع يديه حتى سقط رداؤه. وقال «اللهم أنجز لي ما وعدتني اللهم إني أنشدك عهدك ووعدك اللهم إن تهلك هذه العصابة لن تعبد في الأرض بعد» (1) .", 152, 223], ["نشوب الحرب يوم بدر", "وأمر أبو جهل عامر بن الحضرمي - أخا عمرو بن الحضرمي - أن يطلب دم أخيه. فصاح. وكشف عن استه يصرخ واعمراه واعمراه. فحمي القوم. ونشبت الحرب.", 153, 224], ["هزيمة المشركين يوم بدر", "ومنح الله المسلمين أكتاف المشركين. فتناولوهم قتلا وأسرا. فقتلوا سبعين وأسروا سبعين.", 153, 225], ["المبارزة يوم بدر", "وخرج عتبة وشيبة ابنا ربيعة والوليد بن عتبة: يطلبون المبارزة. فخرج إليهم ثلاثة من الأنصار فقالوا: أكفاء كرام. ما لنا بكم من حاجة. إنما نريد من بني عمنا. فبرز إليهم حمزة وعبيدة بن الحارث بن المطلب وعلي بن أبي طالب. فقتل علي قرنه الوليد. وقتل حمزة قرنه شيبة. واختلف عبيدة وعتبة ضربتين كلاهما أثبت صاحبه. فكر حمزة وعلي على قرن عبيدة فقتلاه. واحتملا عبيدة قد قطعت رجله. فقال لو كان أبو طالب حيا لعلم أنا أولى منه بقوله:", 153, 226], ["وفاة عبيدة بن الحارث بالصفراء", "ومات بالصفراء وفيهم نزلت {هذان خصمان اختصموا في ربهم} [الحج: 19]- الآية (1) فكان علي -رضي الله عنه- يقول «أنا أول من يجثو للخصومة بين يدي الله عز وجل يوم القيامة» .", 154, 227], ["تبدي إبليس لقريش في صورة سراقة", "ولما عزمت قريش على الخروج وذكروا ما بينهم وبين بني كنانة من الحرب. فتبدى لهم إبليس في صورة سراقة بن مالك. فقال {لا غالب لكم اليوم من الناس وإني جار لكم} [الأنفال: 48] فلما تعبئوا للقتال ورأى الملائكة فر ونكص على عقبيه فقالوا: إلى أين يا سراقة؟ فقال {إني أرى ما لا ترون إني أخاف الله والله شديد العقاب} [الأنفال: 48]", 154, 228], ["استشهاد عمير بن الحمام أول قتيل", "فأخرج عمير بن الحمام بن الجموح تمرات من قرنه يأكلهن. ثم قال لئن حييت حتى آكل تمراتي هذه إنها لحياة طويلة \" فرمى بهن وقاتل حتى قتل فكان أول قتيل.", 155, 229], ["رمي النبي ﷺ التراب في وجوه القوم", "وأخذ رسول الله -صلى الله عليه وسلم - ملء كفه ترابا فرمى به في وجوه القوم. فلم تترك رجلا منهم إلا ملأت عينيه. فهو قوله تعالى {وما رميت إذ رميت ولكن الله رمى} [الأنفال: 17] (2) .", 155, 230], ["مقتل أبي جهل", "ولما بردت الحرب وانهزم العدو قال رسول الله -صلى الله عليه وسلم - «من ينظر لنا ما صنع أبو جهل؟» (1) فانطلق ابن مسعود فوجده قد ضربه معوذ وعوف - ابنا عفراء - حتى برد. فأخذ بلحيته فقال أنت أبو جهل؟ فقال لمن الدائرة اليوم؟ قال لله ورسوله. ثم قال له هل أخزاك الله يا عدو الله؟ قال وهل فوق رجل قتله قومه؟ فاحتز رأسه عبد الله بن مسعود. ثم أتى النبي -صلى الله عليه وسلم -. فقال قتلته فقال \" آلله الذي لا إله إلا هو؟ - ثلاثا - ثم قال: «الحمد لله الذي صدق وعده ونصر عبده. وهزم الأحزاب وحده» . انطلق فأرنيه. فانطلقنا فأريته إياه. فلما وقف عليه قال: «هذا فرعون هذه الأمة» .", 155, 231], ["مقتل أبي جهل", "ولما بردت الحرب وانهزم العدو قال رسول الله -صلى الله عليه وسلم - «من ينظر لنا ما صنع أبو جهل؟» (1) فانطلق ابن مسعود فوجده قد ضربه معوذ وعوف - ابنا عفراء - حتى برد. فأخذ بلحيته فقال أنت أبو جهل؟ فقال لمن الدائرة اليوم؟ قال لله ورسوله. ثم قال له هل أخزاك الله يا عدو الله؟ قال وهل فوق رجل قتله قومه؟ فاحتز رأسه عبد الله بن مسعود. ثم أتى النبي -صلى الله عليه وسلم -. فقال قتلته فقال \" آلله الذي لا إله إلا هو؟ - ثلاثا - ثم قال: «الحمد لله الذي صدق وعده ونصر عبده. وهزم الأحزاب وحده» . انطلق فأرنيه. فانطلقنا فأريته إياه. فلما وقف عليه قال: «هذا فرعون هذه الأمة» .", 155, 232], ["مقتل أمية بن خلف", "وأسر عبد الرحمن بن عوف أمية بن خلف وابنه عليا. فأبصره بلال - وكان يعذبه بمكة - فقال رأس الكفر أمية؟ لا نجوت إن نجا. ثم استحمى جماعة من الأنصار. واشتد عبد الرحمن بهما يحجزهما منهم فأدركوهم. فشغلهم عن أمية بابنه علي ففرغوا منه ثم لحقوهما.", 156, 233], ["انقطاع سيف عكاشة بن محصن", "وانقطع يومئذ سيف عكاشة بن محصن. فأعطاه النبي -صلى الله عليه وسلم - جذلا من حطب فلما أخذه وهزه عاد في يده سيفا طويلا فلم يزل يقاتل به حتى قتل يوم الردة. ولما انقضت الحرب أقبل النبي -صلى الله عليه وسلم - حتى وقف على القتلى. فقال: «بئس عشيرة النبي كنتم كذبتموني. وصدقني الناس. وخذلتموني ونصرني الناس. وأخرجتموني. وآواني الناس» .", 156, 234], ["وقوف النبي ﷺ على قتلى بدر", "وانقطع يومئذ سيف عكاشة بن محصن. فأعطاه النبي -صلى الله عليه وسلم - جذلا من حطب فلما أخذه وهزه عاد في يده سيفا طويلا فلم يزل يقاتل به حتى قتل يوم الردة. ولما انقضت الحرب أقبل النبي -صلى الله عليه وسلم - حتى وقف على القتلى. فقال: «بئس عشيرة النبي كنتم كذبتموني. وصدقني الناس. وخذلتموني ونصرني الناس. وأخرجتموني. وآواني الناس» .", 156, 235], ["إلقاء القتلى في قليب بدر", "ثم أمر بهم فسحبوا حتى ألقوا في القليب - قليب بدر - ثم وقف عليهم فقال يا عتبة بن ربيعة ويا شيبة بن ربيعة ويا فلان ويا فلان هل وجدتم ما وعدكم ربكم حقا؟ فإني قد وجدت ما وعدني ربي حقا فقال عمر يا رسول الله ما تخاطب من أقوام قد جيفوا؟ فقال ما أنت بأسمع لما أقول منهم.", 157, 236], ["قتل النضر بن الحارث وعقبة بن أبي معيط", "فلما كان بالصفراء قسم الغنائم وضرب عنق النضر بن الحارث. ثم لما نزل بعرق الظبية ضرب عنق عقبة بن أبي معيط.", 157, 237], ["دخول المدينة بعد بدر وإسلام كثير من أهلها", "فأسلم بشر كثير من أهل المدينة ودخل عبد الله بن أبي رأس المنافقين وأصحابه في الإسلام.", 157, 238], ["عدد من حضر بدرا ومن استشهد", "وجملة من حضر بدرا: ثلاثمائة وبضعة عشر رجلا. واستشهد منهم أربعة عشر رجلا.", 157, 239], ["نزول آية في المفتونين الذين خرجوا إلى بدر", "قال ابن إسحاق: كان أناس قد أسلموا. فلما هاجر رسول الله -صلى الله عليه وسلم - حبسهم أهلهم بمكة. وفتنوهم فافتتنوا. ثم ساروا مع قومهم إلى بدر. فأصيبوا فأنزل الله فيهم {إن الذين توفاهم الملائكة ظالمي أنفسهم} [النساء: 97]- الآية (1) .", 157, 240], ["قسم غنائم بدر", "ثم إن رسول الله -صلى الله عليه وسلم - أمر بالغنائم فجمعت فاختلفوا. فقال من جمعها: هي لنا. وقال من هزم العدو لولانا ما أصبتموها، وقال الذين يحرسون رسول الله -صلى الله عليه وسلم - ما أنتم بأحق بها منا. قال عبادة بن الصامت: فنزعها الله من أيدينا. فجعلها إلى رسول الله -صلى الله عليه وسلم - فقسمه بين المسلمين وأنزل الله تعالى {يسألونك عن الأنفال قل الأنفال لله والرسول} [الأنفال: 1]- الآيات (2) .", 157, 241], ["تفريق أسرى بدر والوصية بهم", "وذكر ابن إسحاق عن نبيه بن وهب. قال \" فرق رسول الله -صلى الله عليه وسلم - الأسرى على أصحابه. وقال استوصوا بالأسرى خيرا فكان أبو عزيز بن عمير عند رجل من الأنصار، فقال له أخوه مصعب شد يدك به. فإن أخته ذات متاع. فقال أبو عزيز يا أخي، هذه وصيتك بي؟ فقال مصعب: إنه أخي دونك. قال عزيز وكنت مع رهط من الأنصار حين قفلوا، فكانوا إذا قدموا طعاما خصوني بالخبز وأكلوا التمر. لوصية رسول الله -صلى الله عليه وسلم - إياهم بنا، ما يقع في يد رجل منهم كسرة إلا نفحني بها. قال فأستحي فأردها على أحدهما. فيردها علي ما يمسها.", 158, 242], ["أسارى بدر والاستشارة فيهم", "واستشار رسول الله -صلى الله عليه وسلم - أصحابه في الأسرى وهم سبعون. وكذلك القتلى سبعون أيضا. فأشار الصديق أن يؤخذ منهم فدية تكون لهم قوة. ويطلقهم لعل الله يهديهم للإسلام. فقال عمر لا والله ما أرى ذلك. ولكني أرى أن تمكننا، فنضرب أعناقهم. فإن هؤلاء أئمة الكفر وصناديد الشرك فهوى رسول الله -صلى الله عليه وسلم - ما قال أبو بكر. فقال: «إن الله عز وجل ليلين قلوب رجال فيه حتى تكون ألين من اللين وإن الله عز وجل ليشدد قلوب رجال فيه حتى تكون أشد من الحجارة. وإن مثلك يا أبا بكر كمثل إبراهيم إذ قال {فمن تبعني فإنه مني ومن عصاني فإنك غفور رحيم} [إبراهيم: 36] وإن مثلك يا أبا بكر كمثل عيسى، إذ قال {إن تعذبهم فإنهم عبادك وإن تغفر لهم} [المائدة: 118]- الآية وإن مثلك يا عمر كمثل موسى، قال {ربنا اطمس على أموالهم واشدد على قلوبهم} [يونس: 88]- الآية وإن مثلك يا عمر كمثل نوح قال {رب لا تذر على الأرض من الكافرين ديارا} [نوح: 26] ثم قال أنتم اليوم عالة. فلا ينفلتن منهم أحد إلا بفداء أو ضرب عنق. فأنزل الله تعالى {ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض} [الأنفال: 67]- الآيتين» (1) .", 158, 243], ["نزول آية ما كان لنبي أن يكون له أسرى", "واستشار رسول الله -صلى الله عليه وسلم - أصحابه في الأسرى وهم سبعون. وكذلك القتلى سبعون أيضا. فأشار الصديق أن يؤخذ منهم فدية تكون لهم قوة. ويطلقهم لعل الله يهديهم للإسلام. فقال عمر لا والله ما أرى ذلك. ولكني أرى أن تمكننا، فنضرب أعناقهم. فإن هؤلاء أئمة الكفر وصناديد الشرك فهوى رسول الله -صلى الله عليه وسلم - ما قال أبو بكر. فقال: «إن الله عز وجل ليلين قلوب رجال فيه حتى تكون ألين من اللين وإن الله عز وجل ليشدد قلوب رجال فيه حتى تكون أشد من الحجارة. وإن مثلك يا أبا بكر كمثل إبراهيم إذ قال {فمن تبعني فإنه مني ومن عصاني فإنك غفور رحيم} [إبراهيم: 36] وإن مثلك يا أبا بكر كمثل عيسى، إذ قال {إن تعذبهم فإنهم عبادك وإن تغفر لهم} [المائدة: 118]- الآية وإن مثلك يا عمر كمثل موسى، قال {ربنا اطمس على أموالهم واشدد على قلوبهم} [يونس: 88]- الآية وإن مثلك يا عمر كمثل نوح قال {رب لا تذر على الأرض من الكافرين ديارا} [نوح: 26] ثم قال أنتم اليوم عالة. فلا ينفلتن منهم أحد إلا بفداء أو ضرب عنق. فأنزل الله تعالى {ما كان لنبي أن يكون له أسرى حتى يثخن في الأرض} [الأنفال: 67]- الآيتين» (1) .", 158, 244], ["فداء العباس", "وقال الأنصار للنبي -صلى الله عليه وسلم - نريد أن نترك لابن أختنا العباس فداءه فقال «لا تدعوا منه درهما» ثم دخلت السنة الثالثة من الهجرة.", 159, 245], ["غزوة بني قينقاع", "فكانت فيها غزوة بني قينقاع وكانوا من يهود المدينة. فنقضوا العهد. فحاصرهم رسول الله -صلى الله عليه وسلم - خمس عشرة ليلة. فنزلوا على حكمه فشفع فيهم عبد الله بن أبي ابن سلول. وألح على رسول الله -صلى الله عليه وسلم - فيهم. فأطلقهم له وكانوا سبعمائة رجل. وهم رهط عبد الله بن سلام.", 160, 247], ["غزوة أحد", "وفيها كانت وقعة أحد في شوال. وذلك: أن الله تبارك وتعالى لما أوقع بقريش يوم بدر، وترأس فيهم أبو سفيان لذهاب أكابرهم أخذ يؤلب على رسول الله -صلى الله عليه وسلم - وعلى المسلمين. ويجمع الجموع. فجمع قريبا من ثلاث آلاف من قريش، والحلفاء والأحابيش. وجاءوا بنسائهم لئلا يفروا. ثم أقبل بهم نحو المدينة. فنزل قريبا من جبل أحد.", 160, 248], ["استشارة الصحابة في الخروج إلى أحد", "فاستشار رسول الله -صلى الله عليه وسلم - أصحابه في الخروج إليهم. وكان رأيه ألا يخرجوا. فإن دخلوها قاتلهم المسلمون على أفواه السكك والنساء من فوق البيوت ووافقه عبد الله بن أبي - رأس المنافقين - على هذا الرأي. فبادر جماعة من فضلاء الصحابة - ممن فاته بدر - وأشاروا على رسول الله بالخروج. وألحوا عليه.", 160, 249], ["الخروج إلى أحد في ألف", "فخرج في ألف من أصحابه واستعمل على المدينة عبد الله بن أم مكتوم. وكان رسول الله -صلى الله عليه وسلم - رأى رؤيا: رأى أن في سيفه ثلمة وأن بقرا تذبح. وأنه يدخل يده في درع حصينة. فتأول الثلمة برجل يصاب من أهل بيته والبقر بنفر من أصحابه يقتلون والدرع بالمدينة فخرج وقال لأصحابه عليكم بتقوى الله والصبر عند البأس إذا لقيتم العدو. وانظروا ماذا أمركم الله به فافعلوا.", 161, 250], ["رؤيا النبي ﷺ قبل أحد", "فخرج في ألف من أصحابه واستعمل على المدينة عبد الله بن أم مكتوم. وكان رسول الله -صلى الله عليه وسلم - رأى رؤيا: رأى أن في سيفه ثلمة وأن بقرا تذبح. وأنه يدخل يده في درع حصينة. فتأول الثلمة برجل يصاب من أهل بيته والبقر بنفر من أصحابه يقتلون والدرع بالمدينة فخرج وقال لأصحابه عليكم بتقوى الله والصبر عند البأس إذا لقيتم العدو. وانظروا ماذا أمركم الله به فافعلوا.", 161, 251], ["انخزال عبد الله بن أبي، رأس المنافقين، بنحو ثلث العسكر", "فلما كان بالشوط - بين المدينة وأحد - انخذل عبد الله بن أبي بنحو ثلث العسكر وقال عصاني. وسمع من غيري ما ندري: علام نقتل أنفسنا هاهنا أيها الناس؟", 161, 252], ["مرور الجيش بحائط مربع بن قيظي", "لو نعلم أنكم تقاتلون لم نرجع فرجع عنهم وسبهم. وسأل نفر من الأنصار رسول الله -صلى الله عليه وسلم - أن يستعينوا بحلفائهم من يهود. فأبى، وقال من يخرج بنا على القوم من كثب؟ . فخرج به بعض الأنصار، حتى سلك في حائط لمربع بن قيظي من المنافقين - وكان أعمى - فقام يحثو التراب في وجوه المسلمين ويقول لا أحل لك أن تدخل في حائطي، إن كنت رسول الله. فابتدروه ليقتلوه. فقال رسول الله -صلى الله عليه وسلم - لا تقتلوه فهذا أعمى القلب أعمى البصر.", 161, 253], ["نزول الشعب من أحد وتعبئة المسلمين", "فلما أصبح يوم السبت تعبأ للقتال. وهو في سبعمائة منهم خمسين فارسا. واستعمل على الرماة - وكانوا خمسين - عبد الله بن جبير. وأمرهم ألا يفارقوا مركزهم ولو رأوا الطير تختطف العسكر. وأمرهم أن ينضحوا المشركين بالنبل لئلا يأتوا المسلمين من ورائهم. وظاهر رسول الله -صلى الله عليه وسلم - بين درعين.", 162, 254], ["رد من استصغر عن القتال", "وأعطى اللواء مصعب بن عمير، وجعل على إحدى المجنبتين الزبير بن العوام وعلى الأخرى: المنذر بن عمرو. واستعرض الشباب يومئذ. فرد من استصغر عن القتال - كابن عمر وأسامة بن زيد والبراء وزيد بن أرقم وزيد بن ثابت، وعرابة الأوسي - وأجاز من رآه مطيقا.", 162, 255], ["تعبئة قريش يوم أحد", "وتعبأت قريش وهم ثلاثة آلاف وفيهم مائتا فارس فجعلوا على ميمنتهم خالد بن الوليد. وعلى الميسرة عكرمة بن أبي جهل.", 162, 256], ["قتال أبي عامر الفاسق المسلمين", "وكان أول من بدر من المشركين أبو عامر - عبد عمرو بن صيفي - الفاسق. وكان يسمى الراهب. وهو رأس الأوس في الجاهلية. فلما جاء الإسلام شرق به وجاهر بالعداوة. فذهب إلى قريش يؤلبهم على رسول الله -صلى الله عليه وسلم - ووعدهم بأن قومه إذا رأوه أطاعوه. فلما ناداهم وتعرف إليهم قالوا: لا أنعم الله بك عينا يا فاسق. فقال لقد أصاب قومي بعدي شر ثم قاتل المسلمين قتالا شديدا. ثم أرضخهم بالحجارة.", 162, 257], ["انهزام المشركين أول النهار ثم إخلاء الرماة الثغر", "وأبلى يومئذ أبو دجانة وطلحة وحمزة وعلي والنضر بن أنس وسعد بن الربيع بلاء حسنا. وكانت الدولة أول النهار للمسلمين. فانهزم أعداء الله وولوا مدبرين. حتى انتهوا إلى نسائهم. فلما رأى ذلك الرماة قالوا: الغنيمة الغنيمة. فذكرهم أميرهم عهد رسول الله -صلى الله عليه وسلم - فلم يسمعوا. فأخلوا الثغر وكر فرسان المشركين عليه فوجدوه خاليا. فجاءوا منه وأقبل آخرهم حتى أحاطوا بالمسلمين فأكرم الله من أكرم منهم بالشهادة - وهم سبعون - وولى الصحابة.", 163, 258], ["جرح النبي ﷺ وكسر رباعيته ومقتل مصعب بن عمير", "وخلص المشركون إلى رسول الله -صلى الله عليه وسلم - فجرحوه جراحات وكسروا رباعيته. وقتل مصعب بن عمير بين يديه. فدفع اللواء إلى علي بن أبي طالب. وأدركه المشركون يريدون قتله. فحال دونه نحو عشرة حتى قتلوا. ثم جلدهم طلحة بن عبيد الله حتى أجهضهم عنه. وترس أبو دجانة عليه بظهره والنبل يقع فيه وهو لا يتحرك.", 163, 259], ["رد عين قتادة بن النعمان", "وأصيبت يومئذ عين قتادة بن النعمان. فأتى بها رسول الله -صلى الله عليه وسلم - فردها بيده. فكانت أحسن عينيه.", 163, 260], ["صراخ الشيطان بقتل النبي ﷺ واستشهاد أنس بن النضر", "وصرخ الشيطان إن محمدا قد قتل فوقع ذلك في قلوب كثير من المسلمين فمر أنس بن النضر بقوم من المسلمين قد ألقوا بأيديهم فقالوا: قتل رسول الله -صلى الله عليه وسلم - فقال ما تصنعون بالحياة بعده؟ قوموا فموتوا على ما مات عليه. ثم استقبل الناس ولقي سعد بن معاذ، فقال يا سعد إني لأجد ريح الجنة من دون أحد. فقاتل حتى قتل. ووجد به سبعون جراحة.", 163, 261], ["مقتل حمزة بن عبد المطلب", "وقتل وحشي الحبشي حمزة بن عبد المطلب -رضي الله عنه-. رماه بحربة على طريقة الحبشة.", 164, 262], ["اجتماع المسلمين إلى النبي ﷺ في الشعب", "وأقبل رسول الله -صلى الله عليه وسلم - نحو المسلمين. فكان أول من عرفه تحت المغفر كعب بن مالك. فصاح بأعلى صوته يا معشر المسلمين هذا رسول الله فأشار إليه أن اسكت. فاجتمع إليه المسلمون. ونهضوا معه إلى الشعب الذي نزل فيه.", 164, 263], ["مقتل أبي بن خلف", "فلما أسندوا إلى الجبل أدركه أبي بن خلف على فرس له كان يزعم بمكة أنه يقتل عليه رسول الله -صلى الله عليه وسلم - فلما اقترب منه طعنه رسول الله -صلى الله عليه وسلم - في ترقوته فكر منهزما. فقال له المشركون ما بك من بأس. فقال والله لو كان ما بي بأهل ذي المجاز لماتوا أجمعين. فمات بسرف.", 164, 264], ["صلاة النبي ﷺ بهم جالسا يوم أحد", "وحانت الصلاة فصلى بهم رسول الله -صلى الله عليه وسلم - جالسا.", 164, 265], ["استشهاد حنظلة بن أبي عامر", "وشد حنظلة بن أبي عامر على أبي سفيان. فلما تمكن منه حمل عليه شداد بن الأسود فقتله وكان حنظلة جنبا. فإنه سمع الصيحة وهو على بطن امرأته -: قام من فوره إلى الجهاد فأخبر رسول الله -صلى الله عليه وسلم - أن الملائكة تغسله.", 164, 266], ["إسلام الأصيرم واستشهاده", "وكان الأصيرم - عمرو بن ثابت بن وقش - يأبى الإسلام. وهو من بني عبد الأشهل. فلما كان يوم أحد قذف الله الإسلام في قلبه للحسنى التي سبقت له. فأسلم وأخذ سيفه. فقاتل حتى أثبتته الجراح ولم يعلم أحد بأمره. فلما طاف بنو عبد الأشهل يلتمسون قتلاهم وجدوا الأصيرم - وبه رمق يسير - فقالوا: والله إن هذا الأصيرم. ثم سألوه ما الذي جاء بك؟ أحدب على قومك، أم رغبة في الإسلام؟ فقال بل رغبة في الإسلام آمنت بالله وبرسوله وأسلمت. ومات من وقته. فذكروه لرسول الله -صلى الله عليه وسلم - فقال «هو من أهل الجنة ولم يصل لله سجدة قط» .", 165, 267], ["نداء أبي سفيان بعد انقضاء الحرب", "ولما انقضت الحرب أشرف أبو سفيان على الجبل ونادى: أفيكم محمد؟ فلم يجيبوه. فقال أفيكم ابن أبي قحافة؟ فلم يجيبوه. فقال أفيكم عمر بن الخطاب؟ فلم يجيبوه.", 165, 268], ["قتال الملائكة يوم أحد", "وقاتلت الملائكة يوم أحد عن رسول الله -صلى الله عليه وسلم -. ففي الصحيحين عن سعد قال «رأيت رسول الله يوم أحد ومعه رجلان يقاتلان عليهما ثياب بيض. كأشد القتال وما رأيتهما قبل ولا بعد» .", 165, 269], ["نزول آية وما محمد إلا رسول", "ومر رجل من المهاجرين برجل من الأنصار - وهو يتشحط في دمه - فقال يا فلان أشعرت أن محمدا قتل؟ فقال الأنصاري إن كان قد قتل فقد بلغ فقاتلوا عن دينكم فنزل {وما محمد إلا رسول قد خلت من قبله الرسل} [آل عمران: 144]- الآية (1) .", 166, 270], ["ما نزل من القرآن في يوم أحد", "وكان يوم أحد يوم بلاء وتمحيص اختبر الله عز وجل به المؤمنين. وأظهر به المنافقين. وأكرم فيه من أراد كرامته بالشهادة. فكان مما نزل من القرآن في يوم أحد إحدى وستون آية من آل عمران أولها {وإذ غدوت من أهلك تبوئ المؤمنين مقاعد للقتال} [آل عمران: 121]- الآيات (2) .", 166, 271], ["المسير إلى حمراء الأسد", "فبلغ ذلك رسول الله -صلى الله عليه وسلم -. فنادى في الناس بالمسير إليهم وقال لا يخرج معنا إلا من شهد القتال فقال له ابن أبي: أركب معك؟ قال لا. فاستجاب له المسلمون - على ما بهم من القرح الشديد - وقالوا: سمعا وطاعة. وقال جابر يا رسول الله إني أحب ألا تشهد مشهدا إلا كنت معك. وإنما خلفني أبي على بناته فأذن لي أسر معك. فأذن له.", 166, 272], ["وقعة خبيب وأصحابه", "ثم دخلت السنة الرابعة. فكانت فيها وقعة خبيب وأصحابه في صفر.", 167, 274], ["وقعة بئر معونة", "وفي هذا الشهر بعينه من السنة المذكورة كانت وقعة أهل بئر معونة. وفي شهر ربيع الأول كانت غزوة بني النضير. ونزل فيها سورة الحشر. ثم دخلت السنة الخامسة.", 167, 275], ["غزوة بني النضير", "وفي هذا الشهر بعينه من السنة المذكورة كانت وقعة أهل بئر معونة. وفي شهر ربيع الأول كانت غزوة بني النضير. ونزل فيها سورة الحشر. ثم دخلت السنة الخامسة.", 167, 276], ["غزوة المريسيع على بني المصطلق", "غزوة المريسيع فكانت فيها غزوة المريسيع على بني المصطلق فأغار عليهم رسول الله -صلى الله عليه وسلم - وهم غارون. فسبى رسول الله -صلى الله عليه وسلم - النساء والنعم والشاء. وكان من جملة السبي جويرية بنت الحارث، سيد القوم وقعت في سهم ثابت بن قيس فكاتبها، فأدى عنها رسول الله -صلى الله عليه وسلم - وتزوجها، فأعتق المسلمون - بسبب هذا التزوج - مائة أهل بيت من بني المصطلق. وقالوا: أصهار رسول الله -صلى الله عليه وسلم -.", 167, 278], ["زواج النبي ﷺ من جويرية بنت الحارث", "غزوة المريسيع فكانت فيها غزوة المريسيع على بني المصطلق فأغار عليهم رسول الله -صلى الله عليه وسلم - وهم غارون. فسبى رسول الله -صلى الله عليه وسلم - النساء والنعم والشاء. وكان من جملة السبي جويرية بنت الحارث، سيد القوم وقعت في سهم ثابت بن قيس فكاتبها، فأدى عنها رسول الله -صلى الله عليه وسلم - وتزوجها، فأعتق المسلمون - بسبب هذا التزوج - مائة أهل بيت من بني المصطلق. وقالوا: أصهار رسول الله -صلى الله عليه وسلم -.", 167, 279], ["قصة الإفك", "وفي هذه الغزوة كانت قصة الإفك. وذلك: أن عائشة -رضي الله عنها- خرج بها رسول الله -صلى الله عليه وسلم - معه بقرعة - وتلك كانت عادته مع نسائه - فلما رجعوا: نزل في طريقهم بعض المنازل. فخرجت عائشة لحاجتها، ثم رجعت. ففقدت عقدا عليها. فرجعت تلتمسه. فجاء الذين يرحلون هودجها. فحملوه. وهم يظنونها فيه. لأنها صغيرة السن. فرجعت - وقد أصابت العقد - إلى مكانهم. فإذا ليس به داع ولا مجيب. فقعدت في المنزل وظنت أنهم يفقدونها، ويرجعون إليها. فغلبتها عيناها. فلم تستيقظ إلا بقول صفوان بن المعطل: إنا لله وإنا إليه راجعون زوجة رسول الله -صلى الله عليه وسلم -؟ وكان صفوان قد عرس في أخريات الجيش لأنه كان كثير النوم. فلما رآها عرفها - وكان يراها قبل الحجاب - فاسترجع. وأناخ راحلته فركبت وما كلمها كلمة واحدة. ولم تسمع منه إلا استرجاعه. ثم سار يقود بها، حتى قدم بها. وقد نزل الجيش في نحر الظهيرة. فلما رأى ذلك الناس تكلم كل منهم بشاكلته. ووجد رأس المنافقين عدو الله عبد الله بن أبي متنفسا. فتنفس من كرب النفاق والحسد. فجعل يستحكي الإفك ويجمعه ويفرقه.", 168, 280], ["احتباس الوحي شهرا في شأن عائشة", "واقتضى تمام الابتلاء أن حبس الله عن رسوله الوحي شهرا في شأنها، ليزداد المؤمنون إيمانا، وثباتا على العدل والصدق. ويزداد المنافقون إفكا ونفاقا ولتتم العبودية المرادة من الصديقة وأبويها، وتتم نعمة الله عليهم ولينقطع رجاؤها من المخلوق وتيأس من حصول النصر والفرج إلا من الله.", 169, 281], ["نزول براءة عائشة", "قالت فنزل الوحي على رسول الله -صلى الله عليه وسلم -. فأما أنا: فعلمت أن الله لا يقول إلا الحق. وأما أبواي فوالذي ذهب بأنفاسهما، ما أقلع عن رسول الله -صلى الله عليه وسلم - إلا خفت أن أرواحهما ستخرجان. فكان أول كلمة قالها رسول الله -صلى الله عليه وسلم - «أما الله يا عائشة فقد برأك» (1) .", 169, 282], ["اعتذار حسان إلى عائشة", "فقال أبواي قومي إلى رسول الله -صلى الله عليه وسلم -. قلت والله لا أقوم إليه ولا أحمد إلا الله \". وكان حسان -رضي الله عنه- ممن قيل عنه إنه يتكلم مع أهل الإفك فقال يعتذر إلى عائشة. ويمدحها:", 170, 283], ["نزول أول سورة النور في قصة الإفك", "فأنزل الله تعالى في هذه القصة أول سورة النور من قوله {إن الذين جاءوا بالإفك عصبة منكم} [النور: 11] (1) إلى آخر القصة.", 171, 284], ["غزوة الأحزاب (الخندق)", "وفي هذه السنة - وهي سنة خمس - كانت وقعة الخندق في شوال. وسببها: أن اليهود لما رأوا انتصار المشركين يوم أحد، خرج أشرافهم - كسلام بن أبي الحقيق - وغيره إلى قريش بمكة يحرضونهم على غزو رسول الله -صلى الله عليه وسلم - ووعدهم من أنفسهم النصر لهم. فأجابتهم قريش. ثم خرجوا إلى غطفان: فاستجابوا لهم ثم طافوا في قبائل العرب يدعونهم إلى ذلك فاستجاب لهم من استجاب.", 171, 285], ["حفر الخندق بمشورة سلمان الفارسي", "فلما سمع رسول الله -صلى الله عليه وسلم - بمسيرهم إليه استشار أصحابه. فأشار عليه سلمان الفارسي بحفر خندق يحول بين العدو وبين المدينة. فأمر رسول الله -صلى الله عليه وسلم -. فبادر إليه المسلمون. وعمل فيه بنفسه. وكان في حفره من آيات نبوته ما قد تواتر الخبر به.", 171, 286], ["خروج المسلمين في ثلاثة آلاف وتحصنهم", "وخرج رسول الله -صلى الله عليه وسلم - في ثلاثة آلاف من المسلمين. فتحصن بالجبل من خلفه - جبل سلع - وبالخندق أمامه. وأمر بالنساء والذراري فجعلوا في آطام المدينة.", 172, 287], ["نقض بني قريظة العهد", "فلم يزل حتى نقض العهد الذي بينه وبين رسول الله -صلى الله عليه وسلم - ودخل مع المشركين. وسر بذلك المشركون وشرط كعب على حيي أنهم إن لم يظفروا بمحمد أن يجيء حتى يدخل معهم في حصنهم فيصيبه ما يصيبهم فشرط ذلك ووفى له.", 172, 288], ["بعث السعدين إلى بني قريظة", "وبلغ رسول الله -صلى الله عليه وسلم - الخبر فبعث إليهم السعدين - سعد بن معاذ، وسعد بن عبادة - وخوات بن جبير. وعبد الله بن رواحة ليتعرفوا الخبر فلما دنوا معهم وجدوهم على أخبث ما يكون. وجاهروهم بالسب. ونالوا من رسول الله -صلى الله عليه وسلم -.", 172, 289], ["استئذان بعض بني حارثة في الذهاب إلى المدينة", "واشتد البلاء ونجم النفاق. واستأذن بعض بني حارثة رسول الله -صلى الله عليه وسلم - في الذهاب إلى المدينة. وقالوا {إن بيوتنا عورة وما هي بعورة إن يريدون إلا فرارا} [الأحزاب: 13] (1) .", 173, 290], ["حصار المشركين شهرا ومقتل عمرو بن عبد ود", "وأقام المشركون محاصرين رسول الله -صلى الله عليه وسلم - شهرا. ولم يكن بينهم قتال لأجل الخندق، إلا أن فوارس من قريش - منهم عمرو بن عبد ود - أقبلوا نحو الخندق. فلما وقفوا عليه قالوا: إن هذه مكيدة ما كانت العرب تعرفها. ثم تيمموا مكانا ضيقا منه وجالت بهم خيلهم في السبخة ودعوا إلى البراز. فانتدب لعمرو: علي بن أبي طالب، فبارزه. فقتله الله على يدي علي. وكان من أبطال المشركين. وانهزم أصحابه.", 173, 291], ["مفاوضة غطفان على ثلث ثمار المدينة", "ولما طالت هذه الحال على المسلمين أراد رسول الله -صلى الله عليه وسلم - أن يصالح عيينة بن حصن والحارث بن عوف - رئيسي غطفان - على ثلث ثمار المدينة وينصرفا بقومهما. وجرت المفاوضة على ذلك. واستشار رسول الله -صلى الله عليه وسلم - السعدين. فقالا: إن كان الله أمرك: فسمعا وطاعة. وإن كان شيئا تحب أن تصنعه صنعناه. وإن كان شيئا تصنعه لنا، فلا. لقد كنا نحن وهؤلاء القوم على الشرك وعبادة الأوثان وهم لا يطمعون أن يأكلوا منها ثمرة إلا قرى أو بيعا. أفحين أكرمنا الله بالإسلام وأعزنا بك، نعطيهم أموالنا؟ والله لا نعطيهم إلا السيف. فصوب رأيهما.", 173, 292], ["إسلام نعيم بن مسعود وتخذيله الأحزاب", "فمن ذلك أن رجلا من غطفان - يقال له نعيم بن مسعود - جاء إلى رسول الله -صلى الله عليه وسلم -. فقال قد أسلمت، فمرني بما شئت. فقال «إنما أنت رجل واحد. فخذل عنا ما استطعت. فإن الحرب خدعة» .", 174, 293], ["تخاذل قريش وبني قريظة", "فلما جاءهم رسلهم قالوا: قد صدقكم والله نعيم. فبعثوا إليهم إنا والله لا نبعث إليكم أحدا. فقالت قريظة قد صدقكم والله نعيم. فتخاذل الفريقان.", 174, 294], ["إرسال الريح على المشركين ورحيلهم", "وأرسل الله على المشركين جندا من الريح فجعلت تقوض خيامهم ولا تدع لهم قدرا إلا كفأتها، ولا طنبا إلا قلعته وجندا من الملائكة يزلزلون بهم ويلقون في قلوبهم الرعب كما قال الله {يا أيها الذين آمنوا اذكروا نعمة الله عليكم إذ جاءتكم جنود فأرسلنا عليهم ريحا وجنودا لم تروها} [الأحزاب: 9] (1) . وأرسل رسول الله -صلى الله عليه وسلم - حذيفة بن اليمان يأتيه بخبرهم. فوجدهم على هذه الحال وقد تهيئوا للرحيل. فرجع إليه فأخبره برحيلهم.", 175, 295], ["غزوة بني قريظة", "فلما أصبح رسول الله -صلى الله عليه وسلم - انصرف عن الخندق راجعا والمسلمون إلى المدينة. فوضعوا السلاح. فجاءه جبريل وقت الظهر فقال أقد وضعتم السلاح؟ إن الملائكة لم تضع أسلحتها، انهض إلى هؤلاء - يعني بني قريظة - فنادى رسول الله -صلى الله عليه وسلم - «من كان سامعا مطيعا فلا يصلين العصر إلا في بني قريظة» (2) .", 175, 296], ["حكم سعد بن معاذ في بني قريظة", "قال فانزلوا الليلة. فعسى أن يكون محمد وأصحابه قد أمنوكم فيها لأنها ليلة السبت - لعلنا نصيب منهم غرة. قالوا: لا نفسد سبتنا. وقد علمت ما أصاب من اعتدوا في السبت. قال ما بات رجل منكم - منذ ولدته أمه ليلة من الدهر حازما. ثم نزلوا على حكم رسول الله -صلى الله عليه وسلم -. فحكم فيهم سعد بن معاذ فحكم أن تقتل الرجال وتقسم الأموال وتسبى النساء والذراري (1) .", 176, 297], ["نزول صدر سورة الأحزاب", "وأنزل الله في غزوة الخندق صدر سورة الأحزاب وذكر قصتهم في قوله {يا أيها الذين آمنوا اذكروا نعمة الله عليكم} [الأحزاب: 9]- إلى قوله - {وأورثكم أرضهم وديارهم وأموالهم} [الأحزاب: 27] (2) . ثم دخلت السنة السادسة.", 176, 298], ["وقعة الحديبية", "وفيها كانت وقعة الحديبية. وعدة الصحابة إذ ذاك ألف وأربعمائة. وهم أهل الشجرة وأهل بيعة الرضوان خرج رسول الله -صلى الله عليه وسلم - بهم معتمرا، لا يريد قتالا. فلما كانوا بذي الحليفة قلد رسول الله -صلى الله عليه وسلم - الهدي وأشعره وأحرم بالعمرة وبعث عينا من خزاعة يخبره عن قريش. حتى إذا كان قريبا من عسفان أتاه عينه فقالا: إني تركت كعب بن لؤي وعامر بن لؤي قد جمعوا جموعا، وهم مقاتلوك، وصادوك عن البيت.", 176, 300], ["بروك القصواء ونزول أقصى الحديبية", "فما شعر بهم خالد حتى إذا هو بغبرة الجيش. فانطلق يركض نذيرا. وانطلق رسول الله -صلى الله عليه وسلم - حتى إذا كان في ثنية المرار، التي يهبط عليهم منها: بركت راحلته فقال الناس حل حل. فقالوا: خلأت القصواء فقال «ما خلأت القصواء وما ذاك لها بخلق ولكن حبسها حابس الفيل. ثم قال والذي نفس محمد بيده لا يسألوني خطة يعظمون فيها حرمات الله إلا أعطيتهم إياها»", 177, 301], ["جيشان الماء بالسهم في الحديبية", "ثم زجرها فوثبت به. فعدل حتى نزل بأقصى الحديبية، على ثمد قليل الماء. فلم يلبث الناس أن نزحوه. فشكوا إليه. فانتزع سهما من كنانته. وأمرهم أن يجعلوه فيه فوالله ما زال يجيش لهم بالري حتى صدروا عنه.", 177, 302], ["إرسال عثمان إلى قريش", "وفزعت قريش لنزوله. فأحب أن يبعث إليهم رجلا. فدعا عمر فقال يا رسول الله ليس لي بمكة أحد من بني عدي بن كعب يغضب لي إن أوذيت، فأرسل عثمان. فإن عشيرته بها، وإنه يبلغ ما أردت. فدعاه فأرسله إلى قريش، وقال أخبرهم أنا لم نأت لقتال وإنما جئنا عمارا، وادعهم إلى الإسلام وأمره أن يأتي رجالا بمكة مؤمنين ونساء مؤمنات فيبشرهم بالفتح وأن الله عز وجل مظهر دينه بمكة حتى لا يتخفى فيها الإيمان.", 177, 303], ["معركة بين المسلمين والمشركين بالنبل والحجارة", "واختلط المسلمون بالمشركين في أمر الصلح. فرمى رجل من أحد الفريقين رجلا من الفريق الآخر. فكانت معركة. وتراموا بالنبل والحجارة. وصاح الفريقان وارتهن كل منهما من فيهم.", 178, 304], ["بيعة الرضوان تحت الشجرة", "وبلغ رسول الله -صلى الله عليه وسلم - أن عثمان قد قتل. فدعا إلى البيعة. فتبادروا إليه وهو تحت الشجرة فبايعوه على ألا يفروا. فأخذ بيد نفسه وقال هذه عن عثمان.", 178, 305], ["رجوع عثمان من مكة", "ولما تمت البيعة رجع عثمان فقالوا له اشتفيت من الطواف بالبيت. فقال بئسما ظننتم بي والذي نفسي بيده لو مكثت بها سنة ورسول الله -صلى الله عليه وسلم - وسلم بالحديبية ما طفت بها حتى يطوف. ولقد دعتني قريش إلى الطواف فأبيت. فقال المسلمون رسول الله أعلم بالله وأحسننا ظنا.", 179, 306], ["مجيء بديل بن ورقاء", "فبينا هم كذلك إذ جاء بديل بن ورقاء في نفر خزاعة - وكانوا عيبة نصح لرسول الله -صلى الله عليه وسلم - من أهل تهامة - فقال إني تركت ابن لؤي وعامر بن لؤي: قد نزلوا أعداد مياه الحديبية، معهم العوذ المطافيل. وهم مقاتلوك وصادوك عن البيت. فقال إنا لم نجئ لقتال أحد وإنما جئنا معتمرين. وإن قريشا نهكتهم الحرب وأضرت بهم. فإن شاءوا ماددتهم ويخلوا بيني وبين الناس. فإن شاءوا أن يدخلوا فيما دخل فيه الناس فعلوا، وإلا فقد جموا، وإن أبوا إلا القتال فوالذي نفسي بيده لأقاتلنهم على أمري هذا حتى تنفرد سالفتي، أو لينفذن الله أمره.", 179, 307], ["مجيء عروة بن مسعود", "فقال عروة بن مسعود إن هذا قد عرض عليكم خطة رشد فاقبلوها ودعوني آته. فقالوا: ائته. فأتاه. فجعل يكلمه. فقال له نحوا من قوله لبديل.", 180, 308], ["مجيء رجل من بني كنانة", "قال رجل من بني كنانة دعوني آته فقالوا: ائته. فلما أشرف على النبي -صلى الله عليه وسلم - قال هذا فلان وهو من قوم يعظمون البدن. فابعثوها له ففعلوا واستقبله القوم يلبون فلما رأى ذلك. قال سبحان الله! ما ينبغي لهؤلاء أن يصدوا عن البيت. فرجع إلى أصحابه فأخبرهم.", 181, 309], ["كتابة صلح الحديبية مع سهيل بن عمرو", "فبينا هم كذلك إذ جاء سهيل بن عمرو. فقال النبي -صلى الله عليه وسلم - «قد سهل لكم من أمركم» .", 181, 310], ["مجيء أبي جندل يرسف في قيوده وطلب سهيل رده", "فبينا هم كذلك إذ جاء أبو جندل بن سهيل وقد خرج من أسفل مكة يرسف في قيوده حتى رمى بنفسه بين أظهر المسلمين. فقال سهيل هذا أول ما أقاضيك عليه أن ترده إلي فقال النبي -صلى الله عليه وسلم - «إنا لم نقض الكتاب بعد» فقال إذا والله لا أصالحك على شيء أبدا. فقال النبي -صلى الله عليه وسلم - «فأجزه لي» قال ما أنا بمجيزه لك. قال بلى «فافعل قال ما أنا بفاعل» . قال أبو جندل يا معشر المسلمين كيف أرد إلى المشركين وقد جئت مسلما؟ ألا ترون ما لقيت؟ وكان قد عذب في الله عذابا شديدا - قال عمر بن الخطاب: والله ما شككت منذ أسلمت إلا يومئذ. فأتيت النبي -صلى الله عليه وسلم - فقلت: يا رسول الله ألست نبي الله؟ قال. بلى. قلت: ألسنا على حق وعدونا على الباطل؟ قال بلى. قلت علام نعطي الدنية في ديننا؟ ونرجع ولما يحكم الله بيننا وبين أعدائنا؟ فقال «إني رسول الله وهو ناصري» . ولست أعصيه. قلت. أو لست تحدثنا: أنا نأتي البيت ونطوف به؟ قال بلى، أفأخبرتك أنك تأتيه العام؟ قلت: لا. قال فإنك آتيه ومطوف به. قال فأتيت أبا بكر. فقلت له مثلما قلت لرسول الله -صلى الله عليه وسلم -. ورد علي كما رد علي رسول الله -صلى الله عليه وسلم - سواء وزاد فاستمسك بغرزه حتى تموت.", 182, 311], ["مراجعة عمر النبي ﷺ في الصلح", "فبينا هم كذلك إذ جاء أبو جندل بن سهيل وقد خرج من أسفل مكة يرسف في قيوده حتى رمى بنفسه بين أظهر المسلمين. فقال سهيل هذا أول ما أقاضيك عليه أن ترده إلي فقال النبي -صلى الله عليه وسلم - «إنا لم نقض الكتاب بعد» فقال إذا والله لا أصالحك على شيء أبدا. فقال النبي -صلى الله عليه وسلم - «فأجزه لي» قال ما أنا بمجيزه لك. قال بلى «فافعل قال ما أنا بفاعل» . قال أبو جندل يا معشر المسلمين كيف أرد إلى المشركين وقد جئت مسلما؟ ألا ترون ما لقيت؟ وكان قد عذب في الله عذابا شديدا - قال عمر بن الخطاب: والله ما شككت منذ أسلمت إلا يومئذ. فأتيت النبي -صلى الله عليه وسلم - فقلت: يا رسول الله ألست نبي الله؟ قال. بلى. قلت: ألسنا على حق وعدونا على الباطل؟ قال بلى. قلت علام نعطي الدنية في ديننا؟ ونرجع ولما يحكم الله بيننا وبين أعدائنا؟ فقال «إني رسول الله وهو ناصري» . ولست أعصيه. قلت. أو لست تحدثنا: أنا نأتي البيت ونطوف به؟ قال بلى، أفأخبرتك أنك تأتيه العام؟ قلت: لا. قال فإنك آتيه ومطوف به. قال فأتيت أبا بكر. فقلت له مثلما قلت لرسول الله -صلى الله عليه وسلم -. ورد علي كما رد علي رسول الله -صلى الله عليه وسلم - سواء وزاد فاستمسك بغرزه حتى تموت.", 182, 312], ["النحر والحلق بالحديبية", "فوالله إنه لعلى الحق. فعملت لذلك أعمالا. فلما فرغ من قضية الكتاب قال رسول الله -صلى الله عليه وسلم - لأصحابه قوموا فانحروا. «ثم احلقوا قال فوالله ما قام منهم رجل حتى قالها ثلاث مرات» . فلما لم يقم منهم أحد قام ولم يكلم أحدا منهم حتى نحر بدنه ودعا حالقه.", 182, 313], ["مجيء نسوة مؤمنات ونزول آية الامتحان", "فلما رأوا ذلك قاموا فنحروا. وجعل بعضهم يحلق بعضا، حتى كاد بعضهم يقتل بعضا غما. ثم جاء نسوة مؤمنات فأنزل الله {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن} [الممتحنة: 10]- حتى بلغ - {بعصم الكوافر} [الممتحنة: 10] (1) فطلق عمر يومئذ امرأتين كانتا له في الشرك.", 183, 314], ["طلاق عمر امرأتين كانتا له في الشرك", "فلما رأوا ذلك قاموا فنحروا. وجعل بعضهم يحلق بعضا، حتى كاد بعضهم يقتل بعضا غما. ثم جاء نسوة مؤمنات فأنزل الله {يا أيها الذين آمنوا إذا جاءكم المؤمنات مهاجرات فامتحنوهن} [الممتحنة: 10]- حتى بلغ - {بعصم الكوافر} [الممتحنة: 10] (1) فطلق عمر يومئذ امرأتين كانتا له في الشرك.", 183, 315], ["نزول سورة الفتح", "وفي مرجعه -صلى الله عليه وسلم - أنزل الله سورة الفتح {إنا فتحنا لك فتحا مبينا - ليغفر لك الله ما تقدم من ذنبك وما تأخر} [الفتح: 1 - 2]- الآية فقال عمر أو فتح هو يا رسول الله؟ قال نعم. قال الصحابة هذا لك يا رسول الله فما لنا؟ فأنزل الله {هو الذي أنزل السكينة في قلوب المؤمنين ليزدادوا إيمانا مع إيمانهم} [الفتح: 4]- الآيتين إلى قوله - {فوزا عظيما} [الفتح: 5] (1) .", 183, 316], ["قصة أبي بصير", "ولما رجع إلى المدينة جاءه أبو بصير - رجل من قريش - مسلما، فأرسلوا في طلبه رجلين وقالوا: العهد الذي بيننا وبينك. فدفعه إلى الرجلين. فخرجا به حتى بلغا ذا الحليفة. فنزلوا يأكلون من تمر لهم.", 183, 317], ["لحاق أبي جندل بأبي بصير بسيف البحر", "فلما سمع ذلك عرف أنه سيرده إليهم. فخرج حتى أتى سيف البحر. وتفلت منهم أبو جندل. فلحق بأبي بصير. فلا يخرج من قريش رجل - قد أسلم - إلا لحق به.", 184, 318], ["مناشدة قريش النبي ﷺ أن يرسل إليهم", "حتى اجتمعت منهم عصابة. فوالله ما يسمعون بعير لقريش خرجت إلى الشام إلا اعترضوا لها، فقاتلوهم وأخذوا أموالهم. فأرسلت قريش إلى النبي -صلى الله عليه وسلم - تناشده الله والرحم لما أرسل إليهم فمن أتاه منهم فهو آمن.", 184, 319], ["غزوة خيبر", "ولما قدم رسول الله -صلى الله عليه وسلم - من الحديبية، مكث بالمدينة عشرين يوما، أو قريبا منها. ثم خرج إلى خيبر واستخلف على المدينة سباع بن عرفطة وقدم أبو هريرة حينئذ المدينة مسلما. فوافى سباعا في صلاة الصبح. فسمعه يقرأ {ويل للمطففين} [المطففين: 1] فقال - وهو في الصلاة -: ويل أبي فلان له مكيالان إذا اكتال اكتال بالوافي، وإذا كال كال بالناقص.", 184, 320], ["قدوم أبي هريرة المدينة مسلما", "ولما قدم رسول الله -صلى الله عليه وسلم - من الحديبية، مكث بالمدينة عشرين يوما، أو قريبا منها. ثم خرج إلى خيبر واستخلف على المدينة سباع بن عرفطة وقدم أبو هريرة حينئذ المدينة مسلما. فوافى سباعا في صلاة الصبح. فسمعه يقرأ {ويل للمطففين} [المطففين: 1] فقال - وهو في الصلاة -: ويل أبي فلان له مكيالان إذا اكتال اكتال بالوافي، وإذا كال كال بالناقص.", 184, 321], ["مبارزة مرحب ومقتل عامر بن الأكوع", "فاختلفا ضربتين. فوقع سيف مرحب في ترس عامر فعضه. فذهب عامر يسفل له - وكان سيفه قصيرا - فرجع إليه سيف فأصاب ركبته فمات.", 185, 322], ["حصار خيبر قريبا من عشرين ليلة", "فحاصرهم رسول الله -صلى الله عليه وسلم - قريبا من عشرين ليلة. وكانت أرضا وخمة شديدة الحر. فجهد المسلمون جهدا شديدا. فقام النبي -صلى الله عليه وسلم - فيهم. فوعظهم وحضهم على الجهاد.", 186, 323], ["استشهاد العبد الأسود", "وكان فيهم عبد أسود فقال يا رسول الله إني رجل أسود اللون قبيح الوجه منتن الريح لا مال لي. فإن قاتلت هؤلاء حتى أقتل أدخل الجنة؟ قال نعم فتقدم. فقاتل حتى قتل فقال النبي -صلى الله عليه وسلم - لما رآه «لقد حسن الله وجهك، وطيب ريحك. وكثر مالك وقال لقد رأيت زوجتيه من الحور العين تتنازعان جبة عليه. وتدخلان فيما بين جلده وجبته» .", 186, 324], ["افتتاح خيبر وصلح أهلها", "فحاصرهم حتى إذا أيقنوا بالهلكة سألوه الصلح. ونزل إليه سلام بن أبي الحقيق فصالحهم على حقن الدماء وعلى الذرية ويخرجون من خيبر، ويخلون ما كان لهم من مال وأرض. وعلى الصفراء والبيضاء والحلقة إلا ثوبا على ظهر إنسان.", 186, 325], ["معاملة أهل خيبر على شطر الثمر وقسمها", "فلما أراد أن يجليهم قالوا: نحن أعلم بهذه الأرض منكم. فدعنا نكون فيها. فأعطاهم إياها، على شطر ما يخرج من ثمرها وزرعها.", 187, 326], ["قدوم جعفر بن أبي طالب وصحبه من الحبشة", "وفي هذه الغزوة قدم عليه ابن عمه جعفر بن أبي طالب وأصحابه. ومعهم الأشعريون: أبو موسى، وأصحابه.", 187, 327], ["محاصرة يهود وادي القرى", "ثم انصرف رسول الله -صلى الله عليه وسلم - من خيبر إلى وادي القرى وكان به جماعة من اليهود، وانضاف إليهم جماعة من العرب.", 188, 328], ["مقتل مدعم عبد رسول الله ﷺ", "فلما نزلوا استقبلتهم يهود بالرمي وهم على غير تعبئة. فقتل مدعم - عبد لرسول الله -صلى الله عليه وسلم -. كان رفاعة بن زيد الجذامي وهبه لرسول الله -صلى الله عليه وسلم - فقال الناس هنيئا له الجنة. فقال رسول الله -صلى الله عليه وسلم - كلا، والذي نفسي بيده. إن الشملة التي أخذها يوم خيبر من المغانم لم تصبها القسمة لتشتعل عليه نارا فلما سمع ذلك الناس جاء رجل بشراك أو شراكين. فقال رسول الله -صلى الله عليه وسلم - «شراك من نار أو شراكان من نار» .", 188, 329], ["افتتاح وادي القرى عنوة", "فعبأ رسول الله -صلى الله عليه وسلم - أصحابه للقتال وصفهم ثم دعاهم إلى الإسلام فأبوا. وبرز رجل منهم. فبرز إليه الزبير بن العوام فقتله. ثم برز آخر فبرز إليه علي فقتله. حتى قتل منهم أحد عشر رجلا. فقاتلهم حتى أمسوا. ثم غدا عليهم. فلم ترتفع الشمس قدر رمح حتى افتتحها عنوة. وأصابوا أثاثا ومتاعا كثيرا. فقسمه في أصحابه.", 188, 330], ["رد المهاجرين منائح الأنصار", "ولما رجع إلى المدينة رد المهاجرون إلى الأنصار منائحهم من النخيل.", 189, 331], ["بعث سرية إلى الحرقات", "ثم بعث رسول الله -صلى الله عليه وسلم - سرية إلى الحرقات من جهينة. فلما دنوا منهم بعث الأمير الطلائع. فلما رجعوا بخبرهم أقبل حتى دنا منهم ليلا، وقد هدءوا، ثم قام فحمد الله وأثنى عليه بما هو أهله. ثم قال أوصيكم بتقوى الله وحده لا شريك له وأن تطيعوني ولا تعصوني، ولا تخالفوا أمري. فإنه لا رأي لمن لا يطاع. ثم رتبهم. فقال يا فلان أنت وفلان ويا فلان أنت وفلان لا يفارق كل منكم صاحبه وزميله وإياكم أن يرجع أحد منكم فأقول. أين صاحبك؟ فيقول لا أدري. فإذا كبرت فكبروا. وجردوا السيوف. ثم كبروا وحملوا حملة واحدة. وأحاطوا بالقوم وأخذتهم سيوف الله.", 189, 332], ["عمرة القضية", "فلما كان في ذي القعدة من السنة السابعة خرج رسول الله -صلى الله عليه وسلم - معتمرا عمرة القضية. حتى إذا بلغ يأجج (1) وضع الأداة كلها، إلا الجحف والمجان والنبل والرماح. ودخلوا بسلاح الراكب - السيوف - وبعث جعفر بن أبي طالب بين يديه إلى ميمونة بنت الحارث يخطبها. فجعلت أمرها إلى العباس. فزوجه إياها.", 189, 333], ["زواج النبي ﷺ من ميمونة بنت الحارث", "فلما كان في ذي القعدة من السنة السابعة خرج رسول الله -صلى الله عليه وسلم - معتمرا عمرة القضية. حتى إذا بلغ يأجج (1) وضع الأداة كلها، إلا الجحف والمجان والنبل والرماح. ودخلوا بسلاح الراكب - السيوف - وبعث جعفر بن أبي طالب بين يديه إلى ميمونة بنت الحارث يخطبها. فجعلت أمرها إلى العباس. فزوجه إياها.", 189, 334], ["طواف المسلمين ورملهم في عمرة القضية", "فلما قدم رسول الله -صلى الله عليه وسلم - أمر أصحابه أن يكشفوا عن المناكب ويسعوا في الطواف ليرى المشركون قوتهم - وكان يكايدهم بكل ما استطاع - فوقف أهل مكة - الرجال والنساء والصبيان - ينظرون إليه وإلى أصحابه وهم يطوفون بالبيت. وعبد الله بن رواحة آخذ بخطام ناقة رسول الله -صلى الله عليه وسلم - يرتجز يقول:", 190, 335], ["الإقامة بمكة ثلاثا والخروج منها", "فأقام بمكة ثلاثا. ثم أتاه سهيل بن عمرو، وحويطب بن عبد العزى. فصاح حويطب نناشدك الله والعقد لما خرجت من أرضنا. فقد مضت الثلاث فأمر رسول الله -صلى الله عليه وسلم - أبا رافع فأذن بالرحيل.", 190, 336], ["غزوة مؤتة", "ثم دخلت السنة الثامنة\nفكانت فيها غزوة مؤتة", 190, 338], ["مقتل الحارث بن عمير رسول النبي ﷺ", "وسببها: أن رسول الله -صلى الله عليه وسلم - بعث الحارث بن عمير بكتاب إلى ملك الروم - أو بصرى - فعرض له شرحبيل بن عمرو الغساني. فقتله - ولم يقتل لرسول الله -صلى الله عليه وسلم - رسول غيره - فاشتد ذلك عليه فبعث البعوث. واستعمل عليهم زيد بن حارثة، وقال إن أصيب زيد فجعفر بن أبي طالب على الناس وإن أصيب جعفر فعبد الله بن رواحة فتجهزوا. وهم ثلاثة آلاف.", 190, 339], ["بعث البعوث إلى مؤتة وتأمير زيد ثم جعفر ثم ابن رواحة", "وسببها: أن رسول الله -صلى الله عليه وسلم - بعث الحارث بن عمير بكتاب إلى ملك الروم - أو بصرى - فعرض له شرحبيل بن عمرو الغساني. فقتله - ولم يقتل لرسول الله -صلى الله عليه وسلم - رسول غيره - فاشتد ذلك عليه فبعث البعوث. واستعمل عليهم زيد بن حارثة، وقال إن أصيب زيد فجعفر بن أبي طالب على الناس وإن أصيب جعفر فعبد الله بن رواحة فتجهزوا. وهم ثلاثة آلاف.", 190, 340], ["نزولهم معان وبلوغهم خبر هرقل", "ثم مضوا حتى نزلوا معان. فبلغهم أن هرقل بالبلقاء في مائة ألف من الروم وانضم إليه من لخم وجذام وبلي وغيرهم مائة ألف. فأقاموا ليلتين ينظرون في أمرهم.", 191, 341], ["القتال عند مؤتة ومقتل زيد وجعفر", "فمضى الناس حتى إذا كانوا بتخوم البلقاء لقيتهم الجموع. فانحاز المسلمون إلى مؤتة. ثم اقتتلوا عندها والراية في يد زيد. فلم يزل يقاتل بها حتى شاط في رماح القوم. فأخذها جعفر فقاتل بها. حتى إذا أرهقه القتال اقتحم عن فرسه فعقرها. ثم قاتل حتى قطعت يمينه. فأخذ الراية بيساره فقطعت يساره. فاحتضن الراية حتى قتل. وله ثلاث وثلاثون سنة. -رضي الله عنهم-.", 192, 342], ["مقتل عبد الله بن رواحة", "ثم أخذها عبد الله بن رواحة. فتقدم بها، وهو على فرسه فجعل يستنزل نفسه ويقول:", 192, 343], ["أخذ خالد بن الوليد الراية وانصراف الناس", "ثم أخذ الراية خالد بن الوليد. فدافع القوم وخاشى بهم (1) ثم انحازوا، وانصرف الناس.", 193, 344], ["غزوة الفتح الأعظم", "وكانت سنة ثمان في رمضان.", 194, 345], ["عدوان بني بكر على خزاعة بالوتير", "وسببها: أن بكرا عدت على خزاعة في مائهم \" الوتير \" فبيتوهم، وقتلوا منهم. وكان في صلح الحديبية: \" أن من أحب أن يدخل في عقد رسول الله صلى الله عليه وسلم فعل، ومن أحب أن يدخل في عقد قريش فعل \" فدخلت بنو بكر في عقد قريش، ودخلت خزاعة في عقد رسول الله صلى الله عليه وسلم. ثم إن بني بكر وثبوا على خزاعة ليلا بماء، يقال له: الوتير، قريبا من مكة. وأعانت قريش بني بكر بالسلاح. وقاتل معهم بعضهم مستخفيا ليلا، حتى لجأت خزاعة إلى الحرم.", 194, 346], ["قدوم عمرو بن سالم الخزاعي المدينة مستنصرا", "فخرج عمرو بن سالم الخزاعي، حتى قدم على رسول الله صلى الله عليه وسلم المدينة. فوقف عليه وهو جالس في المسجد بين ظهراني أصحابه، فقال:", 194, 347], ["قدوم بديل بن ورقاء في نفر من خزاعة", "فقال رسول الله صلى الله عليه وسلم: «نصرت يا عمرو بن سالم» . ثم خرج بديل بن ورقاء في نفر من خزاعة، حتى قدموا على رسول الله صلى الله عليه وسلم المدينة، فأخبروه بما أصيب منهم، وبمظاهرة قريش بني بكر عليهم. فقال رسول الله صلى الله عليه وسلم للناس: «كأنكم بأبي سفيان قد جاءكم ليشد العقد، ويزيد في المدة. بعثته قريش. وقد رهبوا للذي صنعوا» .", 195, 348], ["قدوم أبي سفيان المدينة", "ثم قدم أبو سفيان. فدخل على ابنته أم حبيبة. فلما ذهب ليجلس على فراش رسول الله صلى الله عليه وسلم طوته عنه. فقال: يا بنية، ما أدري: أرغبت بي عن هذا الفراش، أم رغبت به عني؟ قالت: بل هو فراش رسول الله صلى الله عليه وسلم، وأنت مشرك نجس. فقال: والله لقد أصابك بعدي شر. ثم خرج حتى أتى رسول الله صلى الله عليه وسلم. فكلمه فلم يرد عليه شيئا ثم ذهب إلى أبي بكر فكلمه في أن يكلم النبي صلى الله عليه وسلم فقال: ما أنا بفاعل. ثم أتى عمر فقال: أنا أشفع لكم؟ والله لو لم أجد إلا الذر، لجاهدتكم به. ثم دخل على علي، وعنده فاطمة - والحسن غلام يدب بين يديها - فقال: يا علي، إنك أمس القوم بي رحما، وإني جئت في حاجة، فلا أرجعن خائبا. اشفع لي إلى محمد. فقال: قد عزم رسول الله صلى الله عليه وسلم على أمر، ما نستطيع أن نكلمه فيه. فقال لفاطمة: هل لك أن تأمري ابنك هذا، فيجير بين الناس. فيكون سيد العرب إلى آخر الدهر؟ فقالت: ما يبلغ ابني ذلك. وما يجير أحد على رسول الله صلى الله عليه وسلم.", 195, 349], ["إجارة أبي سفيان بين الناس ورجوعه إلى مكة", "فقام أبو سفيان في المسجد، فقال: يا أيها الناس، إني قد أجرت بين الناس. ثم ركب بعيره، وانصرف عائدا إلى مكة.", 196, 350], ["أمر النبي ﷺ الناس بالجهاز", "وأمر رسول الله صلى الله عليه وسلم الناس بالجهاز، وقال: «اللهم خذ العيون والأخبار عن قريش، حتى نبغتها في بلادها» .", 196, 351], ["كتاب حاطب بن أبي بلتعة إلى قريش", "فكتب حاطب بن أبي بلتعة إلى قريش كتابا، يخبرهم فيه بمسير رسول الله صلى الله عليه وسلم. ودفعه إلى سارة - مولاة لبني عبد المطلب - فجعلته في رأسها. ثم فتلت عليه قرونها. وأتى الخبر رسول الله صلى الله عليه وسلم من السماء. فأرسل رسول الله صلى الله عليه وسلم عليا والزبير إلى المرأة، فأدركاها بروضة خاخ. فأنكرت. ففتشا رحلها، فلم يجدا فيه شيئا. فهدداها. فأخرجته من قرون رأسها. فأتيا به رسول الله صلى الله عليه وسلم. فدعا حاطبا. فقال: «ما هذا يا حاطب» ؟ \" فقال: لا تعجل علي يا رسول الله. والله إني لمؤمن بالله ورسوله. وما ارتددت ولا بدلت، ولكني كنت امرءا ملصقا في قريش، لست من أنفسهم. ولي فيهم أهل وعشيرة وولد. وليس لي فيهم قرابة يحمونهم. وكان من معك لهم قرابات يحمونهم. فأحببت أن أتخذ عندهم يدا. قد علمت أن الله مظهر رسوله، ومتم له أمره.", 197, 352], ["مسير رسول الله ﷺ إلى مكة", "ثم مضى رسول الله صلى الله عليه وسلم، وعمى الله الأخبار عن قريش، لكنهم على وجل. فكان أبو سفيان يتجسس، هو وحكيم بن حزام، وبديل بن ورقاء.", 197, 353], ["هجرة العباس ولقاؤه النبي ﷺ بالجحفة", "وكان العباس قد خرج قبل ذلك بأهله وعياله مسلما مهاجرا. فلقي رسول الله صلى الله عليه وسلم بالجحفة. فلما نزل رسول الله صلى الله عليه وسلم مر الظهران نزل العشاء، فأمر الجيش فأوقدوا النيران. فأوقد أكثر من عشرة آلاف نارا. فركب العباس بغلة رسول الله صلى الله عليه وسلم. وخرج يلتمس، لعله يجد بعض الحطابة، أو أحدا يخبر قريشا، ليخرجوا يستأمنون رسول الله صلى الله عليه وسلم قبل أن يدخلها عنوة.", 198, 354], ["النزول بمر الظهران وإيقاد النيران", "وكان العباس قد خرج قبل ذلك بأهله وعياله مسلما مهاجرا. فلقي رسول الله صلى الله عليه وسلم بالجحفة. فلما نزل رسول الله صلى الله عليه وسلم مر الظهران نزل العشاء، فأمر الجيش فأوقدوا النيران. فأوقد أكثر من عشرة آلاف نارا. فركب العباس بغلة رسول الله صلى الله عليه وسلم. وخرج يلتمس، لعله يجد بعض الحطابة، أو أحدا يخبر قريشا، ليخرجوا يستأمنون رسول الله صلى الله عليه وسلم قبل أن يدخلها عنوة.", 198, 355], ["العباس يأتي بأبي سفيان ليستأمن له", "قلت: والله لئن ظفر بك ليضربن عنقك. فاركب في عجز هذه البغلة، حتى آتيه بك، فأستأمنه لك. فركب خلفي. ورجع صاحباه. فجئت به. فكلما مررت بنار من نيران المسلمين، قالوا: من هذا؟ فإذا رأونا قالوا: عم رسول الله صلى الله عليه وسلم على بغلته. حتى مررت بنار عمر، فقال: من هذا؟ وقام إلي. فلما رأى أبا سفيان قال: عدو الله؟ الحمد لله الذي أمكن الله منك بغير عقد ولا عهد.", 198, 356], ["إسلام أبي سفيان", "فقال له العباس: ويحك. وأسلم قبل أن يضرب عنقك. قال: فشهد شهادة الحق، فأسلم.", 199, 357], ["الأمان لمن دخل دار أبي سفيان أو أغلق بابه أو دخل المسجد", "فقال العباس: إن أبا سفيان رجل يحب الفخر، فاجعل له شيئا، قال: «نعم من دخل دار أبي سفيان فهو آمن، ومن أغلق عليه بابه فهو آمن ومن دخل المسجد فهو آمن» .", 199, 358], ["مرور الكتائب بأبي سفيان ونزع اللواء من سعد بن عبادة", "وكانت راية الأنصار مع سعد بن عبادة، فلما مر بأبي سفيان، قال: اليوم يوم الملحمة. اليوم تستحل الحرمة. اليوم أذل الله قريشا. فذكره أبو سفيان لرسول الله صلى الله عليه وسلم. فقال «كذب سعد. ولكن هذا اليوم يوم تعظم فيه الكعبة، اليوم أعز الله قريشا» ثم نزع اللواء من سعد. ودفعه إلى قيس ابنه.", 200, 359], ["أبو سفيان ينذر قريشا", "ومضى أبو سفيان. فلما جاء قريشا صرخ بأعلى صوته. هذا محمد قد جاءكم بما لا قبل لكم به، فمن دخل دار أبي سفيان فهو آمن. قالوا: قاتلك الله، وما تغني عنا دارك؟ قال: ومن أغلق عليه بابه فهو آمن. ومن دخل المسجد فهو آمن.", 200, 360], ["دخول رسول الله ﷺ مكة من أعلاها", "وسار رسول الله صلى الله عليه وسلم حتى دخل مكة من أعلاها، وأمر خالد بن الوليد فدخلها من أسفلها، وقال: «إن عرض لكم أحد من قريش فاحصدوهم حصدا، حتى توافوني على الصفا» . فما عرض لهم أحد إلا أناموه.", 200, 361], ["قتال الخندمة", "وتجمع سفهاء قريش عكرمة بن أبي جهل، وصفوان بن أمية، وسهيل بن عمرو، بالخندمة ليقاتلوا. وكان حماس بن قيس يعد سلاحا قبل مجيء رسول الله صلى الله عليه وسلم. فقالت له امرأته: والله ما يقوم لمحمد وأصحابه شيء فقال: والله إني لأرجو أن أخدمك بعضهم، ثم قال:", 201, 362], ["الطواف بالبيت وطعن الأصنام بالقوس وتساقطها", "وقال أبو هريرة: أقبل رسول الله صلى الله عليه وسلم. فدخل مكة. فبعث الزبير على إحدى المجنبتين. وبعث خالدا على المجنبة الأخرى. وبعث أبا عبيدة بن الجراح على الحسر. فأخذوا بطن الوادي، ورسول الله صلى الله عليه وسلم في كتيبته. وقد وبشت قريش أوباشها، وقالوا: نقدم هؤلاء. فإذا كان لهم شيء كنا معهم، وإن أصيبوا أعطيناه الذي سألنا. فقال رسول الله صلى الله عليه وسلم: «يا أبا هريرة \"، فقلت: لبيك يا رسول الله. قال: \" اهتف لي بالأنصار. ولا يأتيني إلا أنصاري \" فهتفت بهم، فجاءوا. فأطافوا برسول الله صلى الله عليه وسلم. فقال: \" أترون إلى أوباش قريش وأتباعهم؟ - ثم قال بيديه إحداهما على الأخرى - احصدوهم حصدا، حتى توافوني على الصفا» قال أبو هريرة: فانطلقنا. فما يشاء أحد منا أن يقتل منهم ما شاء إلا قتل. وركزت راية رسول الله صلى الله عليه وسلم بالحجون عند مسجد الفتح. ثم نهض والمهاجرون والأنصار بين يديه وخلفه وحوله، حتى دخل المسجد. فأقبل إلى الحجر فاستلمه. ثم طاف بالبيت. وفي يده قوس، وحول البيت وعليه، ثلاثمائة وستون صنما. فجعل يطعنها بالقوس، ويقول: {جاء الحق وزهق الباطل إن الباطل كان زهوقا} [الإسراء: 81] (1) {جاء الحق وما يبدئ الباطل وما يعيد} [سبأ: 49] (1) والأصنام تتساقط على وجوهها.", 201, 363], ["دخول الكعبة ومحو الصور", "فلما أكمله دعا عثمان بن طلحة، فأخذ منه مفتاح الكعبة. فأمر بها ففتحت. فدخلها. فرأى فيها الصور، ورأى صورة إبراهيم وإسماعيل يستقسمان بالأزلام. فقال: «قاتلهم الله، والله إن استقسما بها قط» وأمر بالصور فمحيت. ثم أغلق عليه الباب، هو وأسامة وبلال. فاستقبل الجدار الذي يقابل الباب. حتى إذا كان بينه وبينه قدر ثلاثة أذرع وقف وصلى هناك. ثم دار في البيت، وكبر في نواحيه، ووحد الله. ثم فتح الباب، وقريش قد ملأت المسجد صفوفا، ينظرون ماذا يصنع بهم؟ فأخذ بعضاتي الباب وهم تحته. فقال: «لا إله إلا الله وحده لا شريك له. صدق وعده. ونصر عبده. وأعز جنده. وهزم الأحزاب وحده. ألا كل مأثرة، أو مال، أو دم، فهو تحت قدمي هاتين، إلا سدانة البيت، وسقاية الحاج. ألا وقتل الخطأ شبه العمد - السوط والعصا - ففيه الدية مغلظة، مائة من الإبل، أربعون منها في بطونها أولادها، يا معشر قريش، إن الله قد أذهب عنكم نخوة الجاهلية، وتعظمها بالآباء. الناس من آدم، وآدم من تراب \" ثم تلا هذه الآية: {يا أيها الناس إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبا وقبائل لتعارفوا إن أكرمكم عند الله أتقاكم إن الله عليم خبير} [الحجرات: 13] (2) » .", 202, 364], ["خطبته على باب الكعبة: اذهبوا فأنتم الطلقاء", "ثم قال: «يا معشر قريش، ما ترون أني فاعل بكم؟ قالوا: خيرا، أخ كريم، وابن أخ كريم. قال: فإني أقول لكم كما قال يوسف لإخوته: لا تثريب عليكم اليوم، اذهبوا فأنتم الطلقاء» .", 203, 365], ["رد مفتاح الكعبة إلى عثمان بن طلحة", "ثم جلس في المسجد، فقام إليه علي - ومفتاح الكعبة في يده - فقال: يا رسول الله، اجمع لنا الحجابة مع السقاية. صلى الله عليك. فقال صلى الله عليه وسلم: «أين عثمان بن طلحة \"؟ فدعي له، فقال: \" هاك مفتاحك يا عثمان، اليوم يوم بر ووفاء» .", 203, 366], ["أذان بلال على الكعبة", "وأمر بلالا أن يصعد على الكعبة فيؤذن - وأبو سفيان بن حرب، وعتاب بن أسيد، والحارث بن هشام، وأشراف قريش جلوس بفناء الكعبة - فقال عتاب: لقد أكرم الله أسيدا ألا يكون سمع هذا. فقال الحارث: أما والله لو أعلم أنه محق لاتبعته. فقال أبو سفيان: لا أقول شيئا، لو تكلمت لأخبرت عني هذه الحصباء. فخرج عليهم النبي صلى الله عليه وسلم. فقال: «قد علمت الذي قلتم» ثم ذكر ذلك لهم. فقال الحارث وعتاب: نشهد أنك رسول الله. والله ما اطلع على هذا أحد كان معنا. فنقول: أخبرك.", 203, 367], ["إسلام الحارث بن هشام وعتاب بن أسيد", "وأمر بلالا أن يصعد على الكعبة فيؤذن - وأبو سفيان بن حرب، وعتاب بن أسيد، والحارث بن هشام، وأشراف قريش جلوس بفناء الكعبة - فقال عتاب: لقد أكرم الله أسيدا ألا يكون سمع هذا. فقال الحارث: أما والله لو أعلم أنه محق لاتبعته. فقال أبو سفيان: لا أقول شيئا، لو تكلمت لأخبرت عني هذه الحصباء. فخرج عليهم النبي صلى الله عليه وسلم. فقال: «قد علمت الذي قلتم» ثم ذكر ذلك لهم. فقال الحارث وعتاب: نشهد أنك رسول الله. والله ما اطلع على هذا أحد كان معنا. فنقول: أخبرك.", 203, 368], ["صلاة الفتح في دار أم هانئ", "ثم دخل صلى الله عليه وسلم دار أم هانئ فاغتسل. وصلى ثمان ركعات، صلاة الفتح. وكان أمراء الإسلام إذا فتحوا بلدا صلوا هذه الصلاة.", 204, 369], ["أمان الناس إلا تسعة نفر", "ولما استقر الفتح: أمن رسول الله صلى الله عليه وسلم الناس كلهم، إلا تسعة نفر. فأنه أمر بقتلهم، وإن وجدوا تحت أستار الكعبة: عبد الله بن أبي سرح، وعكرمة بن أبي جهل، وعبد العزى بن خطل، والحارث بن نفيل، ومقيس بن صبابة، وهبار بن الأسود، وقينتان لابن خطل، وسارة مولاة لبني عبد المطلب.", 204, 370], ["خطبة الغد من يوم الفتح في حرمة مكة", "فلما كان الغد من يوم الفتح: قام رسول الله صلى الله عليه وسلم في الناس خطيبا. فحمد الله وأثنى عليه. ثم قال: «أيها الناس، إن الله حرم مكة يوم خلق السماوات والأرض. فلا يحل لامرئ يؤمن بالله واليوم الآخر: أن يسفك بها دما، أو يعضد بها شجرة، فإن أحد ترخص بقتال رسول الله صلى الله عليه وسلم فقولوا له: إن الله أذن لرسوله. ولم يأذن لك. وإنما أحلت لي ساعة من نهار» .", 205, 371], ["هم فضالة بن عمير بقتل النبي ﷺ وهو يطوف", "«وهم فضالة بن عمير بن الملوح الليثي أن يقتل رسول الله صلى الله عليه وسلم، وهو يطوف. فلما دنا منه، قال \" أفضالة؟ \" قال: نعم فضالة يا رسول الله، قال: \" ماذا تحدث به نفسك؟ \" قال: لا شيء. كنت أذكر الله، فضحك صلى الله عليه وسلم. ثم قال: \" استغفر الله \" ثم وضع يده على صدره، فسكن قلبه» . وكان فضالة يقول: والله ما رفع يده عن صدري حتى ما من خلق الله شيء أحب إلي منه، قال فضالة: فرجعت إلى أهلي. فمررت بامرأة كنت أتحدث إليها، فقالت: هلم إلى الحديث. فقال: لا. وانبعث فضالة يقول:", 205, 372], ["فرار صفوان بن أمية وعكرمة ورجوعهما", "وفر يومئذ صفوان بن أمية، وعكرمة بن أبي جهل. فاستأمن عمير بن وهب رسول الله لصفوان، فلحقه. وهو يريد أن يركب البحر فرده.", 206, 373], ["تجديد أنصاب الحرم", "ثم أمر رسول الله صلى الله عليه وسلم عتاب بن أسيد الخزاعي فجدد أنصاب الحرم.", 206, 374], ["بعث السرايا إلى الأوثان حول مكة", "وبعث صلى الله عليه وسلم سراياه إلى الأوثان التي حول مكة فكسرت كلها، منها اللات والعزى ومناة. ونادى مناديه بمكة: من كان يؤمن بالله واليوم الآخر: فلا يدع في بيته صنما إلا كسره.", 206, 375], ["هدم عمرو بن العاص صنم سواع", "وبعث عمرو بن العاص في شهر رمضان إلى سواع - وهو لهذيل - قال: فأتيته وعنده السادن، فقال: ما تريد؟ قلت: أهدمه قال: لا تقدر على ذلك، قلت: لم؟ قال: تمنع. قلت: حتى الآن أنت على الباطل؟ ويحك. وهل يسمع أو يبصر؟ فدنوت منه فكسرته. وأمرت أصحابي فهدموا بيت خزانته. فلم نجد فيه شيئا. فقلت للسادن: كيف رأيت؟ قال: أسلمت لله.", 206, 376], ["بعث سعد بن زيد لهدم مناة", "ثم بعث سعد بن زيد بن مالك بن عبد بن كعب بن عبد الأشهل، الأشهلي الأنصاري، في شهر رمضان إلى مناة. وكانت عند قديد بالمشلل، للأوس والخزرج وغسان وغيرهم.", 206, 377], ["غزوة حنين", "قال ابن إسحاق: لما سمعت هوازن بالفتح، جمعها مالك بن عوف النصري مع هوازن ثقيف كلها.", 207, 378], ["نزول هوازن بأوطاس ومشورة دريد بن الصمة", "فلما أجمع مالك السير إلى رسول الله صلى الله عليه وسلم، ساق مع الناس أموالهم ونساءهم وذراريهم. فلما نزل بأوطاس، اجتمعوا إليه. وفيهم دريد بن الصمة الجشمي، وهو شيخ كبير، ليس فيه إلا رأيه، وكان شجاعا مجربا.", 207, 379], ["بعث عبد الله بن أبي حدرد عينا إلى هوازن", "ولما سمع بهم رسول الله صلى الله عليه وسلم بعث إليهم عبد الله بن أبي حدرد الأسلمي. وأمره أن يداخلهم حتى يعلم علمهم. فانطلق. فداخلهم حتى علم ما هم عليه. فأتى رسول الله صلى الله عليه وسلم، فأخبره الخبر.", 209, 380], ["استعارة أدراع صفوان بن أمية", "فلما أراد المسير، ذكر له: أن عند صفوان بن أمية أدراعا وسلاحا - وهو يومئذ مشرك - فقال له: «يا أبا أمية، أعرنا سلاحك هذا، نلق فيه عدونا غدا» فقال: أغصبا يا محمد؟ قال: «بل عارية مضمونة، حتى نؤديها إليك» فأعطاه مائة درع بما يكفيها السلاح. فخرج صلى الله عليه وسلم. ومعه ألفان من أهل مكة، وعشرة آلاف من أصحابه الذين فتح الله بهم مكة. فكانوا اثني عشر ألفا. واستعمل عتاب بن أسيد على مكة.", 209, 381], ["خروج النبي ﷺ إلى حنين في اثني عشر ألفا", "فلما أراد المسير، ذكر له: أن عند صفوان بن أمية أدراعا وسلاحا - وهو يومئذ مشرك - فقال له: «يا أبا أمية، أعرنا سلاحك هذا، نلق فيه عدونا غدا» فقال: أغصبا يا محمد؟ قال: «بل عارية مضمونة، حتى نؤديها إليك» فأعطاه مائة درع بما يكفيها السلاح. فخرج صلى الله عليه وسلم. ومعه ألفان من أهل مكة، وعشرة آلاف من أصحابه الذين فتح الله بهم مكة. فكانوا اثني عشر ألفا. واستعمل عتاب بن أسيد على مكة.", 209, 382], ["انهزام الناس أول الأمر بوادي حنين", "فلما استقبلوا وادي حنين، انحدروا في واد من أودية تهامة أجوف في عماية الصبح. قال جابر: وكانوا قد سبقونا إليه، فكمنوا في شعابه ومضايقه. قد تهيئوا. فوالله ما راعنا إلا الكتائب، قد شدوا علينا شدة رجل واحد، فانشمر الناس راجعين لا يلوي أحد على أحد، وانحاز رسول الله صلى الله عليه وسلم ذات اليمين، ثم قال: «يا أيها الناس: هلموا إلي، أنا رسول الله، أنا محمد بن عبد الله» .", 209, 383], ["كلام جفاة أهل مكة عند الهزيمة", "قال ابن إسحاق: ولما وقعت الهزيمة: تكلم رجال من جفاة أهل مكة بما في أنفسهم من الضغن، فقال أبو سفيان، لا تنتهي هزيمتهم دون البحر، وصرخ جبلة بن الحنبل: ألا بطل السحر اليوم. فقال له أخوه صفوان بن أمية - وكان بعد مشركا - اسكت، فض الله فاك. فوالله لأن يربني رجل من قريش أحب إلي من أن يربني رجل من هوازن.", 210, 384], ["قصة شيبة بن عثمان الحجبي يوم حنين", "وذكر ابن إسحاق عن شيبة بن عثمان الحجبي. قال: لما كان يوم الفتح قلت: أسير مع قريش إلى هوازن، لعلي أصيب من محمد غرة. فأكون أنا الذي قمت بثأر قريش كلها، وأقول: لو لم يبق من العرب والعجم أحد إلا تبعه، ما اتبعته أبدا. فلما اختلط الناس، اقتحم رسول الله صلى الله عليه وسلم عن بغلته وأصلت السيف، فدنوت أريد ما أريد، ورفعت سيفي حتى كدت أسوره. فرفع لي شواظ من نار كالبرق، كاد أن يمحشني فوضعت يدي على بصري خوفا عليه. فالتفت إلي رسول الله صلى الله عليه وسلم. فناداني «يا شيب، ادن \" فدنوت، فمسح صدري. ثم قال: \" اللهم أعذه من الشيطان» فوالله لهو كان ساعتئذ أحب إلي من سمعي وبصري ونفسي. ثم قال: «ادن، فقاتل» فتقدمت أمامه أضرب بسيفي. الله يعلم أني أحب أن أقيه بنفسي. لو لقيت تلك الساعة أبي لأوقعت به السيف. فجعلت ألزمه فيمن لزمه، حتى تراجع الناس، وكروا كرة رجل واحد. وقربت بغلة رسول الله صلى الله عليه وسلم. فاستوى عليها. وخرج رسول الله صلى الله عليه وسلم في أثرهم حتى تفرقوا، في كل وجه. ورجع رسول الله صلى الله عليه وسلم إلى معسكره، فدخل خباءه. فدخلت عليه، ما دخل عليه غيري، حبا لرؤية وجهه، وسرورا به. فقال: «يا شيب، الذي أراد الله لك، خير من الذي أردت لنفسك» .", 210, 385], ["نداء العباس أصحاب السمرة ورجوع الناس", "قال العباس: إني لمع رسول الله صلى الله عليه وسلم - وكنت امرءا جسيما شديد الصوت - فقال رسول الله صلى الله عليه وسلم - حين رأى ما رأى من الناس - «إلي أيها الناس، أنا النبي لا كذب. أنا ابن عبد المطلب» فلم أر الناس يلوون على شيء. فقال: «أي عباس، اهتف بأصحاب السمرة» (1) \" فناديت: يا أصحاب السمرة، يا أصحاب سورة البقرة. فكان الرجل يريد أن يرد بعيره فلا يقدر. فيأخذ سلاحه، ويقتحم عن بعيره، ويخلي سبيله. ويؤم الصوت، فأتوا من كل ناحية: لبيك، لبيك. حتى إذا اجتمع إلى رسول الله صلى الله عليه وسلم منهم مائة استقبلوا الناس، فاقتتلوا. فكانت الدعوة أولا: \" يا للأنصار، يا للأنصار \"، ثم خلصت الدعوة: \" يا لبني الحارث بن الخزرج \"، وكانوا صبرا عند الحرب.", 211, 386], ["رمي النبي ﷺ بالحصيات وانهزام المشركين", "وفي صحيح مسلم: «ثم أخذ رسول الله صلى الله عليه وسلم حصيات. فرمى بها وجوه القوم. ثم قال: انهزموا، ورب محمد. فما هو إلا أن رماهم، فما زلت أرى حدهم كليلا، وأمرهم مدبرا» .", 211, 387], ["وقعة أوطاس ومقتل أبي عامر الأشعري", "ولما انهزم المشركون أتوا الطائف، ومعهم مالك بن عوف. وعسكر بعضهم بأوطاس. وبعث رسول الله صلى الله عليه وسلم في أثر من توجه نحو أوطاس أبا عامر الأشعري، فأدرك بعضهم فناوشوه القتال، فهزمهم الله تعالى. وقتل أبو عامر. فأخذ الراية أبو موسى الأشعري. فلما بلغ الخبر رسول الله صلى الله عليه وسلم قال: «اللهم اغفر لأبي عامر. واجعله يوم القيامة فوق كثير من خلقك» .", 212, 388], ["جمع سبي حنين وغنائمها", "وأمر رسول الله صلى الله عليه وسلم بالسبي والغنائم أن يجمع. وكان السبي ستة آلاف رأس، والإبل: أربعة وعشرين ألفا، والغنم أربعين ألف شاة، وأربعة آلاف أوقية فضة.", 212, 389], ["قسم الغنائم وإعطاء المؤلفة قلوبهم", "فاستأنى بهم رسول الله صلى الله عليه وسلم أن يقدموا موالين مسلمين، بضعة عشر ليلة. ثم بدأ بالأموال فقسمها: وأعطى المؤلفة قلوبهم أول الناس فأعطى أبا سفيان مائة من الإبل. وأربعين أوقية. وأعطى ابنه يزيد مثل ذلك. وأعطى ابنه معاوية مثل ذلك. وأعطى حكيم بن حزام مائة من الإبل. ثم سأله مائة أخرى فأعطاه.", 212, 390], ["موجدة الأنصار وخطبته ﷺ فيهم", "قال ابن إسحاق: حدثني عاصم بن عمر بن قتادة عن محمود بن لبيد عن أبي سعيد الخدري رضي الله عنه قال: «لما أعطى رسول الله صلى الله عليه وسلم من أعطى من تلك العطايا في قريش وقبائل العرب، ولم يكن في الأنصار منها شيء، وجدت الأنصار في أنفسهم. حتى كثرت منهم القالة، حتى قال قائلهم: لقي والله رسول الله قومه. فدخل عليه سعد بن عبادة، فذكر له ذلك. فقال: \" فأين أنت من ذلك يا سعد؟ \" قال: يا رسول الله، ما أنا إلا من قومي. قال: \" فاجمع لي قومك في هذه الحظيرة \" فجاء رجال من المهاجرين. فتركهم فدخلوا. وجاء آخرون فردهم فلما اجتمعوا، أتاه سعد فأخبره. فأتاهم رسول الله صلى الله عليه وسلم فحمد الله، وأثنى عليه بما هو أهله. ثم قال: \" يا معشر الأنصار، ما مقالة بلغتني عنكم؟ وجدة وجدتموها في أنفسكم؟ ألم آتكم ضلالا. فهداكم الله بي؟ وعالة فأغناكم الله بي وأعداء فألف الله بين قلوبكم بي» ؟ \".", 212, 391], ["قدوم الشيماء بنت الحارث وإسلامها", "وقدمت الشيماء بنت الحارث - أخت رسول الله صلى الله عليه وسلم من الرضاعة - فقالت: يا رسول الله، أنا أختك، فبسط لها رداءه. وأجلسها عليه. وقال: «إن أحببت فعندي مكرمة، وإن أحببت أن أمتعك وترجعي إلى قومك» فقالت: بل تمتعني، وتردني إلى قومي. ففعل وأسلمت. فأعطاها ثلاثة أعبد وجارية ونعماء وشاء.", 214, 392], ["المن على سبي هوازن", "وقدم وفد هوازن على رسول الله صلى الله عليه وسلم، وهم أربعة عشر رجلا. فسألوه:", 214, 393], ["غزوة الطائف", "غزوة الطائف ولما أراد المسير إلى الطائف - وكانت في شوال سنة ثمان - بعث الطفيل بن عمرو إلى ذي الكفين - صنم عمرو بن حممة الدوسي - يهدمه، وأمره أن يستمد قومه يوافيه بالطائف - فخرج سريعا، فهدمه وجعل يحثو النار في وجهه ويقول: - يا ذا الكفين , لست من عبادكا ... ميلادنا أكبر من ميلادكا", 216, 394], ["بعث الطفيل بن عمرو لهدم ذي الكفين", "غزوة الطائف ولما أراد المسير إلى الطائف - وكانت في شوال سنة ثمان - بعث الطفيل بن عمرو إلى ذي الكفين - صنم عمرو بن حممة الدوسي - يهدمه، وأمره أن يستمد قومه يوافيه بالطائف - فخرج سريعا، فهدمه وجعل يحثو النار في وجهه ويقول: - يا ذا الكفين , لست من عبادكا ... ميلادنا أكبر من ميلادكا", 216, 395], ["موافاة الطفيل وقومه النبي ﷺ بالطائف", "وانحدر معه من قومه أربعمائة سراعا. فوافوا النبي صلى الله عليه وسلم بالطائف - بعد مقدمه بأربعة أيام - وقدم بدبابة ومنجنيق.", 217, 396], ["حصار الطائف ونصب المنجنيق", "قال ابن سعد: لما انهزموا من أوطاس دخلوا حصنهم، وتهيئوا للقتال. وسار رسول الله صلى الله عليه وسلم. فنزل قريبا من حصن الطائف. وعسكر هناك. فرموا المسلمين بالنبل رميا شديدا، كأنه رجل جراد، حتى أصيب ناس من المسلمين بجراحة. وقتل منهم اثنا عشر رجلا. فارتفع صلى الله عليه وسلم إلى موضع مسجد الطائف اليوم. فحاصرهم ثمانية عشر يوما. ونصب عليهم المنجنيق - وهو أول من رمى به في الإسلام - وأمر بقطع أعناب ثقيف. فوقع الناس فيها يقطعون، فسألوه: أن يدعها لله وللرحم. فقال رسول الله صلى الله عليه وسلم: «فإني أدعها لله وللرحم» .", 217, 397], ["عتق من نزل من حصن الطائف من العبيد", "ونادى مناديه: \" أيما عبد نزل من الحصن، وخرج إلينا. فهو حر \" فخرج منهم بضعة عشر رجلا، فيهم أبو بكرة بن مسروج، فأعتقهم رسول الله صلى الله عليه وسلم، ودفع كل منهم إلى رجل من المسلمين يمونه.", 217, 398], ["الرحيل عن الطائف", "ولم يأذن في فتح الطائف. فأمر رسول الله صلى الله عليه وسلم عمر بن الخطاب رضي الله عنه، فأذن بالرحيل، فضج الناس من ذلك، وقالوا: نرحل، ولم يفتح علينا؟ فقال رسول الله صلى الله عليه وسلم: «فاغدوا على القتال» فغدوا، فأصابهم جراحات. فقال النبي صلى الله عليه وسلم: «إنا قافلون إن شاء الله» فسروا بذلك. وجعلوا يرحلون ورسول الله صلى الله عليه وسلم يضحك.", 217, 399], ["عمرة الجعرانة والرجوع إلى المدينة", "ثم خرج إلى الجعرانة. فدخل منها إلى مكة محرما بعمرة فقضاها. ثم رجع إلى المدينة.", 218, 400], ["قدوم النبي ﷺ المدينة من تبوك", "فصل قال ابن إسحاق: وقدم رسول الله صلى الله عليه وسلم المدينة من تبوك في رمضان. وقدم عليه في ذلك الشهر وفد ثقيف.", 219, 401], ["وفد ثقيف", "فصل قال ابن إسحاق: وقدم رسول الله صلى الله عليه وسلم المدينة من تبوك في رمضان. وقدم عليه في ذلك الشهر وفد ثقيف.", 219, 402], ["إسلام عروة بن مسعود ومقتله في قومه", "وكان من حديثهم: \" أن رسول الله صلى الله عليه وسلم لما انصرف عنهم \" اتبع أثره عروة بن مسعود، حتى أدركه قبل أن يدخل المدينة. فأسلم، وسأله: أن يرجع إلى قومه بالإسلام، فقال له رسول الله صلى الله عليه وسلم: «إن فيهم نخوة الامتناع» فقال: يا رسول الله، أنا أحب إليهم من أبكارهم. وكان فيهم كذلك محببا مطاعا.", 219, 403], ["ائتمار ثقيف على الإرسال إلى رسول الله ﷺ", "ثم أقامت ثقيف بعد قتل عروة شهرا. ثم ائتمروا بينهم. ورأوا أنهم لا طاقة لهم بحرب من حولهم من العرب، وقد أسلموا وبايعوا. فأجمعوا أن يرسلوا إلى رسول الله صلى الله عليه وسلم رجلا، كما أرسلوا عروة.", 219, 404], ["قدوم عبد ياليل ومن معه وتأمير عثمان بن أبي العاص", "فلما أسلموا أمر عليهم عثمان بن أبي العاص - وكان من أحدثهم سنا - وذلك: أنه كان من أحرصهم على التفقه في الدين، وتعلم القرآن.", 220, 405], ["هدم اللات", "فلما توجهوا راجعين بعث معهم أبا سفيان والمغيرة بن شعبة، حتى إذا قدموا الطائف أراد المغيرة: أن يقدم أبا سفيان، فأبى، وقال: ادخل أنت على قومك. وأقام أبو سفيان بماله بذي الهدم. فلما دخل المغيرة علاها يضربها بالمعول. وقام دونه بنو مغيث، خشية أن يرمى، كما فعل بعروة، وخرج نساء ثقيف حسرا يبكين عليها. فلما هدمها أخذ مالها وحليها وأرسل به إلى أبي سفيان.", 220, 406], ["بعث المصدقين لأخذ الصدقات", "حوادث سنة تسع ولما قدم رسول الله صلى الله عليه وسلم المدينة، ودخلت سنة تسع، بعث المصدقين يأخذون الصدقات من الأعراب.", 223, 408], ["بعث علي لهدم صنم طيء وهروب عدي إلى الشام", "وفيها: بعث عليا رضي الله عنه إلى صنم طيئ ليهدمه. فشنوا الغارة على محلة آل حاتم مع الفجر. فهدموه. وملئوا أيديهم من السبي والنعم والشاء. وفي السبي سفانة أخت عدي بن حاتم، وهرب عدي إلى الشام. ووجدوا في خزانته ثلاثة أسياف، وثلاثة أدرع. وقسم علي الغنائم في الطريق، ولم يقسم السبي من آل حاتم حتى قدم بهم المدينة.", 223, 409], ["المن على ابنة حاتم", "وقد بلغ رسول الله صلى الله عليه وسلم هربي إلى الشام. فمر بها. فقالت: «يا رسول الله، غاب الوافد، وانقطع الوالد، وأنا عجوز كبيرة ما بي من خدمة، فمن علي. من الله عليك. فقال: \" من وافدك؟ . قالت: عدي بن حاتم، قال: \" الذي فر من الله ورسوله؟ \" - وكررت عليه القول ثلاثة أيام - قالت: فمن علي، وسألته الحملان، فأمر لها به وكساها وحملها وأعطاها نفقة» .", 224, 410], ["قدوم عدي بن حاتم وإسلامه", "فأتتني. فقالت: لقد فعل فعلة ما كان أبوك يفعلها. ائته راغبا أو راهبا، فقد أتاه فلان فأصاب منه، وأتاه فلان فأصاب منه. قال: فأتيته، وهو جالس في المسجد. فقال القوم: هذا عدي بن حاتم - وجئت بغير أمان ولا كتاب - فأخذ بيدي - وكان قبل ذلك قال: \" إني لأرجو أن يجعل الله يده في يدي \" - فقام إلي، فلقيت امرأة ومعها صبي. فقالا: إن لنا إليك حاجة. فقام معهما حتى قضى حاجتهما. ثم أخذ بيدي حتى أتى داره. فألقت له الوليدة وسادة. فجلس عليها، وجلست بين يديه. فحمد الله وأثنى عليه. ثم قال: «ما يفرك؟ أيفرك (1) أن يقال: \" لا إله إلا الله؟ \" فهل تعلم من إله سوى الله؟ \" فقلت: لا. فتكلم ساعة. ثم قال: \" أيفرك أن يقال: الله أكبر؟ وهل تعلم شيئا أكبر من الله؟ \" قلت: لا، قال: \" فإن اليهود مغضوب عليهم. والنصارى ضالون \"، فقلت: فإني حنيف مسلم. فرأيت وجهه ينبسط فرحا» .", 224, 411], ["قصة كعب بن زهير", "قال ابن إسحاق: لما قدم رسول الله صلى الله عليه وسلم من الطائف كتب بجير بن زهير إلى أخيه كعب: يخبره أن رسول الله صلى الله عليه وسلم قد قتل رجالا بمكة ممن كان يهجوه ويؤذيه، وأن من بقي من شعراء قريش - ابن الزبعرى، وهبيرة بن أبي وهب - قد هربوا في كل وجه. فإن كان لك في نفسك حاجة فطر إلى رسول الله صلى الله عليه وسلم. فأنه لا يقتل أحدا جاءه تائبا، وإن أنت لم تفعل فانج إلى نجائبك. وكان قد قال: -", 225, 412], ["قدوم كعب بن زهير وإسلامه", "فلما بلغ كعبا ضاقت عليه الأرض. وأشفق على نفسه، فلما لم يجد من شيء بدا، قال قصيدته التي مدح فيها رسول الله صلى الله عليه وسلم، ثم خرج حتى قدم المدينة. فنزل على رجل كان بينه وبينه معرفة. فغدا به إلى رسول الله صلى الله عليه وسلم. فذكر لي أنه قام فجلس إليه - وكان رسول الله صلى الله عليه وسلم لا يعرفه - فقال: «يا رسول الله، إن كعب بن زهير قد جاء ليستأمنك تائبا مسلما، فهل أنت قابل منه، إن أنا جئتك به؟ قال: \" نعم \": قال: أنا كعب بن زهير.»", 227, 413], ["غزوة تبوك", "قال ابن إسحاق: كانت في زمان عسرة من الناس، وجدب من البلاد، حين طابت الثمار، فالناس يحبون المقام في ثمارهم وظلالهم. وكان صلى الله عليه وسلم قلما يخرج في غزوة إلا ورى بغيرها، إلا ما كان منها، فإنه جلاها للناس لبعد الشقة، وشدة الزمان.", 230, 414], ["استئذان الجد بن قيس في التخلف", "فقال ذات يوم - وهو في جهازه - للجد بن قيس «هل لك في جلاد بني الأصفر؟ \" فقال: يا رسول الله، أوتأذن لي ولا تفتني؛ فقد عرف قومي أنه ما من رجل أشد عجبا بالنساء مني، وإني أخشى إن رأيت نساء بني الأصفر، ألا أصبر، فقال: \" قد أذنت لك» ففيه نزلت: {ومنهم من يقول ائذن لي ولا تفتني} [التوبة: 49] الآية (1) .", 230, 415], ["نفقة عثمان في جيش العسرة", "ثم إن رسول الله صلى الله عليه وسلم حض أهل الغنى على النفقة. فحمل رجال من أهل الغنى واحتسبوا. وأنفق عثمان ثلاثمائة بعير بأحلاسها، وأقتابها وعدتها، وألف دينار عينا.", 230, 416], ["مجيء البكائين", "وجاء البكاءون - وهم سبعة - يستحملون رسول الله صلى الله عليه وسلم. فقال: «لا أجد ما أحملكم عليه» تولوا وأعينهم تفيض من الدمع حزنا ألا يجدوا ما ينفقون.", 231, 417], ["تصدق علبة بن يزيد بعرضه", "وقام علبة بن يزيد، فصلى من الليل وبكى. ثم قال: «اللهم إنك أمرت بالجهاد، ورغبت فيه، ثم لم تجعل عندي ما أتقوى به مع رسولك، ولم تجعل في يد رسولك ما يحملني عليه، وإني أتصدق على كل مسلم بكل مظلمة أصابني فيها: من مال، أو جسد أو عرض، ثم أصبح مع الناس. فقال النبي صلى الله عليه وسلم أين المتصدق هذه الليلة؟ فلم يقم أحد، ثم قال: أين المتصدق؟ فلم يقم. فقام إليه فأخبره، فقال صلى الله عليه وسلم: أبشر، فوالذي نفس محمد بيده، لقد كتبت في الزكاة المتقبلة» \".", 231, 418], ["الخروج إلى تبوك وتخلف المنافقين ونفر من المسلمين", "واستخلف على المدينة محمد بن مسلمة الأنصاري. فلما سار رسول الله صلى الله عليه وسلم، تخلف عبد الله بن أبي ومن كان معه، وتخلف نفر من المسلمين من غير شك ولا ارتياب، منهم الثلاثة - كعب بن مالك. وهلال بن أمية. ومرارة بن الربيع - وأبو خيثمة السالمي، وأبو ذر. . . ثم لحقاه. وشهدها رسول الله صلى الله عليه وسلم في ثلاثين ألفا من الناس، والخيل عشرة آلاف فرس. وأقام بها عشرين ليلة يقصر الصلاة، وهرقل يومئذ بحمص.", 231, 419], ["تخليف علي على أهله ولحاقه بالجرف", "قال ابن إسحاق: «ولما خرج رسول الله صلى الله عليه وسلم خلف عليا على أهله. فقال المنافقون: ما خلفه إلا استثقالا له، وتخففا منه، فأخذ سلاحه ولحق به بالجرف، فقال: يا نبي الله: زعم المنافقون: أنك ما خلفتني إلا استثقالا، فقال: \" كذبوا، ولكني خلفتك لما تركت ورائي، فارجع فاخلفني في أهلي وأهلك، أولا ترضى أن تكون مني بمنزلة هارون من موسى؟ إلا أنه لا نبي بعدي» فرجع.", 231, 420], ["لحاق أبي خيثمة برسول الله ﷺ", "ودخل أبو خيثمة إلى أهله في يوم حار، بعد ما سار رسول الله صلى الله عليه وسلم أياما، فوجد امرأتين له في عريشين لهما في حائط، قد رشت كل واحدة منهما عريشها، وبردت له ماء، وهيأت له طعاما. فلما دخل قام على باب العريش، فنظر إلى امرأتيه وما صنعتا. فقال: رسول الله في الضح والريح والحر، وأبو خيثمة في ظل بارد، وطعام مهيأ، وامرأة حسناء؟ ما هذا بالنصف. ثم قال: والله لا أدخل عريش واحدة منكما حتى ألحق برسول الله صلى الله عليه وسلم. فهيئا لي زادا، ففعلتا. ثم قدم ناضحه فارتحله، ثم خرج حتى أدرك رسول الله صلى الله عليه وسلم حين نزل تبوك.", 232, 421], ["المرور بالحجر من ديار ثمود", "وقد كان رسول الله صلى الله عليه وسلم، لما مر بالحجر - من ديار ثمود - قال: «لا تدخلوا على هؤلاء القوم المعذبين، إلا أن تكونوا باكين، فإن لم تكونوا باكين فلا تدخلوا عليهم، لا يصيبكم مثل ما أصابهم» وقال: «لا تشربوا من مائها شيئا، ولا تتوضئوا منه للصلاة وما كان من عجين عجنتموه فاعلفوه الإبل ولا تأكلوا منه شيئا، وأمرهم أن يهرقوا الماء، وأن يستقوا من البئر التي كانت تردها الناقة» .", 232, 422], ["الريح الشديدة بتبوك", "وفي صحيح مسلم عن أبي حميد الساعدي قال: «انطلقنا حتى قدمنا تبوك. فقال رسول الله صلى الله عليه وسلم: ستهب عليكم الليلة ريح شديدة. فلا يقم أحد منكم. فمن كان له بعير فليشد عقاله. فهبت ريح شديدة، فقام رجل. فحملته الريح حتى ألقته بجبلي طيئ» .", 233, 423], ["نزول المطر بالدعاء", "قال ابن إسحاق: وأصبح الناس ولا ماء معهم. فشكوا ذلك إلى رسول الله صلى الله عليه وسلم، فدعا الله. فأرسل الله سحابة. فأمطرت حتى ارتوى الناس واحتملوا حاجتهم من الماء.", 233, 424], ["لحاق أبي ذر ماشيا", "وتلوم على أبي ذر بعيره. فلما أبطأ عليه أخذ متاعه على ظهره، ثم خرج يتبع أثر رسول الله صلى الله عليه وسلم ماشيا.", 233, 425], ["وفاة أبي ذر بفلاة من الأرض", "وفي صحيح ابن حبان عن أم ذر قالت \" لما حضرت أبا ذر الوفاة بكيت، فقال: ما يبكيك؟ فقلت: وما لي لا أبكي، وأنت تموت بفلاة من الأرض، وليس عندي ثوب يسعك كفنا، ولا يدان لي في تغيبك؟ فقال: أبشري ولا تبكي، فإني سمعت رسول الله صلى الله عليه وسلم يقول لنفر - وأنا فيهم -: «ليموتن رجل منكم بفلاة من الأرض، يشهده عصابة من المسلمين. وليس من أولئك النفر أحد إلا وقد مات في قرية وجماعة» ، فأنا ذلك الرجل، فوالله ما كذبت ولا كذبت. فأبصري الطريق. فكنت أشتد إلى الكثيب أتبصر، ثم أرجع فأمرضه. فبينا أنا وهو كذلك، إذا أنا برجال على رحالهم، كأنهم الرخم، تخب بهم رواحلهم، قالت: فأشرت إليهم. فأسرعوا إلي حتى وقفوا علي. فقالوا: يا أمة الله، ما لك؟ قلت: امرؤ من المسلمين يموت تكفنونه. قالوا: من هو؟ قلت: أبو ذر، قالوا: صاحب رسول الله صلى الله عليه وسلم؟ قلت: نعم، ففدوه بآبائهم وأمهاتهم، وأسرعوا إليه حتى دخلوا عليه. فقال لهم: أبشروا، فإني سمعت رسول الله صلى الله عليه وسلم - وذكر الحديث - ثم قال: وإنه لو كان عندي ثوب يسعني كفنا لي ولامرأتي لم أكفن إلا في ثوب هو لي، أو لها. فإني أنشدكم الله ألا يكفنني رجل منكم كان أميرا أو عريفا، أو بريدا أو نقيبا. وليس من أولئك النفر أحد إلا وقد قارف بعض ما قال إلا فتى من الأنصار، قال: يا عم، أنا أكفنك في ردائي هذا. وفي ثوبين في عيبتي من غزل أمي، قال: فأنت تكفنني، فكفنه الأنصاري، وأقاموا عليه ودفنوه في نفر كلهم يمان \".", 234, 426], ["مصالحة صاحب أيلة وأهل جربا وأذرح", "ولما انتهى رسول الله صلى الله عليه وسلم إلى تبوك، أتاه صاحب أيلة، فصالحه وأعطاه الجزية، وأتاه أهل جربا وأذرح، فأعطوه الجزية، وكتب لهم كتابا. فهو عندهم.", 234, 427], ["بعث خالد بن الوليد إلى أكيدر دومة", "ثم بعث خالد بن الوليد إلى أكيدر دومة، وقال لخالد: «إنك تجده يصيد البقر» فخرج خالد، حتى إذا كان من حصنه بمنظر العين في ليلة مقمرة - وهو على سطح له - فبانت البقر تحك بقرونها باب القصر. فقالت له امرأته: هل رأيت مثل هذا قط؟ قال: لا والله. قالت: فمن يترك مثل هذه؟ قال: لا أحد. ثم نزل فأمر بفرسه فأسرج له، وركب معه نفر من أهل بيته. فلما خرجوا، تلقتهم خيل رسول الله صلى الله عليه وسلم، فأخذته وقتلوا أخاه. وقدم به خالد على رسول الله صلى الله عليه وسلم، فحقن له دمه. وصالحه على الجزية، ثم خلى سبيله. فرجع إلى قريته.", 235, 428], ["الانصراف من تبوك إلى المدينة", "قال ابن إسحاق: فأقام رسول الله صلى الله عليه وسلم بتبوك بضع عشرة ليلة. ثم انصرف إلى المدينة. قال: وحدثني محمد بن إبراهيم بن الحارث التميمي: أن ابن مسعود كان يحدث، قال: \" قمت من جوف الليل، وأنا مع رسول الله صلى الله عليه وسلم في غزوة تبوك، فرأيت شعلة من نار في ناحية العسكر، فاتبعتها أنظر إليها. فإذا رسول الله صلى الله عليه وسلم وأبو بكر وعمر. وإذا عبد الله ذو البجادين - والبجاد الكساء الأسود - المزني قد مات، وإذا هم قد حفروا له، ورسول الله صلى الله عليه وسلم في حفرته، وأبو بكر وعمر، يدليانه إليه. وهو يقول: أدليا إلي أخاكما. فأدلياه إليه. فلما هيأه لشقه، قال: اللهم إني قد أمسيت راضيا عنه، فارض عنه \" قال: يقول عبد الله بن مسعود: \" يا ليتني كنت صاحب الحفرة \".", 235, 429], ["موت عبد الله ذي البجادين", "قال ابن إسحاق: فأقام رسول الله صلى الله عليه وسلم بتبوك بضع عشرة ليلة. ثم انصرف إلى المدينة. قال: وحدثني محمد بن إبراهيم بن الحارث التميمي: أن ابن مسعود كان يحدث، قال: \" قمت من جوف الليل، وأنا مع رسول الله صلى الله عليه وسلم في غزوة تبوك، فرأيت شعلة من نار في ناحية العسكر، فاتبعتها أنظر إليها. فإذا رسول الله صلى الله عليه وسلم وأبو بكر وعمر. وإذا عبد الله ذو البجادين - والبجاد الكساء الأسود - المزني قد مات، وإذا هم قد حفروا له، ورسول الله صلى الله عليه وسلم في حفرته، وأبو بكر وعمر، يدليانه إليه. وهو يقول: أدليا إلي أخاكما. فأدلياه إليه. فلما هيأه لشقه، قال: اللهم إني قد أمسيت راضيا عنه، فارض عنه \" قال: يقول عبد الله بن مسعود: \" يا ليتني كنت صاحب الحفرة \".", 235, 430], ["مسجد الضرار وهدمه", "وأقبل رسول الله صلى الله عليه وسلم من تبوك، حتى كان بينه وبين المدينة ساعة. وكان أصحاب مسجد الضرار أتوه - وهو يتجهز إلى تبوك - فقالوا: «يا رسول الله، إنا بنينا مسجدا لذي العلة والحاجة، والليلة المطيرة. وإنا نحب أن تصلي فيه. فقال: \" إني على جناح سفر، ولو قدمنا إن شاء الله لأتيناكم \".", 235, 431], ["تلقي أهل المدينة لرسول الله ﷺ", "ولما دنا رسول الله صلى الله عليه وسلم من المدينة، خرج الناس لتلقيه، والنساء والصبيان والولائد يقلن:", 236, 432], ["قصة الثلاثة الذين خلفوا وتوبتهم", "وفي غزوة تبوك: كانت قصة تخلف كعب بن مالك، ومرارة بن الربيع، وهلال بن أمية الواقفي. ممن شهدوا بدرا. ولم يكن لهم عذر في التخلف عن رسول الله صلى الله عليه وسلم. فلما عاد رسول الله صلى الله عليه وسلم إلى المدينة، جاء المعذرون من الأعراب من المنافقين، يحلفون أنهم كانوا معذورين. فقبل منهم رسول الله صلى الله عليه وسلم، وأرجأ كعب بن مالك وصاحبيه حتى أنزل الله في شأنهم وفي توبتهم - وكانوا من خيار المؤمنين -: {لقد تاب الله على النبي والمهاجرين والأنصار الذين اتبعوه في ساعة العسرة من بعد ما كاد يزيغ قلوب فريق منهم ثم تاب عليهم إنه بهم رءوف رحيم - وعلى الثلاثة الذين خلفوا} [التوبة: 117 - 118] الآيتين (1) . خلفهم الله وأخر توبتهم ليمحصهم ويطهرهم من ذنب تأخرهم. لأنهم كانوا من الصادقين.", 237, 433], ["وفود العرب سنة الوفود", "ولما فرغ رسول الله صلى الله عليه وسلم من تبوك، وأسلمت ثقيف. ضربت إليه أكباد الإبل، تحمل وفود العرب من كل وجه، في سنة تسع. وكانت تسمى: سنة الوفود.", 237, 434], ["سرية عيينة بن حصن إلى بني تميم", "فقدم عليه عطارد بن حاجب التميمي، في أشراف من بني تميم، جاءوا في أسرى بني تميم، الذين أخذتهم سرية عيينة بن حصن الفزاري في المحرم من هذه السنة. وكان عيينة قد أخذ أحد عشر رجلا، وإحدى وعشرين امرأة، وثلاثين صبيا. وساقهم إلى المدينة. فقدم رؤساء بني تميم فيهم. فلما دخلوا المسجد، نادوا رسول الله صلى الله عليه وسلم من وراء الحجرات - وهو في بيته - أن اخرج إلينا. فآذى ذلك رسول الله صلى الله عليه وسلم. فأنزل الله فيهم: {إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون - ولو أنهم صبروا حتى تخرج إليهم لكان خيرا لهم والله غفور رحيم} [الحجرات: 4 - 5] (2) .", 238, 435], ["وفد بني تميم", "فقدم عليه عطارد بن حاجب التميمي، في أشراف من بني تميم، جاءوا في أسرى بني تميم، الذين أخذتهم سرية عيينة بن حصن الفزاري في المحرم من هذه السنة. وكان عيينة قد أخذ أحد عشر رجلا، وإحدى وعشرين امرأة، وثلاثين صبيا. وساقهم إلى المدينة. فقدم رؤساء بني تميم فيهم. فلما دخلوا المسجد، نادوا رسول الله صلى الله عليه وسلم من وراء الحجرات - وهو في بيته - أن اخرج إلينا. فآذى ذلك رسول الله صلى الله عليه وسلم. فأنزل الله فيهم: {إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون - ولو أنهم صبروا حتى تخرج إليهم لكان خيرا لهم والله غفور رحيم} [الحجرات: 4 - 5] (2) .", 238, 436], ["إسلام وفد بني تميم", "لخطيبه أخطب من خطيبنا، ولشاعره أشعر من شاعرنا، ولأصواتهم أحلى من أصواتنا. فلما فرغ القوم أسلموا، وجوزهم رسول الله صلى الله عليه وسلم فأحسن جوائزهم.", 241, 437], ["وفد طيء", "وقدم على رسول الله صلى الله عليه وسلم وفد طيئ، فيهم زيد الخيل - وهو سيدهم - فعرض عليهم رسول الله صلى الله عليه وسلم الإسلام فأسلموا وحسن إسلامهم.", 241, 438], ["موت زيد الخيل", "ثم سماه رسول الله صلى الله عليه وسلم \" زيد الخير \" وأقطعه \" فيدا \" وأرضين معه، وكتب له بذلك كتابا. فخرج من عنده راجعا إلى قومه، فلما انتهى إلى ماء من مياه نجد - يقال له \" فردة \" - أصابته الحمى بها فمات. فعمدت امرأته إلى ما كان معه من الكتب التي أقطع له بها رسول الله صلى الله عليه وسلم، فحرقتها بالنار.", 242, 439], ["وفد عبد القيس", "وقدم على رسول الله صلى الله عليه وسلم، الجارود العبدي في وفد عبد القيس، وكان نصرانيا، فقال: يا رسول الله، إني على ديني. وإني تارك ديني لدينك، فتضمن لي بما فيه؟ قال: \" نعم. أنا ضامن لذلك، إن الذي أدعوك إليه خير من الذي كنت عليه \" فأسلم وأسلم أصحابه. فكان حسن الإسلام صلبا في دينه، حتى هلك، وقد أدرك الردة. وكان في الوفد \" الأشج \" الذي قال له رسول الله صلى الله عليه وسلم: «إن فيك لخصلتين يحبهما الله: الحلم والأناة \".» .", 242, 440], ["إسلام المنذر بن ساوى", "وقد كان رسول الله صلى الله عليه وسلم بعث العلاء بن الحضرمي - قبل فتح مكة - إلى المنذر بن ساوى العبدي، فأسلم وحسن إسلامه. ثم هلك بعد رسول الله صلى الله عليه وسلم، وفي ردة أهل البحرين. والعلاء عنده أمير الرسول صلى الله عليه وسلم على البحرين.", 242, 441], ["وفد بني حنيفة", "وقدم على رسول الله صلى الله عليه وسلم وفد بني حنيفة، فيهم مسيلمة الكذاب، فأتوه وخلفوا مسيلمة في رحالهم، فلما أسلموا ذكروا مكانه، فقالوا: يا رسول الله، إنا قد خلفنا صاحبا لنا في رحالنا يحفظها لنا. فأمر له بمثل ما أمر به للقوم، وقال: «أما أنه ليس بشركم مكانا» يعني لحفظه ضيعة أصحابه. ثم انصرفوا فلما انتهوا إلى اليمامة، ارتد عدو الله وتنبأ، وقال: إني أشركت في الأمر معه. وقال للوفد: ألم يقل لكم: \" أما أنه ليس بشركم مكانا؟ \" ما ذاك إلا لما كان يعلم أني أشركت في الأمر معه. ثم جعل يسجع لهم السجعات، مضاهاة للقرآن، وهو مع ذلك يشهد لرسول الله صلى الله عليه وسلم بالنبوة.", 243, 442], ["ردة مسيلمة وادعاؤه النبوة", "وقدم على رسول الله صلى الله عليه وسلم وفد بني حنيفة، فيهم مسيلمة الكذاب، فأتوه وخلفوا مسيلمة في رحالهم، فلما أسلموا ذكروا مكانه، فقالوا: يا رسول الله، إنا قد خلفنا صاحبا لنا في رحالنا يحفظها لنا. فأمر له بمثل ما أمر به للقوم، وقال: «أما أنه ليس بشركم مكانا» يعني لحفظه ضيعة أصحابه. ثم انصرفوا فلما انتهوا إلى اليمامة، ارتد عدو الله وتنبأ، وقال: إني أشركت في الأمر معه. وقال للوفد: ألم يقل لكم: \" أما أنه ليس بشركم مكانا؟ \" ما ذاك إلا لما كان يعلم أني أشركت في الأمر معه. ثم جعل يسجع لهم السجعات، مضاهاة للقرآن، وهو مع ذلك يشهد لرسول الله صلى الله عليه وسلم بالنبوة.", 243, 443], ["كتاب مسيلمة وجواب رسول الله ﷺ", "وكتب لرسول الله صلى الله عليه وسلم: من مسيلمة رسول الله إلى محمد رسول الله، أما بعد. فإني أشركت في الأمر معك. وإن لنا نصف الأرض ولقريش نصفها، ولكن قريشا قوم لا يعدلون.", 243, 444], ["حجة أبي بكر بالناس", "ثم أقام رسول الله صلى الله عليه وسلم بعد رجوعه من تبوك - بقية رمضان وشوالا وذا القعدة - ثم بعث أبا بكر رضي الله عنه أميرا على الحج ليقيم للناس حجهم. وأهل الشرك على دينهم ومنازلهم من حجهم. فخرج أبو بكر في ثلاثمائة من المدينة. وبعث معه رسول الله صلى الله عليه وسلم بعشرين بدنة. قلدها وأشعرها بيده. ثم نزلت سورة براءة في نقض ما بين رسول الله صلى الله عليه وسلم وبين المشركين من العهد الذي كانوا عليه. فأرسل بها علي بن أبي طالب على ناقته العضباء، ليقرأ براءة على الناس. وينبذ إلى كل ذي عهد عهده. فلما لقي أبا بكر قال له: \" أمير أو مأمور؟ فقال علي: بل مأمور \" فلما كان يوم النحر قام علي بن أبي طالب. فقال: \" يا أيها الناس، لا يدخل الجنة كافر، ولا يحج بعد العام مشرك، ولا يطوف بالبيت عريان. ومن كان له عهد عند رسول الله صلى الله عليه وسلم فهو إلى مدته \" (1) .", 244, 445], ["نزول براءة وقراءة علي لها يوم النحر", "ثم أقام رسول الله صلى الله عليه وسلم بعد رجوعه من تبوك - بقية رمضان وشوالا وذا القعدة - ثم بعث أبا بكر رضي الله عنه أميرا على الحج ليقيم للناس حجهم. وأهل الشرك على دينهم ومنازلهم من حجهم. فخرج أبو بكر في ثلاثمائة من المدينة. وبعث معه رسول الله صلى الله عليه وسلم بعشرين بدنة. قلدها وأشعرها بيده. ثم نزلت سورة براءة في نقض ما بين رسول الله صلى الله عليه وسلم وبين المشركين من العهد الذي كانوا عليه. فأرسل بها علي بن أبي طالب على ناقته العضباء، ليقرأ براءة على الناس. وينبذ إلى كل ذي عهد عهده. فلما لقي أبا بكر قال له: \" أمير أو مأمور؟ فقال علي: بل مأمور \" فلما كان يوم النحر قام علي بن أبي طالب. فقال: \" يا أيها الناس، لا يدخل الجنة كافر، ولا يحج بعد العام مشرك، ولا يطوف بالبيت عريان. ومن كان له عهد عند رسول الله صلى الله عليه وسلم فهو إلى مدته \" (1) .", 244, 446], ["حجة الوداع", "فخرج لها لخمس بقين من ذي القعدة في آخر سنة عشر. فمضى رسول الله صلى الله عليه وسلم، وساق معه الهدي. فأرى الناس مناسكهم، وعلمهم سنن حجهم. وهو صلى الله عليه وسلم يقول لهم ويكرر عليهم «أيها الناس خذوا عني مناسككم. فلعلكم لا تلقوني بعد عامكم هذا» .", 245, 447], ["خطبته بمنى", "ولما كان بمنى خطب الناس خطبته التي بين فيها ما بين: \" فحمد الله وأثنى عليه. ثم قال: «أيها الناس: اسمعوا قولي: فإني لا أدري، لعلي لا ألقاكم بعد عامي هذا. أيها الناس، إن دماءكم وأموالكم وأعراضكم عليكم حرام إلى أن تلقوا ربكم. وكل ربا موضوع. وأول ربا أضعه: ربا العباس بن عبد المطلب. فأنه موضوع كله. وإن كل دم في الجاهلية موضوع، وأول دم أضعه: دم ربيعة بن الحارث بن عبد المطلب. وإني تركت فيكم ما إن اعتصمتم به لم تضلوا - كتاب الله -، وأنتم مسئولون عني. فما أنتم قائلون؟ قالوا: نشهد أنك قد بلغت، وأديت، ونصحت. فجعل يرفع إصبعه إلى السماء، وينكبها إليهم، ويقول اللهم اشهد - ثلاث مرات» .", 245, 448], ["الرجوع إلى المدينة بعد الحج", "فلما انقضى حجه، رجع إلى المدينة. فأقام صلى الله عليه وسلم بقية ذي الحجة والمحرم وصفر.", 246, 449], ["ابتداء وجع رسول الله ﷺ", "ثم ابتدأ برسول الله صلى الله عليه وسلم وجعه الذي مات فيه في آخر صفر.", 246, 450], ["بعث أسامة بن زيد إلى البلقاء", "ولما كان يوم الاثنين لأربع ليال بقين من صفر سنة إحدى عشرة. أمر رسول الله صلى الله عليه وسلم الناس بالتهيؤ لغزو الروم. فلما كان من الغد دعا أسامة بن زيد. وأمره أن يسير إلى موضع مقتل أبيه زيد بن حارثة، وأن يوطئ الخيل تخوم البلقاء والداروم من أرض فلسطين. فتجهز الناس، وأوعب مع أسامة المهاجرون والأنصار.", 246, 451], ["خطبته في إنفاذ بعث أسامة", "ثم استبطأ رسول الله صلى الله عليه وسلم الناس في بعث أسامة - وهو في وجعه - فخرج عاصبا رأسه حتى جلس على المنبر، وكان المنافقون قد قالوا في إمارة أسامة: أمر غلاما حدثا على جلة المهاجرين والأنصار. فغضب رسول الله صلى الله عليه وسلم غضبا شديدا. وخرج عاصبا رأسه - وكان قد بدأ به الوجع - فصعد المنبر \" فحمد الله وأثنى عليه، ثم قال: أيها الناس، أنفذوا بعث أسامة، فلئن طعنتم في إمارته فقد طعنتم في إمارة أبيه. وأيم الله إن كان لخليقا للإمارة. وإن ابنه من بعده لخليق للإمارة، وإن كان أبوه لمن أحب الناس إلي. وإن هذا لمن أحب الناس إلي من بعده \" ثم نزل.", 246, 452], ["عسكرة أسامة بالجرف", "وانكمش الناس في جهازهم. فاشتد برسول الله صلى الله عليه وسلم وجعه. وخرج أسامة بجيشه، فعسكر بالجرف، وتتام إليه الناس. فأقاموا لينظروا ما الله تبارك وتعالى قاض في رسوله صلى الله عليه وسلم.", 247, 453], ["مرض رسول الله ﷺ", "قال ابن إسحاق: حدثت عن «أسامة قال: \" لما ثقل برسول الله صلى الله عليه وسلم، هبطت وهبط الناس معي إلى المدينة، فدخلت على رسول الله صلى الله عليه وسلم، وقد أصمت، فلا يتكلم. وجعل يرفع يده إلى السماء ثم يضعها علي. أعرف أنه يدعو لي» .", 247, 454], ["استغفاره لأهل البقيع", "قال ابن إسحاق: وحدثت عن «أبي مويهبة مولى رسول الله صلى الله عليه وسلم قال: \" بعثني رسول الله صلى الله عليه وسلم من جوف الليل. فقال: يا أبا مويهبة، قد أمرت أن أستغفر لأهل هذا البقيع، فانطلق معي. فانطلقت معه. فلما وقف عليهم قال: السلام عليكم يا أهل المقابر، ليهن لكم ما أصبحتم فما أصبح الناس فيه. أقبلت الفتن مثل قطع الليل المظلم، يتبع أخراها أولاها، الآخرة شر من الأولى. ثم أقبل علي، فقال: إني قد أعطيت مفاتيح خزائن الدنيا والخلد فيها. فخيرت فيها بين ذلك وبين لقاء ربي والجنة. فقلت: بأبي أنت وأمي، فخذ مفاتيح خزائن الدنيا وتخلد فيها، ثم الجنة. قال: لا والله يا أبا مويهبة. قد اخترت لقاء ربي والجنة. ثم استغفر لأهل البقيع، ثم انصرف» .", 247, 455], ["تمريضه في بيت عائشة", "فبدأ به وجعه. فلما استعز به، دعا نساءه فاستأذنهن: أن يمرض في بيت عائشة رضي الله عنها، فأذن له.", 248, 456], ["خطبة تخيير العبد وسد الأبواب إلا باب أبي بكر", "وعن أبي سعيد الخدري رضي الله عنه قال: «خطب رسول الله صلى الله عليه وسلم، فقال: إن الله خير عبدا بين الدنيا وبين ما عنده، فاختار ذلك العبد ما عند الله. فبكى أبو بكر، فتعجبنا لبكائه: أن يخبر رسول الله صلى الله عليه وسلم عن عبد خير! فكان رسول الله صلى الله عليه وسلم هو المخير. وكان أبو بكر أعلمنا. فقال رسول الله صلى الله عليه وسلم: إن من أمن الناس علي في صحبته وماله: أبو بكر. ولو كنت متخذا خليلا - غير ربي - لاتخذت أبا بكر خليلا، ولكن أخوة الإسلام ومودته. لا يبقين في المسجد باب إلا سد، إلا باب أبي بكر» .", 248, 457], ["آخر صعوده المنبر والوصية بالأنصار", "وفي الصحيح: «أن ابن عباس وأبا بكر مرا بمجلس للأنصار، وهم يبكون. فقالا: ما يبكيكم؟ قالوا: ذكرنا مجلس رسول الله صلى الله عليه وسلم منا. فدخل على النبي صلى الله عليه وسلم. فأخبره بذلك. فخرج، وقد عصب على رأسه بحاشية برد. فصعد المنبر - ولم يصعده بعد ذلك اليوم - فحمد الله، وأثنى عليه، ثم قال: أوصيكم بالأنصار خيرا. فإنهم كرشي وعيبتي. وقد قضوا الذي عليهم. وبقي الذي لهم. فاقبلوا من محسنهم. وتجاوزوا عن مسيئهم» .", 248, 458], ["أمر أبي بكر بالصلاة بالناس", "وفي الصحيح عن أبي موسى الأشعري قال: «اشتد مرض رسول الله صلى الله عليه وسلم، فقال: مروا أبا بكر، فليصل بالناس، قالت عائشة: يا رسول الله، أنه رجل رقيق، إذا قام مقامك لا يسمع الناس، فلو أمرت عمر؟ قال: مروا أبا بكر فليصل بالناس، فعادت. فقال: مروا أبا بكر فليصل بالناس، فإنكن صواحب يوسف. فأتاه الرسول. فصلى بالناس في حياة النبي صلى الله عليه وسلم. قالت: ووالله ما أقول إلا أني أحب أن يصرف ذلك عن أبي بكر، وعرفت أن الناس لا يحبون رجلا قام مقامه أبدا، وأن الناس سيتشاءمون به في كل حدث كان. فكنت أحب أن يصرف ذلك عن أبي بكر» .", 248, 459], ["وفاة رسول الله ﷺ", "قال الزهري: حدثني أنس، قال: «كان يوم الاثنين الذي قبض فيه رسول الله صلى الله عليه وسلم، خرج إلى الناس، وهم يصلون الصبح فرفع الستر وفتح الباب. فخرج رسول الله صلى الله عليه وسلم. فقام على باب عائشة. فكاد المسلمون يفتنون في صلاتهم - فرحا به، حين رأوه، وتفرجوا عنه - فأشار إليهم: أن اثبتوا على صلاتكم، قال: وتبسم رسول الله صلى الله عليه وسلم سرورا، ولما رأى من هيئتهم في صلاتهم. وما رؤي أحسن منه هيئة تلك الساعة. قال: ثم رجع، وانصرف الناس، وهم يرون أنه قد أفرق من وجعه. وخرج أبو بكر إلى أهله بالسنح. فتوفي رسول الله صلى الله عليه وسلم حين اشتد الضحى من ذلك اليوم» .", 249, 460], ["مقالة عمر وخطبة أبي بكر بعد الوفاة", "قال ابن إسحاق: قال الزهري حدثني سعيد بن المسيب عن أبي هريرة قال: «لما توفي رسول الله صلى الله عليه وسلم قام عمر. فقال: إن رجالا من المنافقين يزعمون أن رسول الله صلى الله عليه وسلم قد توفي، وإن رسول الله صلى الله عليه وسلم والله ما مات، ولكنه قد ذهب إلى ربه، كما ذهب موسى بن عمران. فقد غاب عن قومه أربعين ليلة، ثم رجع إليهم بعد أن قيل مات. ووالله ليرجعن رسول الله صلى الله عليه وسلم بعد حين، كما رجع موسى، فليقطعن أيدي رجال وأرجلهم زعموا أنه قد مات. قال: وأقبل أبو بكر، حتى نزل على باب المسجد. حين بلغه الخبر - وعمر يكلم الناس - فلم يلتفت إلى شيء، حتى دخل على رسول الله صلى الله عليه وسلم في بيت عائشة، ورسول الله صلى الله عليه وسلم مسجى في ناحية البيت، عليه برد حبرة. فأقبل حتى كشف عن وجهه. ثم أقبل عليه فقبله ثم قال: بأبي أنت وأمي، أما الموتة التي كتبها الله عليك: فقد ذقتها، ثم لن تصيبك بعدها موتة أبدا. ثم رد البرد على وجهه. وخرج - وعمر يكلم الناس - فقال: على رسلك يا عمر، أنصت. فأبى إلا أن يتكلم. فلما رآه أبو بكر لا ينصت أقبل على الناس. فلما سمع الناس كلام أبي بكر أقبلوا عليه، وتركوا عمر. فحمد الله تعالى، وأثنى عليه. ثم قال: أيها الناس، أنه من كان يعبد محمدا. فإن محمدا قد مات. ومن كان يعبد الله تعالى، فإن الله حي لا يموت. قال: ثم تلا هذه الآية؛ {وما محمد إلا رسول قد خلت من قبله الرسل أفإن مات أو قتل انقلبتم على أعقابكم ومن ينقلب على عقبيه فلن يضر الله شيئا وسيجزي الله الشاكرين} [آل عمران: 144] » الآية (1) .", 249, 461]];
export const KH=[["حديث السقيفة", "فلما قبض رسول الله صلى الله عليه وسلم: انحاز هذا الحي من الأنصار إلى سعد بن عبادة في سقيفة بني ساعدة. واعتزل علي بن أبي طالب، والزبير بن العوام، وطلحة بن عبيد الله في بيت فاطمة. وانحاز المهاجرون إلى أبي بكر وعمر، ومعهم أسيد بن حضير في بني عبد الأشهل. فأتى آت إلى أبي بكر وعمر، فقال: إن هذا الحي من الأنصار مع سعد بن عبادة في سقيفة بني ساعدة قد انحازوا إليه. فإن كان لكم بأمر الناس من حاجة، فأدركوا الناس قبل أن يتفاقم أمرهم، ورسول الله صلى الله عليه وسلم في بيته لم يفرغ من أمره، قد أغلق دونه الباب أهله. فقال عمر لأبي بكر: انطلق بنا إلى إخواننا هؤلاء من الأنصار، حتى ننظر ما هم عليه.", 251, 462], ["خطبة عمر في شأن بيعة أبي بكر", "قال ابن إسحاق: وكان من حديث السقيفة: أن عبد الله بن أبي بكر حدثني عن محمد بن شهاب الزهري عن عبيد الله بن عبد الله بن عتبة بن مسعود عن ابن عباس قال: أخبرني عبد الرحمن بن عوف - وكنت في منزله بمنى أنتظره، وهو عند عمر في آخر حجة حجها عمر - قال: فرجع عبد الرحمن من عند عمر، فوجدني في منزله بمنى أنتظره، وكنت أقرئه القرآن. فقال لي: لو رأيت رجلا أتى أمير المؤمنين فقال: هل لك في فلان؟ يقول: والله لو قد مات عمر لقد بايعت فلانا. والله ما كانت بيعة أبي بكر إلا فلتة فتمت. فغضب عمر، وقال: إني - إن شاء الله - لقائم العشية في الناس، فمحذرهم من هؤلاء الذين يريدون أن يغصبوهم أمرهم، قال عبد الرحمن: فقلت لا تفعل، فإن الموسم يجمع رعاع الناس وغوغائهم، وإنهم الذين يغلبون على قربك حين تقوم في الناس. وإني أخشى أن تقوم فتقول مقالة يطيرها أولئك عنك كل مطير، ولا يعوها ولا يضعوها على مواضعها. فأمهل، حتى تقدم المدينة. فإنها دار السنة، وتخلص بأهل الفقه وأشراف الناس فتقول ما قلت بالمدينة متمكنا، فيعي أهل الفقه مقالتك، ويضعوها على مواضعها. فقال عمر: أما والله - إن شاء الله - لأقومن بذلك أول مقام أقومه بالمدينة.", 251, 463], ["بيعة أبي بكر في السقيفة", "فقلت: ابسط يدك يا أبا بكر. فبسطها، فبايعته. ثم بايعه المهاجرون. ثم بايعه الأنصار. ونزونا على سعد بن عبادة.", 255, 464], ["البيعة العامة لأبي بكر", "ولما بويع أبو بكر في السقيفة، وكان الغد، جلس أبو بكر على المنبر. فقام عمر قبل أبي بكر فتكلم فحمد الله، وأثنى عليه بما هو أهله، ثم قال: أيها الناس. إني قد قلت لكم بالأمس مقالة، ما كانت وما وجدتها في كتاب الله. ولا كانت عهدا عهده إلي رسول الله صلى الله عليه وسلم. ولكني قد كنت أرى أن رسول الله صلى الله عليه وسلم سيدبر أمرنا - يقول: يكون آخرنا - وإن الله قد أبقى فيكم كتابه الذي به هدى رسوله صلى الله عليه وسلم. فإن اعتصمتم به هداكم الله لما كان هدى له رسوله. إن الله قد جمعكم على خيركم - صاحب رسول الله صلى الله عليه وسلم، وثاني اثنين إذ هما في الغار - فقوموا فبايعوه. فبايع الناس أبا بكر البيعة العامة، بعد بيعة السقيفة.", 255, 465], ["خطبة أبي بكر بعد البيعة", "ثم تكلم أبو بكر رضي الله عنه. فحمد الله، وأثنى عليه بالذي هو أهله. ثم قال: \" أما بعد، أيها الناس، فإني قد وليت عليكم. ولست بخيركم، فإن أحسنت فأعينوني. وإن أسأت فقوموني. الصدق أمانة، والكذب خيانة. والضعيف فيكم قوي عندي حتى أريح عليه حقه إن شاء الله. والقوي فيكم ضعيف، حتى آخذ الحق منه، إن شاء الله. لا يدع قوم الجهاد في سبيل الله إلا ضربهم الله بالذل. ولا تشيع الفاحشة في قوم قط إلا عمهم الله بالبلاء. أطيعوني ما أطعت الله ورسوله. فإذا عصيت الله ورسوله، فلا طاعة لي عليكم \".", 255, 466], ["إنفاذ جيش أسامة وهزيمة الروم", "وعن أبي هريرة رضي الله عنه أنه قال: والذي لا إله إلا هو، لولا أن أبا بكر استخلف، ما عبد الله - ثم قال الثانية، ثم قال الثالثة - فقيل له: مه، يا أبا هريرة. فقال: إن رسول الله صلى الله عليه وسلم وجه أسامة بن زيد في سبعمائة إلى الشام. فلما نزل بذي خشب (1) قبض رسول الله، وارتدت العرب. واجتمع إليه الصحابة. فقالوا: رد هؤلاء، توجه هؤلاء إلى الروم، وقد ارتدت العرب حول المدينة؟ فقال: والذي لا إله إلا هو، لو جرت الكلاب بأرجل أزواج رسول الله صلى الله عليه وسلم، ما رددت جيشا وجهه رسول الله صلى الله عليه وسلم، ولا حللت لواء عقده. فوجه أسامة. فجعل لا يمر بقبائل يريدون الارتداد، إلا قالوا: لولا أن لهؤلاء قوة، ما خرج مثل هؤلاء من عندهم. ولكن ندعهم حتى يلقوا الروم. فلقوا الروم، فهزموهم. ورجعوا سالمين. فثبتوا على الإسلام - ولله الحمد.", 256, 467], ["تصدي الصديق لقتال أهل الردة ومانعي الزكاة", "وفي الصحيح عن أبي هريرة رضي الله عنه قال: \" لما توفي رسول الله صلى الله عليه وسلم، وكان أبو بكر، وكفر من كفر من العرب، قال عمر لأبي بكر: كيف تقاتل الناس، وقد قال رسول الله صلى الله عليه وسلم: «أمرت أن أقاتل الناس، حتى يقولوا: لا إله إلا الله. فإذا قالوها عصموا مني دماءهم وأموالهم، إلا بحقها» فقال أبو بكر: فإن الزكاة من حقها. والله لأقاتلن من فرق بين الصلاة والزكاة، والله لو منعوني عناقا كانوا يؤدونها إلى رسول الله صلى الله عليه وسلم لقاتلتهم على منعها. قال عمر: فما هو إلا أن رأيت الله قد شرح صدر أبي بكر للقتال، فعرفت أنه الحق. قال عمر: والله لرجح إيمان أبي بكر بإيمان هذه الأمة جميعا في قتال أهل الردة \".", 257, 468], ["قدوم عيينة والأقرع على أبي بكر", "فجادل الصحابة أبا بكر رضي الله عنهم، وقالوا: احبس جيش أسامة، فيكون أمانا بالمدينة، وارفق بالعرب حتى يتفرج هذا الأمر. فلو أن طائفة ارتدت، قلنا: قاتل بمن معك من ارتد. وقد أصفقت العرب على الارتداد. وقدم على أبي بكر عيينة بن حصن، والأقرع بن حابس في رجال من أشراف العرب. فدخلوا على رجال من المهاجرين، فقالوا: أنه قد ارتد عامة من وراءنا عن الإسلام. وليس في أنفسهم أن يؤدوا إليكم ما كانوا يؤدونه إلى رسول الله صلى الله عليه وسلم. فإن تجعلوا لنا جعلا كفيناكم. فدخل الصحابة على أبي بكر، فعرضوا عليه ذلك. وقالوا: نرى أن تطعم الأقرع وعيينة طعمة يرضيان بها، ويكفيانك من وراءها، حتى يرجع إلينا أسامة وجيشه، ويشتد أمرك، فإنا اليوم قليل في كثير.", 258, 469], ["تجهز أبي بكر للمسير إلى أهل الردة", "فأمر أبو بكر رضي الله عنه الناس بالتجهيز، وأجمع على المسير بنفسه.", 259, 470], ["بعث المصدقين في العرب", "وقد كان رسول الله صلى الله عليه وسلم - لما صدر من الحج سنة عشر - وقدم المدينة: أقام حتى رأى هلال المحرم سنة إحدى عشرة. فبعث المصدقين في العرب.", 259, 471], ["ثبات عدي بن حاتم وطيء على الإسلام", "فلما رأوا منه الجد كفوا عنه. وأسلموا له.", 260, 472], ["عدي بن حاتم وعمر", "فلما كان زمن عمر رأى من عمر جفوة. فقال له عدي ما أراك تعرفني؟ قال عمر بلى والله، والله يعرفك في السماء. أعرفك والله، أسلمت إذ كفروا، ووفيت إذ غدروا، وأقبلت إذا أدبروا. وايم الله أعرفك.", 261, 473], ["خروج أبي بكر لقتال أهل الردة", "ولما كان من العرب ما كان ومنع من منع منهم الصدقة. جد بأبي بكر الجد في قتالهم. وأراه الله رشده فيهم. وعزم على الخروج بنفسه. فخرج في مائة من المهاجرين والأنصار، وخالد يحمل اللواء حتى نزل بقعاء، يريد أن يتلاحق الناس ويكون أسرع لخروجهم. ووكل بالناس محمد بن مسلمة يستحثهم. وأقام ببقعاء أياما ينتظر الناس. ولم يبق أحد من المهاجرين والأنصار إلا خرج.", 261, 474], ["تأمير خالد على الناس", "فدعا أبا حذيفة بن عتبة فعرض عليه ذلك فقال مثلما قال زيد فدعا سالما مولى أبي حذيفة فأبى عليه. فدعا خالدا فأمره على الناس وكتب معه هذا الكتاب.", 261, 475], ["كتاب أبي بكر لأمرائه", "ويروى أن أبا بكر كتب مع هذا كتابا آخر وأمر خالدا أن يقرأه في كل مجمع، وهو:", 262, 476], ["مسير خالد إلى بزاخة", "لما سار خالد إلى بزاخة (2) كان عدي بن حاتم معه، وقد انضم إليه من طيء ألف، فنزلوا بزاخة وكانت جديلة معرضة عن الإسلام - وهي بطن من طيء - وكان عدي بن حاتم رضي الله عنه من الغوث، وقد همت جديلة أن ترتد فجاءهم مكنف بن زيد الخيل. فقال أتريدون أن تصيروا سبة على قومكم؟ ولم يرجع رجل واحد من طيء وهذا عدي معه ألف رجل من طيء، فكسرهم.", 265, 477], ["إسلام جديلة على يد عدي", "فجاءهم عدي. فدعاهم إلى الإسلام فأسلموا. فحمد الله. وسار بهم إلى خالد. فلما رآهم صاح في أصحابه السلاح. فلما جاءوا حلوا ناحية، فجاءهم خالد ورحب بهم. فاعتذروا إليه. وقالوا: نحن لك حيث شئت. فجزاهم خيرا. فلم يرتد من طيء رجل واحد.", 265, 478], ["دعوة خالد طليحة وإباؤه", "فلما انتهوا إلى طليحة الأسدي وجدوه وقد ضربت له قبة وأصحابه حوله. فضرب خالد خيام عسكره على ميل أو نحوه، وخرج يسير على فرس معه نفر من الصحابة. فوقف قريبا من العسكر. ودعا بطليحة فخرج إليه. فقال إن من عهد خليفتنا إلينا: أن ندعوك إلى الله وحده لا شريك له، وأن محمدا عبده ورسوله، وأن تعود إلى ما خرجت منه فأبى طليحة.", 266, 479], ["وقعة بزاخة", "فلما أبى طليحة أن يجيب خالدا، انصرف خالد إلى معسكره. فاستعمل تلك الليلة على حرسه مكنف بن زيد الخيل، وعدي بن حاتم. فلما كان من السحر نهض خالد. فعبأ أصحابه ووضع ألويته مواضعها. ودفع اللواء الأعظم إلى زيد بن الخطاب. فتقدم به. وتقدم ثابت بن قيس بن شماس بلواء الأنصار، وطلبت طيء لواء. فعقد لهم خالد لواء ودفعه إلى عدي.", 266, 480], ["قتل حبال بن أبي حبال", "فقال خالد: يا معشر المسلمين، الله الله. واقتحم وسط القوم وكر معه أصحابه. فاختلطت الصفوف ونادى يومئذ مناد من طيء عندما حمل أولئك الأربعون: يا خالد عليك - بسلمى وأجا - جبلي طيئ - فقال: بل إلى الله الملتجأ، ثم حمل فما رجع حتى لم يبق من الأربعين رجل واحد. وتراد الناس بعد الهزيمة واشتد القتال. وأسر حبال بن أبي حبال فأرادوا أن يبعثوا به إلى أبي بكر. فقال اضربوا عنقي، ولا تروني محمديكم هذا، فضربوا عنقه.", 267, 481], ["انصراف فزارة عن طليحة", "فقال عيينة: أظن أن قد علم الله أنه سيكون لك حديث لن تنساه يا بني فزارة هكذا - وأشار تحت الشمس - انصرفوا. هذا والله كذاب. ما بورك لنا ولا له فيما يطلب. فانصرفت فزارة وذهب عيينة وأخوه في آثارهما. فأدرك عيينة فأسر. وأفلت أخوه.", 267, 482], ["أسر عيينة بن حصن", "فقال عيينة: أظن أن قد علم الله أنه سيكون لك حديث لن تنساه يا بني فزارة هكذا - وأشار تحت الشمس - انصرفوا. هذا والله كذاب. ما بورك لنا ولا له فيما يطلب. فانصرفت فزارة وذهب عيينة وأخوه في آثارهما. فأدرك عيينة فأسر. وأفلت أخوه.", 267, 483], ["هرب طليحة إلى الشام", "ماذا تأمرنا؟ وقد كان أعد فرسه وهيأ امرأته. فوثب على فرسه وحمل امرأته وراءه. ثم ولى هاربا. وقال: من استطاع منكم أن يفعل هكذا فليفعل ثم هرب حتى قدم الشام.", 268, 484], ["قتل طليحة عكاشة وثابت بن أقرم", "ولما ولى طليحة هاربا، تبعه عكاشة بن محصن وثابت بن أقرم. وكان طليحة قد أعطى الله عهدا: أن لا يسأله أحد النزول إلا فعل. فلما أدبر ناداه عكاشة بن محصن يا طليحة، فعطف عليه فقتل عكاشة ثم أدركه ثابت فقتله أيضا طليحة، ثم لحق المسلمون أصحاب طليحة فقتلوا وأسروا. وصاح خالد لا يطبخن رجل قدرا، ولا يسخنن ماء إلا وأثفيته رأس رجل (1) .", 268, 485], ["تأمين خالد بني أسد", "وتلطف رجل من بني أسد حتى وثب على عجز راحلة خالد، فقال: أنشدك الله أن لا يكون هلاك مضر على يدك، يا خالد حكمك في بني أسد. فنادى خالد: من قام فهو آمن. فقام الناس كلهم.", 269, 486], ["إعلان بني عامر الإسلام", "وسمعت بذلك بنو عامر. فأعلنوا الإسلام.", 269, 487], ["تحريق الأسرى في الحظائر", "وأمر خالد بالحظائر أن تبنى، ثم أوقد فيها النار. ثم أمر بالأسرى فألقيت فيها. وألقي فيها يومئذ حامية بن سبيع الذي استعمله رسول الله صلى الله عليه وسلم على صدقات قومه.", 269, 488], ["أخذ أم طليحة", "وأخذت أم طليحة فعرض عليها الإسلام، فوثبت. وأخذت فحمة من النار وهي تقول: يا موت عم صباحا، كافحته كفاحا، إذ لم أجد براحا.", 269, 489], ["رجوع بني عامر وغيرهم إلى الإسلام", "ولما أوقع الله ببني أسد وفزارة ما أوقع ببزاخة بث خالد السرايا، ليصيبوا من قدروا عليه ممن هو على ردته. وجعلت العرب تسير إلى خالد، رغبة في الإسلام وخوفا من السيف.", 269, 490], ["تأمين عامر وغطفان عند أجا وسلمى", "ثم عمد خالد إلى جبلي طيء - أجا وسلمى - فأتته عامر وغطفان يدخلون الإسلام ويسألونه الأمان على مياههم وبلادهم. وأظهروا التوبة. وأقاموا الصلاة. وأقروا بالزكاة.", 270, 491], ["بعث عيينة موثقا إلى أبي بكر", "وبعث بعيينة إلى أبي بكر مجموعة يداه في وثاقه فجعل غلمان المدينة ينخسونه بالجريد، ويضربونه. ويقولون: أي عدو الله أكفرت بالله بعد إيمانك؟ فيقول والله ما كنت آمنت بالله قط.", 270, 492], ["وفد أسد وغطفان على أبي بكر", "وحدث يزيد بن أبي شريك الفزاري عن أبيه قال: قدمت مع أسد وغطفان على أبي بكر وافدا، حين فرغ خالد منهم. فقال أبو بكر: \" اختاروا بين خصلتين حرب مجلية أو سلم مخزية. فقال خارجة بن حصن: هذه الحرب المجلية قد عرفناها، فما السلم المخزية؟ قال: تشهدون أن قتلانا في الجنة وقتلاكم في النار. وأن تردوا علينا ما أخذتم منا، ولا نرد عليكم ما أخذنا منكم. وأن تدوا قتلانا، كل قتيل مائة بعير منها أربعون في بطونها أولادها. ولا ندي قتلاكم. ونأخذ منكم الحلقة والكراع وتلحقون بأذناب الإبل حتى يرى الله خليفة نبيه والمؤمنين ما شاء فيكم، أو يرى منكم إقبالا لما خرجتم منه.", 270, 493], ["رد عمر الحلقة والكراع إلى أهلها", "فلما توفي رأى عمر أن الإسلام قد ضرب بجرانه. فدفعه إلى أهله وإلى ورثة من مات منهم.", 271, 494], ["مسير خالد إلى اليمامة", "فلما فرغ خالد من بزاخة وبني عامر أظهر أن أبا بكر عهد إليه أن يسير إلى أرض بني تميم، وإلى اليمامة، فقال ثابت بن قيس - وهو على الأنصار، وخالد على جماعة المسلمين - ما عهد إلينا ذلك وليس بنا قوة. وقد كل المسلمون وعجف كراعهم. فقال خالد: لا أستكره أحدا، وسار بمن تبعه.", 271, 495], ["لحاق الأنصار بخالد", "وأقامت الأنصار يوما أو يومين ثم تلاومت فيما بينها. وقالت والله ما صنعنا شيئا. والله لئن أصيب القوم ليقولن خذلتموهم وإنها لمسبة عارها باق إلى آخر الدهر ولئن أصابوا فتحا، إنه لخير منعتموه. فابعثوا إلى خالد يقيم حتى تلحقوه. فبعثوا إليه فأقام حتى لحقوه. فاستقبلهم في كثرة من المسلمين حتى نزلوا.", 272, 496], ["منع مالك بن نويرة الصدقة", "وساروا جميعا حتى انتهوا إلى البطاح، من أرض بني تميم فلم يجدوا بها جمعا. ففرق خالد السرايا في نواحيها. فأتت سرية منهم بني حنظلة - وسيدهم مالك بن نويرة - وكان قد بعثه النبي صلى الله عليه وسلم مصدقا على قومه. فجمع صدقاتهم. فلما بلغته وفاة النبي صلى الله عليه وسلم جفل إبل الصدقة - أي ردها إلى أهلها فلذلك سمي الجفول - وجمع قومه فقال: إن هذا الرجل قد هلك فإن قام قائم بعده رضي منكم أن تدخلوا في أمره ولم يطلب ما مضى، ولم تكونوا أعطيتم الناس أموالكم. فتسارع إليه جمهورهم.", 272, 497], ["أخذ السرية قوم مالك بن نويرة", "فلما وصلتهم السرية - مع طلوع الشمس - فزعوا إلى السلاح. وقالوا: من أنتم؟ قالوا: نحن عباد الله المسلمون قالوا: ونحن عباد الله المسلمون. قالوا: فضعوا السلاح. ففعلوا. فأخذوهم. وجاءوا بهم إلى خالد.", 273, 498], ["قتل مالك بن نويرة وقومه", "فقال له أبو قتادة: - وهو مع السرية - أقاتل أنت هؤلاء؟ قال: نعم. قال: إنهم اتقونا بالإسلام أذنا فأذنوا، وصلينا فصلوا. وكان من عهد أبي بكر \" أيما دار غشيتموها فسمعتم الأذان فيها بالصلاة فأمسكوا عن أهلها حتى تسألوهم ماذا نقموا؟ وماذا يبغون؟ وإن لم تسمعوا الأذان فشنوا عليها الغارة فاقتلوا وحرقوا \". فأمر بهم خالد فقتلوا، وأمر برأس مالك فجعل أثفية للقدر ورثاه أخوه متمم بقصائد كثيرة (1) .", 273, 499], ["وفد بني حنيفة ومعهم مسيلمة", "عن رافع بن خديج قال: \" قدمت على النبي صلى الله عليه وسلم وفود العرب، فلم يقدم علينا وفد أقسى قلوبا، ولا أحرى أن لا يكون الإسلام يقر في قلوبهم - من بني حنيفة وكان مسيلمة مع الوفد \".", 274, 500], ["دعوى مسيلمة الشركة في النبوة وكتابه", "فلما انصرفوا إلى اليمامة ادعى أن النبي صلى الله عليه وسلم أشركه في النبوة، وكتب إليه: من مسيلمة رسول الله إلى محمد رسول الله، أما بعد فإني أشركت في الأمر معك وإنا لنا نصف الأرض ولقريش نصفها، ولكن قريش قوم يعتدون. فكتب إليه رسول الله صلى الله عليه وسلم.", 274, 501], ["ردة أهل اليمامة مع مسيلمة", "وجد بعدو الله ضلاله بعد وفاة رسول الله صلى الله عليه وسلم. وأصفقت معه بنو حنيفة على ذلك، إلا أفذاذا من ذوي عقولهم.", 274, 502], ["شهادة الرجال بن عنفوة لمسيلمة", "وكان من أعظم ما فتن به قومه شهادة الرجال بن عنفوة له بإشراك النبي صلى الله عليه وسلم إياه في الأمر. وكان الرجال من الوفد الذين قدموا على النبي صلى الله عليه وسلم. فقرأ القرآن وتعلم السنن. قال ابن عمر: \" وكان من أفضل الوفد عندنا، فكان أعظم فتنة على أهل اليمامة من غيره لما كان يعرف به \".", 274, 503], ["لحاق ابن عمر اليشكري بخالد", "فبلغ ذلك مسيلمة ومحكم وأشرافهم فطلبوه ففاتهم. ولحق بخالد. فأخبره بحالهم. ودله على عوراتهم.", 275, 504], ["بئر بني حنيفة وبصاق مسيلمة", "وحفرت بنو حنيفة بئرا فاستعذبوها، فأتوا مسيلمة. وطلبوا أن يبارك فيها، فبصق فيها فعادت ملحا أجاجا.", 276, 505], ["قدوم بعض أسد وغطفان على أبي بكر يطلبون البيعة", "وكان الصديق رضي الله عنه قد عهد إلى خالد - إذا فرغ من أسد وغطفان والضاحية - أن يقصد اليمامة، وأكد عليه في ذلك. فلما أظفر الله خالدا بهم تسلل بعضهم إلى المدينة، يسألون أبا بكر أن يبايعهم على الإسلام. فقال بيعتي إياكم وأماني لكم أن تلحقوا بخالد. فمن كتب إلى خالد أنه حضر معه اليمامة فهو آمن. وليبلغ شاهدكم غائبكم. ولا تقدموا علي.", 276, 506], ["كتاب أبي بكر إلى خالد مع شريك الفزاري", "قال شريك الفزاري كنت ممن شهد بزاخة مع عيينة بن حصن. ثم رزقني الله الإنابة فجئت أبا بكر. فأمرني بالمسير إلى خالد. وكتب معي إليه.", 277, 507], ["حيرة أهل اليمامة بمسير خالد", "ولما اتصل بأهل اليمامة مسير خالد إليهم بعد الذي صنع بأمثالهم، حيرهم ذلك. وجزع له محكم بن طفيل سيدهم. وهم أن يرجع إلى الإسلام. ثم استمر على ضلالته. وكان صديقا لزياد بن لبيد الأنصاري.", 277, 508], ["إنذار عمير بن ضابئ أهل اليمامة", "ثم خطبهم فقال إنكم تلقون قوما يبذلون أنفسهم دون صاحبهم فابذلوا نفوسكم دون صاحبكم. وكان عمير بن ضابئ في أصحاب خالد. ولم يكن من أهل حجر كان من أهل ملهم (1) . فقال له خالد: تقدم إلى قومك فاكسرهم.", 278, 509], ["خطبة ثمامة بن أثال في بني حنيفة", "وقام ثمامة بن أثال فيهم. فقال: \" اسمعوا مني وأطيعوا أمري، ترشدوا. إنه لا يجتمع نبيان بأمر واحد. إن محمدا لا نبي بعده ولا نبي يرسل معه. ثم قرأ: بسم الله الرحمن الرحيم {حم - تنزيل الكتاب من الله العزيز العليم - غافر الذنب وقابل التوب شديد العقاب ذي الطول لا إله إلا هو إليه المصير} [غافر: 1 - 3] (1) هذا كلام الله عز وجل. أين هذا من: يا ضفدع يا ضفدعين. نقي كم تنقين؟ نصفك في الماء ونصفك في الطين. لا الشراب تمنعين ولا الماء تكدرين ولا الطين تفارقين. لنا نصف الأرض ولقريش نصفها. ولكن قريشا قوم يعتدون. والله إنكم لترون هذا ما يخرج من إل (2) . وقد استحق محمد أمرا أذكره به خرجت معترا، فأخذتني رسله في غير عهد ولا ذمة. فعفا عن دمي. فأسلمت وأذن لي في الخروج إلى بيت الله. فتوفي رسول الله صلى الله عليه وسلم، وقام بهذا الأمر رجل من بعده هو أفقههم في أنفسهم. لا تأخذه في الله لومة لائم. ثم بعث إليكم رجلا، لا يسمى باسمه. ولا باسم أبيه يقال له: \" سيف الله \" معه سيوف الله كثيرة، فانظروا في أمركم \".", 279, 510], ["تقديم خالد الطلائع من البطاح", "لما سار خالد من البطاح، وجاء أرض بني تميم قدم مائتي فارس عليهم معن بن عدي. وقدم عينين له أمامه.", 280, 511], ["أسر مجاعة بن مرارة وقتل أصحابه", "فانطلقوا. فأخذوا مجاعة بن مرارة في ثلاثة وعشرين رجلا من قومه خرجوا في طلب رجل أصاب فيهم دما، وهم لا يشعرون بإقبال خالد. فسألوهم ممن أنتم؟ فقالوا: من بني حنيفة. فقالوا: ما تقولون في صاحبكم؟ فشهدوا أنه رسول الله. فقالوا لمجاعة ما تقول أنت؟ فقال ما كنت أقر بمسيلمة. وقد قدمت على رسول الله صلى الله عليه وسلم فأسلمت. وما غيرت ولا بدلت. فضرب خالد أعناقهم. حتى إذا بقي سارية بن عامر قال: يا خالد إن كنت تريد بأهل اليمامة خيرا أو شرا، فاستبق مجاعة. وكان مجاعة شريفا، فلم يقتله. وترك أيضا سارية. وأمر بهما فأوثقا في جوامع من حديد.", 280, 512], ["حبس مجاعة عند أم متمم", "فقال خالد: إن بين القتل والترك منزلة وهي الحبس حتى يقضي الله في حربنا ما هو قاض. ودفعه إلى أم متمم زوجته. وأمرها أن تحسن إساره. فظن مجاعة أن خالدا يريد حبسه لأجل أن يخبره عن عدوه ويشير عليه.", 281, 513], ["نزول خالد عقرباء", "قال عبيد الله بن عبد الله: لما أشرف خالد، وأجمع أن ينزل عقرباء، ودفع الطلائع أمامه، فرجعوا إليه. فأخبروه أن مسيلمة ومن معه قد نزلوا عقرباء فشاور أصحابه أن يمضي إلى اليمامة، أو ينتهي إلى عقرباء. فأجمعوا أن ينتهي إلى عقرباء. فزحف خالد بالمسلمين إليها. وكان المسلمون يسألون عن الرجال بن عنفوة فإذا الرجال على مقدمة مسيلمة فلعنوه وشتموه.", 282, 514], ["وقعة اليمامة", "فلما فرغ خالد من ضرب عسكره - وبنو حنيفة تسوي صفوفها - نهض خالد إلى صفوفه فصفها. وقدم رايته مع زيد بن الخطاب، ودفع راية الأنصار إلى ثابت بن قيس بن شماس. فتقدم بها.", 283, 515], ["مقتل زيد بن الخطاب", "واستحر القتل في المسلمين وحملة القرآن حتى فنوا إلا قليلا. وهزم كل من الفريقين حتى دخل المسلمون عسكر المشركين والمشركون عسكر المسلمين مرارا. وجعل زيد بن الخطاب - ومعه الراية - يقول اللهم إني أبرأ إليك مما جاء به مسيلمة. وأعتذر إليك من فرار أصحابي. وجعل يشتد بالراية في نحور العدو. ثم ضارب بسيفه حثى قتل. رحمه الله ورضي عنه.", 283, 516], ["مقتل سالم مولى أبي حذيفة وأبي حذيفة", "ولقد كان الناس يتفرقون في كل وجه وإن سالما وثابتا لقائمان حتى قتل سالم وقتل أبو حذيفة مولاه.", 284, 517], ["مقتل محكم بن الطفيل ودخول الحديقة", "ثم قال: خلوا بيننا وبينهم أخلصونا. فأخلصت الأنصار. فلم تكن لهم ناهية حتى انتهوا إلى محكم بن طفيل فقتلوه. ثم انتهوا إلى الحديقة فدخلوها، فقاتلوا أشد القتال حتى اختلطوا فيها.", 284, 518], ["حملة عباد بن بشر وفتح الحديقة", "وأوفى عباد بن بشر على نشز. فصاح بأعلى صوته: أنا عباد بن بشر يا للأنصار. أنا عباد، إلي إلي. فأجابوا لبيك لبيك حتى توافوا عنده. فقال فداكم أبي وأمي، حطموا جفون السيوف. ثم حطم جفن سيفه فألقاه. وحطمت الأنصار جفون سيوفها. ثم قال: حملة صادقة اتبعوني. فخرج أمامهم حتى ساقوا بني حنيفة منهزمين، حتى انتهوا إلى الحديقة فأغلق عليهم. ثم إن الله فتح الحديقة فاقتحم عليهم المسلمون.", 285, 519], ["انقطاع الحرب بعد العصر", "وعن أبي سعيد الخدري رضي الله عنه قال: \" دخلنا الحديقة حين جاء وقت الظهر واستحر القتل، فأمر خالد المؤذن فأذن على جدار الحديقة بالظهر. والقوم مقبلون على القتل حتى انقطعت الحرب بعد العصر. فصلى بنا خالد الظهر والعصر.", 285, 520], ["الوقوف على مسيلمة قتيلا", "فلما أصبحوا أمر خالد، فسيق مجاعة في الحديد يعرفهم القتلى فمر برجل وسيم، فقال: يا مجاعة أهو هذا؟ قال هذا أكرم منه هذا محكم بن الطفيل. إن الذي تبتغون لرجل أصيفر أخينس. فوجدوه، فوقف عليه خالد. فحمد الله كثيرا، وأمر به فألقي في البئر التي كان يشرب منها.", 286, 521], ["صلح خالد مع بني حنيفة بخدعة مجاعة", "فقال مجاعة: إني لك ناصح. وإن السيف قد أفناك. فتعال أصالحك على قومي. وقد أخل بخالد مصاب أهل السابقة ومن كان يعرف عنده الغناء. فقد رق وأحب الموادعة مع عجف الكراع.", 286, 522], ["تمام الصلح وكتاب أبي بكر يقطر الدم", "فبينما هم على ذلك إذ جاء كتاب أبي بكر يقطر الدم وفيه \" إن أظفرك الله بهم فلا تستبق رجلا مرت عليه الموسى \".", 287, 523], ["تاريخ وقعة اليمامة وقتلى بني حنيفة", "وكانت وقعة اليمامة في ربيع الأول سنة اثنتي عشرة.", 288, 524], ["ردة بني سليم وانتهاب اللطيمة", "ذكر ردة بني سليم ذكر الواقدي - من حديث سفيان بن أبي العرجاء السلمي. وكان عالما بردة قومه - قال: أهدى ملك من ملوك غسان إلى النبي صلى الله عليه وسلم لطيمة فيها مسك وعنبر وخيل. فخرجت بها الرسل حتى إذا كانت بأرض بني سليم بلغتهم وفاة النبي صلى الله عليه وسلم. فتشجع بعض بني سليم على أخذها والردة وأبى بعضهم من ذلك وقال إن كان محمد قد مات، فإن الله حي لا يموت. فانتهب الذين ارتدوا منهم اللطيمة.", 288, 525], ["استعمال معن بن حاجر على مسلمي بني سليم", "فلما ولي أبو بكر رضي الله عنه كتب إلى معن بن حاجر فاستعمله على من أسلم من بني سليم. وكان قد قام في ذلك قياما حسنا، ذكر وفاة رسول الله صلى الله عليه وسلم، وذكر الناس ما قال الله لنبيه: {إنك ميت وإنهم ميتون} [الزمر: 30] (1) وقال: {وما محمد إلا رسول قد خلت من قبله الرسل} [آل عمران: 144] (2) مع آي من كتاب الله. فاجتمع إليه بشر من بني سليم. وانحاز أهل الردة منهم فجعلوا يغيرون على الناس.", 289, 526], ["لحاق معن بخالد واستخلاف طريفة", "فلما بدا لأبي بكر أن يوجه خالدا، كتب إلى معن أن يلحق بخالد، ويستعمل على عمله أخاه طريفة بن حاجر ففعل. وأقام طريفة يكالب من ارتد بمن معه من المسلمين إذ قدم الفجاءة - واسمه إياس بن عبد الله بن عبد ياليل - على أبي بكر. فقال: إني مسلم وقد أردت جهاد من ارتد فاحملني، فلو كان عندي قوة لم أقدم عليك.", 289, 527], ["قتل الفجاءة وتحريقه", "فلما بدا لأبي بكر أن يوجه خالدا، كتب إلى معن أن يلحق بخالد، ويستعمل على عمله أخاه طريفة بن حاجر ففعل. وأقام طريفة يكالب من ارتد بمن معه من المسلمين إذ قدم الفجاءة - واسمه إياس بن عبد الله بن عبد ياليل - على أبي بكر. فقال: إني مسلم وقد أردت جهاد من ارتد فاحملني، فلو كان عندي قوة لم أقدم عليك.", 289, 528], ["أسر الفجاءة وتحريقه بالنار", "فقرأ طريفة الكتاب على قومه. فحشدوا إلى الفجاءة. فقدم عليه ابن المثنى، فقتل نجبة وهرب منه إلى الفجاءة. ثم زحف طريفة إلى الفجاءة فتصادما. فلما رأى الفجاءة الخلل في أصحابه قال: يا طريفة والله ما كفرت. وإني لمسلم. وما أنت بأولى بأبي بكر مني، أنت أميره وأنا أميره. قال طريفة: إن كنت صادقا فألق السلاح، ثم انطلق إلى أبي بكر فأخبره خبرك، فوضع السلاح فأوثقه طريفة في جامعة، فقال: لا تفعل، فقال طريفة: هذا كتاب أبي بكر إلي، فقال الفجاءة: سمعا وطاعة، فبعث به في جامعته مع عشرة من بني سليم. فأرسل به أبو بكر إلى بني جشم فحرقته بالنار (1) .", 290, 529], ["مقتل قبيصة على يد حميضة", "وقدم على أبي بكر - رضي الله عنه - قبيصة - أحد بني الظربان - فذكر أنه مسلم. ولم يرتد فأمره أن يقاتل بمن معه من ارتد فرجع قبيصة. فاجتمع إليه ناس كثير. فخرج يتبع بهم أهل الردة، يقتلهم حيث وجدهم حتى مر ببيت حميضة بن الحكم الشريدي. فوجده غائبا يجمع أهل الردة. ووجد جارا له مرتدا. فقتله واستاق ماله.", 290, 530], ["كتاب أبي بكر إلى خالد في بني سليم", "وكتب أبو بكر رضي الله عنه إلى خالد: \" إن أظفرك الله ببني حنيفة فأقل اللبث فيهم، حتى تنحدر إلى بني سليم، فتطأهم وطأة يعرفون بها ما منعوا. فإنه ليس بطن من العرب أنا أغيظ عليه مني عليهم، فإن أظفرك الله بهم فلا آلوك فيهم أن تحرقهم بالنار وهول فيهم القتل حتى يكون نكالا لهم \" (1) .", 291, 531], ["قتال خالد بني سليم", "وسمعت بنو سليم بإقبال خالد. فاجتمع منهم بشر كثير. واستجلبوا من بقي من العرب، مرتدا وكان الذي جمعهم أبو شجرة بن عبد العزى فانتهى خالد إلى جمعهم مع الصبح. فصاح خالد في أصحابه وأمرهم بلبس السلاح. ثم صفهم. وصفت بنو سليم. وقد كل المسلمون وعجف كراعهم وخفهم. وجعل خالد يلي القتال بنفسه حتى أثخن فيهم القتل. ثم حمل عليهم حملة واحدة، فانهزموا. وأسر منهم بشر كثير. ثم حظر لهم الحظائر وحرقهم فيها.", 291, 532], ["إسلام أبي شجرة", "فرويت رمحي من كتيبة خالد وإني لأرجو بعدها أن أعمرا ثم أسلم، وجعل يعتذر. ويجحد أن يكون قال البيت المتقدم.", 291, 533], ["قدوم أبي شجرة على عمر", "فلما كان زمن عمر رضي الله عنه قدم المدينة، وأناخ راحلته بصعيد بني قريظة ثم أتى عمر - وهو يقسم بين الفقراء - فقال يا أمير المؤمنين أعطني. فإني ذو حاجة. فقال من أنت؟ قال أنا أبو شجرة. قال يا عدو الله ألست الذي تقول: فرويت رمحي - البيت؟ عمر سوء. والله ما عشت لك يا خبيث. ثم جعل يعلوه بالدرة على رأسه حتى سبقه عدوا، وعمر في طلبه حتى أتى راحلته فارتحلها. ثم اشتد بها في حرة شوران فما استطاع أن يقرب عمر حتى توفي.", 291, 534], ["ردة أهل البحرين", "قال عيسى بن طلحة: لما ارتدت العرب - بعد وفاة رسول الله صلى الله عليه وسلم - قال كسرى: من يكفيني أمر العرب؟ فقد مات صاحبهم وهم الآن يختلفون بينهم إلا أن يريد الله بقاء ملكهم فيجتمعون على أفضلهم.", 292, 535], ["أخذ كسرى ستمائة من بكر بن وائل", "فأرسل إليهم. وأخذ منهم ستمائة الأشرف فالأشرف.", 292, 536], ["ردة أهل هجر وثبات عبد القيس بالجارود", "وارتد أهل هجر عن الإسلام. فقام الجارود بن المعلى في قومه فقال:", 292, 537], ["خروج أبان بن سعيد من البحرين", "فقالوا: لا تفعل فأنت أعز الناس علينا، وهذا علينا وعليك فيه مقالة يقال: فر من القتال. فأبى. وانطلق في ثلاثمائة رجل يبلغونه المدينة.", 293, 538], ["بعث العلاء بن الحضرمي إلى البحرين", "فدعا أبو بكر العلاء بن الحضرمي. فبعثه إلى البحرين في ستة عشر راكبا، وقال امض فإن أمامك عبد القيس فسار. ومر بثمامة بن أثال فأمده برجال من قومه بني سحيم ثم لحق به.", 293, 539], ["قتال العلاء بكر بن وائل بالمشقر", "فنزل العلاء بحصن يقال له جواثا، وكان مخارق قد نزل بمن معه من بكر ابن وائل حصن المشقر - حصن عظيم لعبد القيس - فسار إليهم العلاء، فيمن اجتمع إليه. فقاتلهم قتالا شديدا، حتى كثر القتلى في الفريقين والجارود بن المعلى بالخط (1) يبعث البعوث إلى العلاء.", 293, 540], ["حصار العلاء بجواثي", "وسار الحطم وأبجر العجلي حتى حصروا العلاء بجواثا. فقال عبد الله بن حذف، وكان من صالحي المسلمين:", 294, 541], ["تبييت المسلمين عسكر الحطم", "فمكثوا على ذلك محصورين فسمع العلاء وأصحابه ذات ليلة لغطا في العسكر فقالوا: لو علمنا أمرهم؟ فقال عبد الله بن حذف: أنا أعلم لكم علمهم فدلوه بحبل. فأقبل حتى يدخل على أبجر العجلي - وأمه منهم - قال ما جاء بك؟ لا أنعم الله بك عينا.", 294, 542], ["مقتل الحطم وأبجر العجلي", "ووثب الحطم فوضع رجله في الركابات وجعل يقول: من يحملني؟ فسمعه عبد الله (1) بن حذف. فأقبل يقول: أبا ضبيعة؟ قال: نعم. قال: أنا أحملك، فلما دنا منه قتله. وقطعت رجل أبجر العجلي. فمات منها.", 295, 543], ["قتال دارين وصلح أهلها", "ثم سار العلاء إلى مدينة دارين فقاتلهم قتالا شديدا، وضيق عليهم. فلما رأى ذلك مخارق ومن معه قالوا: إن خلوا عنا رجعنا من حيث جئنا.", 295, 544], ["العلاء يخوض البحر إلى دارين", "ثم سار العلاء إلى الخط، حتى نزل إلى الساحل فجاءه نصراني فقال ما لي إن دللتك على مخاضة تخوض منها الخيل إلى دارين؟ قال وما تسألني؟ قال أهل بيت بدارين قال. هم لك.", 296, 545], ["صلح أهل الردة من البحرين", "ولما رأى ذلك أهل الردة من أهل البحرين، صالحوا على ما صالح عليه أهل هجر.", 296, 546], ["وفد عبد القيس إلى أبي بكر", "ولما ظهر العلاء على أهل الردة والمجوس: بعث رجالا من عبد القيس إلى أبي بكر رضي الله عنه. فنزلوا على طلحة والزبير رضي الله عنهما. وأخبروهما بقيامهم في أهل الردة. ثم دخلوا على أبي بكر وحضر طلحة والزبير. فقالوا: يا خليفة رسول الله، إنا قوم أهل إسلام. وليس شيء أحب إلينا من رضاك. ونحن نحب أن تعطينا أرضا من البحر وطواحين.", 296, 547], ["عمر يمحو كتاب الإقطاع", "فانطلقوا بالكتاب إلى عمر رضي الله عنه. فلما قرأه: تفل في الكتاب ومحاه.", 297, 548], ["ردة أهل دبا وأزد عمان", "فلما توفي رسول الله صلى الله عليه وسلم منعوا الصدقة وارتدوا. فدعاهم حذيفة إلى التوبة. فأبوا. وجعلوا يرتجزون:", 298, 549], ["مسير عكرمة إلى أهل دبا", "فسار عكرمة في نحو ألفين من المسلمين. وكان رأس أهل الردة: لقيط بن مالك الأزدي فلما بلغه مسير عكرمة، بعث ألف رجل من الأزد يلقونه. وبلغ عكرمة: أنهم جموع كثيرة. فبعث طليعة. وكان للعدو أيضا طليعة. فالتقت الطليعتان. فتناوشوا ساعة ثم انكشف أصحاب لقيط. وقتل منهم نحو مائة رجل. وبعث أصحاب عكرمة فارسا بخبره. فأسرع عكرمة حتى لحق طليعته. ثم زحفوا جميعا. وسار على تعبئة حتى أدرك القوم. فاقتتلوا ساعة. ثم هزمهم عكرمة، وأكثر فيهم القتل. ورجع فلهم إلى لقيط بن مالك، فأخبروه أن عكرمة مقبل.", 298, 550], ["هزيمة أهل دبا وحصارهم", "فقوي جانب حذيفة ومن معه من المسلمين فناهضهم. وجاء عكرمة. فقاتل معهم. فانهزم العدو حتى دخلوا مدينة دبا. فحصرهم المسلمون شهرا. وشق عليهم الحصار إذ لم يكونوا قد أخذوا له أهبة.", 299, 551], ["نزول أهل دبا على حكم حذيفة", "فأرسلوا إلى حذيفة. يسألونه الصلح. فقال: لا، إلا بين حرب مجلية أو سلم مخزية. قالوا: أما الحرب المجلية، فقد عرفناها، فما السلم المخزية؟ قال: تشهدون أن قتلانا في الجنة وقتلاكم في النار، وأن كل ما أخذناه منكم فهو لنا، وما أخذتموه فهو رد لنا. وأنا على حق وأنتم على باطل وكفر، ونحكم فيكم بما رأينا. فأقروا بذلك.", 299, 552], ["قدوم حذيفة بسبي دبا المدينة", "وقدم حذيفة بسبيهم المدينة. وهم ثلاثمائة من المقاتلة وأربعمائة من الذرية والنساء.", 300, 553], ["عمر يطلق سبي دبا", "فلم يزالوا موقوفين في دار رملة حتى مات أبو بكر. فدعاهم عمر، فقال: انطلقوا إلى أي بلاد شئتم. فأنتم قوم أحرار.", 300, 554], ["مسير خالد إلى العراق", "ولما دخلت السنة الثانية من خلافة أبي بكر رضي الله عنه وهي سنة اثني عشر من الهجرة كتب إلى خالد: \" إذا فرغت من اليمامة فسر إلى العراق، فقد وليتك حرب فارس \".", 301, 556], ["هزيمة الفرس وصلحهم مع خالد", "فسار إليه في بضعة وثلاثين ألفا. فصالح أهل السواد. ثم سار إلى الأبلة. وخرج كسرى في مائة وعشرين ألفا. فالتقى مع خالد فهزم الله المشركين من الفرس. وكتب خالد إلى كسرى: \" أما بعد، فأسلموا تسلموا، وإلا فأدوا الجزية وإلا فقد جئتكم بقوم يحبون الموت كما تحبون الحياة \" فصالحوه.", 301, 557], ["حج أبي بكر بالناس", "وفيها حج أبو بكر رضي الله عنه بالناس ثم رجع إلى المدينة.", 301, 558], ["بعث الجنود إلى الشام", "فبعث أبو بكر رضي الله عنه الجنود إلى الشام. وأمر عليهم يزيد بن أبي سفيان وأبا عبيدة عامر بن الجراح، وشرحبيل بن حسنة وعمرو بن العاص. ونزلت الروم بأعلى فلسطين في سبعين ألفا.", 301, 560], ["أمر خالد بإمداد أهل الشام", "فكتبوا إلى أبي بكر يخبرونه ويستمدونه. فأمر خالدا - وهو بالحيرة - أن يمد أهل الشام بمن معه من أهل القوة ويستخلف على ضعفة الناس رجلا منهم.", 301, 561], ["فتح بصرى", "وسار حتى وصل إلى الشام، ففتحوا بصرى. وهي أول مدينة فتحت.", 302, 562], ["وقعة أجنادين", "ثم اجتمع المشركون من الروم، فانحاز المسلمون إلى أجنادين، فكانت الوقعة المشهورة وكان النصر للمسلمين.", 302, 563], ["موت الصديق رضي الله عنه", "وفي هذه السنة مات الصديق، ليلة الثلاثاء لسبع عشرة ليلة مضت من جمادى الآخرة.", 302, 564], ["استخلاف عمر بن الخطاب", "واستخلف على الناس عمر بن الخطاب. وقال: \" اللهم إني وليتهم خيرهم ولم أرد بذلك إلا إصلاحهم، ولم أرد محاباة عمر. فاخلفني فيهم. فهم عبادك، ونواصيهم بيدك، أصلح لهم واليهم واجعله من خلفائك الراشدين يتبع هدي نبيه صلى الله عليه وسلم. وأصلح له رعيته \".", 302, 565], ["بيعة أمراء الأجناد لعمر", "ولما ورد كتاب أبي بكر رضي الله عنه إلى أمراء الأجناد باستخلاف عمر بايعوه.", 303, 566], ["وقعة فحل", "ثم ساروا إلى \" فحل \" بناحية الأردن. وقد اجتمع بها الروم. فكانت وقعة \" فحل \" المشهورة ونصر الله المسلمين. وانحاز المشركون إلى دمشق.", 303, 567], ["المسير إلى دمشق وعزل خالد", "وفيها: ساروا إلى دمشق وعليهم خالد. فأتى كتاب عمر رضي الله عنه بعزل خالد وتأمير أبي عبيدة بن الجراح.", 303, 569], ["أمر عمر بصلاة التراويح جماعة", "وفيها: أمر عمر بصلاة التراويح جماعة وقدم جرير بن عبد الله في ركب من بجيلة، فأشار عليه عمر بالخروج إلى العراق، فسار بهم جرير إلى العراق. فلما قرب من المثنى بن حارثة كتب إليه: \" أقبل فإنما أنت مدد لي \".", 303, 570], ["مسير جرير بن عبد الله إلى العراق", "وفيها: أمر عمر بصلاة التراويح جماعة وقدم جرير بن عبد الله في ركب من بجيلة، فأشار عليه عمر بالخروج إلى العراق، فسار بهم جرير إلى العراق. فلما قرب من المثنى بن حارثة كتب إليه: \" أقبل فإنما أنت مدد لي \".", 303, 571], ["وقعة البويب", "فقال جرير: أنت أمير وأنا أمير. ثم اجتمعا. فكانت وقعة البويب المشهورة.", 303, 572], ["تأمير سعد بن أبي وقاص على العراق", "ثم إن عمر أمر سعد بن أبي وقاص رضي الله عنه على العراق، وكتب له وأوصاه فقال: \" يا سعد بن وهيب لا يغرنك من الله أن قيل خال رسول الله صلى الله عليه وسلم وصاحبه. فإن الله لا يمحو السيئ بالسيئ ولكن يمحو السيئ بالحسن. وإن الله ليس بينه وبين أحد نسب إلا بطاعته. فالناس شريفهم ووضيعهم في ذات الله سواء. الله ربهم وهم عباده. يتفاضلون بالعافية. ويدركون ما عند الله بالطاعة. فانظر الأمر الذي رأيت عليه رسول الله صلى الله عليه وسلم منذ بعث إلى أن فارقنا. فالزمه. فإنه الأمر \" وكتب إلى المثنى وجرير: أن يجتمعا إليه، فسار سعد بمن معه. فنزل بشراف واجتمع إليه الناس.", 303, 573], ["نزول سعد بشراف", "ثم إن عمر أمر سعد بن أبي وقاص رضي الله عنه على العراق، وكتب له وأوصاه فقال: \" يا سعد بن وهيب لا يغرنك من الله أن قيل خال رسول الله صلى الله عليه وسلم وصاحبه. فإن الله لا يمحو السيئ بالسيئ ولكن يمحو السيئ بالحسن. وإن الله ليس بينه وبين أحد نسب إلا بطاعته. فالناس شريفهم ووضيعهم في ذات الله سواء. الله ربهم وهم عباده. يتفاضلون بالعافية. ويدركون ما عند الله بالطاعة. فانظر الأمر الذي رأيت عليه رسول الله صلى الله عليه وسلم منذ بعث إلى أن فارقنا. فالزمه. فإنه الأمر \" وكتب إلى المثنى وجرير: أن يجتمعا إليه، فسار سعد بمن معه. فنزل بشراف واجتمع إليه الناس.", 303, 574], ["فتح القادسية", "وسمع بذلك رستم بن الفرخزاد. فخرج بنفسه في مائة وعشرين ألفا، سوى التبع والرقيق حتى نزل القادسية. وبينه وبين المسلمين جسر القادسية، وقيل: كانوا ثلاثمائة ألف ومعهم ثلاثة وثلاثون فيلا. واجتمع المسلمون حتى صاروا ثلاثين ألفا. فكانت وقعة القادسية المشهورة التي نصر الله فيها المسلمين. وهزم المشركين.", 304, 576], ["نزول الكوفة", "فبعث سعد عثمان بن حنيف فارتاد لهم موضع الكوفة اليوم فنزلها سعد بالناس. ثم كتب عمر إلى سعد \" أن ابعث إلى أرض الهند - يريد البصرة - جندا فلينزلوها \".", 304, 577], ["تمصير البصرة", "فبعث إليها عتبة بن غزوان في ثلاثمائة رجل حتى نزلوها. وهو الذي بصر البصرة.", 305, 578], ["وقعة اليرموك", "وفي هذه السنة كانت وقعة اليرموك المشهورة بالشام.", 305, 579], ["صلح نصارى بيت المقدس", "وخرج عمر إلى الشام، ونزل الجابية. فصالح نصارى بيت المقدس - وكانوا قد أبوا أن يجيبوا إلى الصلح مع أبي عبيدة، حتى يكون عمر يعقدون الصلح معه - فصالحهم. واشترط عليهم إجلاء الروم إلى ثلاث. واجتمع إليه أمراء الأجناد.", 305, 580], ["وضع الديوان", "فلما رجع إلى المدينة وضع الديوان. فأعطى العطايا على مقدار السابقة. فبدأ بالعباس حرمة لرسول الله صلى الله عليه وسلم. ثم بالأقرب فالأقرب.", 305, 581], ["كتابة التاريخ من الهجرة", "فيها كتب عمر التاريخ. واستشار الصحابة في مبدئه. فمنهم من قال نبدأ من بدء النبوة. ومنهم من قال من الوفاة، ومنهم من قال من الهجرة. فجعله من الهجرة.", 305, 583], ["فتوح كثيرة شرقا وغربا", "فكان فيها فتوح كثيرة شرقا وغربا.", 305, 585], ["فتح تستر", "وفيها فتحت تستر، التي وجد فيها جسد دانيال عليه السلام. وكان المشركون يستسقون به.", 306, 586], ["زواج عمر أم كلثوم بنت علي", "وفيها: تزوج عمر أم كلثوم بنت علي بن أبي طالب رضي الله عنهم طلبا لصهر رسول الله صلى الله عليه وسلم.", 306, 587], ["عام الرمادة", "فيها: أصاب الناس مجاعة شديدة. وتسمى عام الرمادة لكثرة ما هلك فيها من الناس والبهائم جوعا. فاستسقى عمر بالناس. وسأل العباس أن يدعو الله ويؤمن عمر والناس على دعائه. فأزال الله القحط.", 306, 589], ["استسقاء عمر بالعباس", "فيها: أصاب الناس مجاعة شديدة. وتسمى عام الرمادة لكثرة ما هلك فيها من الناس والبهائم جوعا. فاستسقى عمر بالناس. وسأل العباس أن يدعو الله ويؤمن عمر والناس على دعائه. فأزال الله القحط.", 306, 590], ["طاعون عمواس", "وفيها وقع طاعون عمواس بالشام وقد هلك فيه خمسة وعشرون ألفا. ومات فيه أبو عبيدة عامر بن الجراح ومعاذ بن جبل ويزيد بن أبي سفيان رضي الله عنهم.", 306, 591], ["تأمير معاوية على الشام", "فلما بلغ عمر موتهم أمر على الشام معاوية بن أبي سفيان.", 306, 592], ["فتوح كثيرة شرقا وغربا", "فتح فيها فتوح كثيرة شرقا وغربا.", 306, 594], ["فتح مصر والإسكندرية", "وفيها: فتحت مصر والإسكندرية.", 307, 596], ["إجلاء اليهود من الحجاز", "وفيها: أجلى عمر رضي الله عنه اليهود من الحجاز إلى أذرعات وغيرها.", 307, 597], ["فتح نهاوند", "وفيها كان فتح نهاوند وأميرها النعمان بن مقرن، وقتل يومئذ.", 307, 599], ["موت خالد بن الوليد بحمص", "وفيها: مات خالد بن الوليد رضي الله عنه بحمص.", 307, 600], ["مقتل عمرو بن معدي كرب وطليحة بنهاوند", "وفيها: مات عمرو بن معدي كرب، وطليحة بن خويلد الأسدي - الذي كان تنبأ. ثم أسلم وحسن إسلامه، وأبلى في قتال الفرس بلاء حسنا - قتلا مع النعمان بن مقرن بنهاوند.", 307, 601], ["دخول الأحنف خراسان وهزيمة يزدجرد", "وفيها: دخل الأحنف بن قيس خراسان، وحارب يزدجرد آخر ملوك الفرس. فهزمه الله فيها.", 307, 603], ["اعتمار عمر", "وفيها: اعتمر عمر. فتلقاه نافع بن الحارث - وكان عامله على مكة - فقال له عمر من خلفت؟ قال ابن أبزى، قال عمر: ومن ابن أبزى؟ قال مولى لنا. قال ومولى أيضا؟ قال: إنه قارئ للقرآن عالم بالفرائض. فقال عمر: سمعت رسول الله صلى الله عليه وسلم يقول: «إن الله يرفع بهذا القرآن أقواما ويضع به آخرين» .", 307, 604], ["مقتل عمر رضي الله عنه", "وفيها: قتل عمر رضي الله عنه. في صلاة الصبح من يوم الأربعاء لأربع ليال بقين من ذي الحجة. ودفن يوم الأحد هلال المحرم سنة أربع وعشرين.", 308, 606], ["استخلاف عثمان بن عفان", "فاستخلف فيها عثمان بن عفان رضي الله عنه. لغرة هلال المحرم - أو لثلاث من المحرم - بعد دفن عمر بثلاثة أيام.", 309, 608], ["وفيات", "وفي هذه السنة توفي سراقة بن مالك، وأم الفضل زوجة العباس وأم أيمن بركة مولاة رسول الله صلى الله عليه وسلم. ورضي الله عنهم.", 310, 609], ["وفيات", "فتوفي فيها عبد الله بن أم مكتوم المؤذن، وعمير بن وهب بن خلف الجمحي الذي حزر المسلمين يوم بدر. ثم تعاهد هو وصفوان بن خلف الجمحي على اغتيال رسول الله صلى الله عليه وسلم. فذهب إلى المدينة بدعوى افتداء ابنه وهب الذي كان أسر يوم بدر. فلما دخل على رسول الله صلى الله عليه وسلم قص عليه رسول الله ما تعاهد هو وصفوان عليه. فشهد شهادة الحق وأسلم.", 310, 611], ["غزو عبد الله بن سعد إفريقية", "وفيها غزا عبد الله بن سعد بن أبي سرح إفريقية ومعه العبادلة - عبد الله بن نافع بن قيس، وعبد الله بن نافع بن الحصين وعبد الله بن الزبير - فلقي جرجس ملك البربر في مائتي ألف. فقتل جرجس قتله عبد الله بن الزبير. وفتح الله على المسلمين.", 310, 613], ["موت خارجة بن زيد الأنصاري", "وفيها: مات خارجة بن زيد الأنصاري الذي تكلم بعد الموت. وكان من كلامه: خلت ليلتان. وبقيت أربع، بئر أريس وما بئر أريس؟ .", 310, 614], ["تحويل الساحل إلى جدة", "وفيها اعتمر عثمان فكلمه أهل مكة أن يحول الساحل إلى جدة. وقالوا: هي أقرب إلى مكة وأوسع. وكانوا يرسون قبل ذلك في الشعيبة (1) . فخرج عثمان إلى جدة فرآها، وحول الساحل إليها.", 311, 615], ["فتح إفريقية والأندلس", "وفيها - على قول ابن جرير - كان فتح إفريقية والأندلس على يد عبد الله بن سعد بن أبي سرح.", 311, 617], ["عزل عمرو بن العاص عن مصر", "وفيها: عزل عثمان رضي الله عنه عمرو بن العاص عن مصر، وولى عليها عبد الله بن سعد بن أبي سرح.", 311, 618], ["موت عبد الله بن كعب بن عمرو", "وفيها: مات عبد الله بن كعب بن عمرو رضي الله عنه. وكان من أهل بدر.", 311, 619], ["غزو معاوية البحر وموت أم حرام", "فيها غزا معاوية بن أبي سفيان البحر ومعه عبادة بن الصامت، وامرأته أم حرام بنت ملحان - أخت أم سليم - فسقطت عن دابة لها فهلكت. وهي التي نام رسول الله صلى الله عليه وسلم في بيتها وقت قيلولة. فاستيقظ وهو يضحك فسألته؟ فقال: «ناس من أمتي عرضوا علي غزاة في سبيل الله، يركبون ثبج البحر ملوكا على الأسرة - أو كالملوك على الأسرة - فقالت: ادع الله أن يجعلني منهم. فقال: أنت منهم. ثم نام. ثم استيقظ وهو يضحك فسألته؟ فقال مثل قوله. فقالت: ادع الله أن يجعلني منهم. فقال: أنت من الأولين» .", 311, 621], ["غزو قبرس", "وفيها: غزا معاوية قبرس. فصالحه أهلها.", 312, 622], ["توسعة المسجد النبوي والمسجد الحرام", "فيها: شكا الناس إلى عثمان رضي الله عنه ضيق مسجد رسول الله صلى الله عليه وسلم، فأمر بتوسعته وبناه بالحجارة المنقوشة والقصة - وهي الجص - وفيها وسع المسجد الحرام كذلك.", 312, 624], ["موت سليمان بن ربيعة الباهلي", "وفيها: مات سليمان بن ربيعة الباهلي رضي الله عنه. وكان عمر رضي الله عنه ولاه قضاء المدائن، فمكث أربعين يوما لم يختصم إليه اثنان.", 312, 625], ["سقوط خاتم النبي ﷺ في بئر أريس", "وفيها وقع خاتم رسول الله من يد عثمان بن عفان رضي الله عنه في بئر أريس فنزحت ولم يوجد. فحزن لذلك أشد الحزن. فوقع من الرعية الخلل على عثمان بعدها.", 312, 627], ["غزو سعيد بن العاص خراسان", "وفيها: غزا سعيد بن العاص من الكوفة خراسان، ومعه حذيفة بن اليمان، والحسن، والحسين، وعبد الله بن عمر، وعبد الله بن عمرو بن العاص، وعبد الله بن الزبير رضي الله عنهم.", 312, 628], ["أمر أبي ذر ونزوله الربذة", "فكتب معاوية في شأنه إلى عثمان. فكتب عثمان بإشخاص أبي ذر إلى المدينة، ومحاولة بعض دعاة الفتنة الالتفاف حول أبي ذر. فهرب منهم إلى الربذة بإذن عثمان وفي طاعته. وأقام بها حتى مات رضي الله عنه.", 313, 629], ["زيادة النداء الثالث يوم الجمعة", "وفيها: زاد عثمان النداء الثالث يوم الجمعة على الزوراء حين كثر الناس. فثبت الأمر على ذلك إلى اليوم. والزوراء دار كانت له بالمدينة. وفيها: مات أبي بن كعب: سيد القراء وأحد القراء الأربعة.", 313, 630], ["موت أبي بن كعب", "وفيها: زاد عثمان النداء الثالث يوم الجمعة على الزوراء حين كثر الناس. فثبت الأمر على ذلك إلى اليوم. والزوراء دار كانت له بالمدينة. وفيها: مات أبي بن كعب: سيد القراء وأحد القراء الأربعة.", 313, 631], ["قتل يزدجرد آخر ملوك الفرس", "وفيها: قتل يزدجرد آخر ملوك الفرس، وهو الذي مزق كتاب رسول الله صلى الله عليه وسلم الذي دعاه فيه إلى الإسلام. فدعا عليه أن يمزق الله ملكه. وفيها: فتح حبيب بن مسلمة الفهري أرمينية.", 313, 633], ["فتح أرمينية", "وفيها: قتل يزدجرد آخر ملوك الفرس، وهو الذي مزق كتاب رسول الله صلى الله عليه وسلم الذي دعاه فيه إلى الإسلام. فدعا عليه أن يمزق الله ملكه. وفيها: فتح حبيب بن مسلمة الفهري أرمينية.", 313, 634], ["غزوة الصواري", "وقال الواقدي: كان في هذه السنة غزوة الصواري في البحر. وكان فيها: محمد بن أبي حذيفة ومحمد بن أبي بكر. فأظهرا عيب عثمان وما غير وما خالف أبا بكر وعمر. ويقولان دمه حلال.", 313, 635], ["غزو معاوية بلاد الروم", "فيها: غزا معاوية بلاد الروم، حتى بلغ مضيق القسطنطينية. وفيها: مات عبد الرحمن بن عوف وعبد الله بن مسعود، وسلمان الفارسي وأبو ذر الغفاري - جندب بن جنادة - والعباس بن عبد المطلب، وأبو سفيان بن حرب رضي الله عنهم.", 314, 637], ["وفيات", "فيها: غزا معاوية بلاد الروم، حتى بلغ مضيق القسطنطينية. وفيها: مات عبد الرحمن بن عوف وعبد الله بن مسعود، وسلمان الفارسي وأبو ذر الغفاري - جندب بن جنادة - والعباس بن عبد المطلب، وأبو سفيان بن حرب رضي الله عنهم.", 314, 638], ["نفي الطاعنين على عثمان من أهل العراق", "وفيها: ذكر أهل العراق عثمان بالسوء وتكلموا فيه بكلام خبيث في مجلس سعيد بن عامر فكتب في أمرهم إلى عثمان. فكتب يأمره بإجلائهم إلى الشام. فلما قدموا على معاوية أكرمهم وتألفهم. ونصحهم. فأجابه متكلمهم بكلام فيه شناعة. ثم نصحهم فتمادوا في غيهم وجهالتهم وشرهم. فنفاهم معاوية عن الشام، وكانوا عشرة: كميل بن زياد، والأشتر النخعي - مالك بن يزيد -، وعلقمة بن قيس النخعي، وثابت بن قيس النخعي، وجندب بن زهير العامري، وجندب بن كعب الأزدي، وعروة بن الجعد، وعمرو بن الحمق الخزاعي، وصعصعة بن صوحان، وأخوه زيد بن صوحان، وابن الكواء. فأووا إلى الجزيرة. واستقروا بحمص حتى كانت الفتنة التي قادوها لقتل عثمان.", 314, 640], ["موت المقداد بن عمرو", "وفيها: مات المقداد بن عمرو رضي الله عنه.", 314, 641], ["تكاتب المنحرفين عن عثمان", "فيها: تكاتب المنحرفون عن عثمان - وكان جمهورهم من أهل الكوفة - وتواعدوا أن يجتمعوا لمناظرته فيما نقموا عليه. فبعثوا إليه منهم من يناظره فيما فعل من تولية من ولى وعزل من عزل. حتى شق عليه ذلك جدا، فبعث إلى أمراء الأجناد فأحضرهم عنده. واستشارهم. فكل أشار برأي ثم انتهى الأمر بأن قرر عماله على ما كانوا عليه. وتألف قلوب هؤلاء، وأمر بهم أن يبعثوا إلى الغزو وإلى الثغور. فلم يمنعهم ذلك من التمادي في غيهم.", 315, 643], ["وفيات", "وفيها: توفي أبو طلحة الأنصاري، وعبادة بن الصامت رضي الله عنهما.", 315, 644], ["موت عمار بن ربيعة", "وفيها: مات من الصحابة عمار بن ربيعة أسلم قديما وشهد بدرا رضي الله عنه.", 315, 646], ["خروج أهل مصر على عثمان", "وفيها: كان خروج جماعة من أهل مصر ومن وافقهم على عثمان. وأصل الفتنة ومنبعها: كان من عبد الله بن سبأ - رجل يهودي من أهل صنعاء، أظهر الإسلام ليخفي به حقده عليه وكفره به في زمن عثمان - وكان ينتقل في بلدان المسلمين يحاول ضلالتهم. فبدأ بالحجاز، ثم البصرة، ثم الكوفة ثم الشام. فلم يقدر على ما يريد. فأخرجوه حتى أتى مصر فغمز على عثمان وقاد الفتنة. وأشعل نارها، محادة لله ولرسوله حتى كانت البلية الكبرى بمحاصرة عثمان رضي الله عنه واغتياله وهو يتلو كتاب الله تعالى، وكان بيد أولئك المجرمين الخوارج في ذي الحجة من هذه السنة. رضي الله عنه.", 315, 647], ["مقتل عثمان رضي الله عنه", "وفيها: كان خروج جماعة من أهل مصر ومن وافقهم على عثمان. وأصل الفتنة ومنبعها: كان من عبد الله بن سبأ - رجل يهودي من أهل صنعاء، أظهر الإسلام ليخفي به حقده عليه وكفره به في زمن عثمان - وكان ينتقل في بلدان المسلمين يحاول ضلالتهم. فبدأ بالحجاز، ثم البصرة، ثم الكوفة ثم الشام. فلم يقدر على ما يريد. فأخرجوه حتى أتى مصر فغمز على عثمان وقاد الفتنة. وأشعل نارها، محادة لله ولرسوله حتى كانت البلية الكبرى بمحاصرة عثمان رضي الله عنه واغتياله وهو يتلو كتاب الله تعالى، وكان بيد أولئك المجرمين الخوارج في ذي الحجة من هذه السنة. رضي الله عنه.", 315, 648], ["بيعة علي بن أبي طالب", "قال أهل السير: لما كان من أمر عثمان ما كان قعد علي بن أبي طالب في بيته فأتاه الناس وهم يقولون: علي أمير المؤمنين. فقال: ليس ذلك إليكم إنما هو إلى أهل بدر. فأتاه أهل بدر. فلما رأى ذلك علي خرج فبايعه الناس. ولم يدخل في طاعته معاوية وأهل الشام. فهم علي بالشخوص إليهم (1) .", 316, 649], ["خروج عائشة وطلحة والزبير إلى البصرة", "وبلغ الخبر عائشة - وهي حاجة - ومعها طلحة، والزبير. فخرجوا إلى البصرة يريدون الإصلاح بين الناس واجتماع الكلمة. وأرسل علي عمار بن ياسر وابنه الحسن بن علي إلى الكوفة يستنفرون الناس ليكونوا مع علي فاستنفروهم. فنفروا.", 316, 651], ["وقعة الجمل", "وخرج علي من المدينة في ستمائة رجل. فالتقى - هو والحسن - بذي قار ثم التقوا - هم وطلحة والزبير - قرب البصرة وكان في العسكرين ناس من الخوارج. فخافوا من تمالؤ العسكرين عليهم. فتحيلوا حتى أثاروا الحرب بينهما من غير رأي. فكانت وقعة الجمل المشهورة لأن عائشة كانت في هودج. على جمل. وعقر الجمل ذلك اليوم. فأمر علي بحمل الهودج فحمله محمد بن أبي بكر، وعمار بن ياسر. فأدخل محمد يده في الهودج فقالت من ذا الذي يتعرض لحرم رسول الله صلى الله عليه وسلم؟ أحرقه الله بالنار. فقال: يا أختاه قولي بنار الدنيا. فقالت: بنار الدنيا، فكان الأمر كذلك.", 317, 652], ["رد عائشة إلى المدينة", "ثم التقى علي وعائشة. فاعتذر كل منهما للآخر. ثم جهزها إلى المدينة. وأمر لها بكل شيء ينبغي لها. وأرسل معها أربعين امرأة من نساء أهل البصرة المعروفات.", 317, 653], ["وفيات", "وفي هذه السنة: مات حذيفة بن اليمان، وأبو رافع مولى رسول الله صلى الله عليه وسلم وقدامة بن مظعون رضي الله عنهم.", 317, 654], ["وقعة صفين", "فسار علي رضي الله عنه والتقى هو وأهل الشام بصفين لسبع بقين من المحرم - وصفين اسم موضع بين الشام والعراق - فكانت به الوقعة المشهورة. فلما اشتد البلاء على الفريقين وطال أياما، وكثر القتلى بينهم رفع أهل الشام المصاحف على رؤوس الرماح ونادوا \" ندعوكم إلى كتاب الله \" فسر الناس وأنابوا إلى الحكومة.", 317, 656], ["رفع المصاحف والتحكيم", "فسار علي رضي الله عنه والتقى هو وأهل الشام بصفين لسبع بقين من المحرم - وصفين اسم موضع بين الشام والعراق - فكانت به الوقعة المشهورة. فلما اشتد البلاء على الفريقين وطال أياما، وكثر القتلى بينهم رفع أهل الشام المصاحف على رؤوس الرماح ونادوا \" ندعوكم إلى كتاب الله \" فسر الناس وأنابوا إلى الحكومة.", 317, 657], ["اجتماع الحكمين بأذرح", "فلما حل الموعد في رمضان توافوا بأذرح، بدومة الجندل. فلم يتفق الحكمان على شيء.", 318, 658], ["خروج الخوارج بحروراء", "فلما وصل علي الكوفة خرجت عليه الخوارج ; وكفروه حيث رضي بالتحكيم. وقالوا: لا حكم إلا لله. واجتمعوا بحروراء - اسم موضع بالعراق - فسموا الحرورية، فأرسل علي إليهم عبد الله بن عباس فأتاهم. قال: \" فلم أر قوما أسمد اجتهادا منهم ولا أكثر عبادة \" فقال ما تنقمون؟ قالوا: ثلاث.", 318, 659], ["مناظرة ابن عباس للخوارج", "فلما وصل علي الكوفة خرجت عليه الخوارج ; وكفروه حيث رضي بالتحكيم. وقالوا: لا حكم إلا لله. واجتمعوا بحروراء - اسم موضع بالعراق - فسموا الحرورية، فأرسل علي إليهم عبد الله بن عباس فأتاهم. قال: \" فلم أر قوما أسمد اجتهادا منهم ولا أكثر عبادة \" فقال ما تنقمون؟ قالوا: ثلاث.", 318, 660], ["قتال علي للخوارج", "فرجع منهم أربعة آلاف، وخرج عليه باقيهم. فقاتلوه فقتل منهم مقتلة عظيمة. وأمر بالتماس المخدج ذي الثدية. فلما وجده سجد لله شكرا.", 320, 661], ["وفيات", "وفي هذه السنة مات خباب بن الأرت، وخزيمة ذو الشهادتين وسفينة مولى رسول الله صلى الله عليه وسلم وعبد الله بن سعد بن أبي السرح رضي الله عنهم.", 320, 662], ["قتل محمد بن أبي بكر", "فيها: قتل محمد بن أبي بكر وأحرق.", 320, 664], ["وفيات", "وفيها: مات سهل بن حنيف، وصهيب الرومي.", 320, 665], ["الصلح بين علي ومعاوية", "وفيها: كتب معاوية إلى علي: \" أما إذا شئت فلك العراق. ولي الشام. ونكف السيف عن هذه الأمة. ولا نهريق دماء المسلمين \" ففعل. وتراضيا رضي الله عنهما على ذلك.", 321, 667], ["مقتل علي رضي الله عنه", "وفيها: قتل علي رضي الله عنه. قتله ابن ملجم - رجل من الخوارج - لما خرج لصلاة الصبح لثلاث عشرة ليلة بقيت من رمضان.", 321, 668], ["بيعة الحسن بن علي", "فبايع الناس ابنه الحسن. فبقي خليفة نحو سبعة أشهر. ثم سار إلى معاوية. فلما التقى الجمعان علم الحسن أن لن تغلب إحدى الفئتين حتى يذهب أكثر الأخرى. فصالح معاوية. وترك الأمر له وبايعه على أشياء اشترطها. فأعطاه معاوية إياها وأضعافها.", 321, 669], ["صلح الحسن ومعاوية", "فبايع الناس ابنه الحسن. فبقي خليفة نحو سبعة أشهر. ثم سار إلى معاوية. فلما التقى الجمعان علم الحسن أن لن تغلب إحدى الفئتين حتى يذهب أكثر الأخرى. فصالح معاوية. وترك الأمر له وبايعه على أشياء اشترطها. فأعطاه معاوية إياها وأضعافها.", 321, 670]];
